select ac_cargar_unidad($ac${"slug":"aire-suelo-1","rama":"aire_suelo","orden":1,"nivel":1,"titulo_es":"El aire que respirás","bajada_es":"Respirás unos 11.000 litros de aire por día. De qué está hecho, qué lo ensucia, cómo afecta tu salud y cómo se mide.","objetivos_es":["Describir la composición del aire y las capas de la atmósfera","Identificar los principales contaminantes del aire y sus fuentes","Relacionar la contaminación del aire con la salud según la OMS","Interpretar mediciones e índices de calidad del aire","Reconocer los riesgos del aire interior, en especial el monóxido de carbono"],"repasa":["tronco-2"],"requiere_tronco":1,"fuentes":["oms-calidad-aire","oms-aire-exterior","oms-aire-hogar","noaa-co2","epa","ncse-ozono"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"aire-suelo-1.s1","orden":1,"tipo":"leccion","titulo_es":"De qué está hecho el aire","bajada_es":"Nitrógeno, oxígeno, un poco de argón y una pizca de CO₂: la mezcla que nos rodea y las capas de la atmósfera.","minutos":12,"pasos":[{"slug":"aire-suelo-1.s1.p1","orden":1,"grupo":"aire-suelo-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una mezcla de gases","cuerpo":["El aire seco es una mezcla: alrededor del 78 % es nitrógeno, el 21 % oxígeno y casi el 1 % argón. El dióxido de carbono es una parte muy chica, hoy algo más de 0,04 % (más de 420 partes por millón). Además hay vapor de agua, en cantidad variable, y partículas en suspensión.","Que el CO₂ sea una parte tan chica no quiere decir que no importe: pequeñas cantidades de algunos gases tienen efectos enormes sobre el clima, como viste en el tronco."],"datos":{"tipo":"barras","titulo":"Composición del aire seco","unidad":"% del volumen","filas":[{"etiqueta":"Nitrógeno","valor":78.1},{"etiqueta":"Oxígeno","valor":20.9},{"etiqueta":"Argón","valor":0.93},{"etiqueta":"Dióxido de carbono","valor":0.04}],"nota":"Valores aproximados. El vapor de agua varía entre casi 0 y 4 % según el lugar y el momento."}},"solucion":{}},{"slug":"aire-suelo-1.s1.p2","orden":2,"grupo":"aire-suelo-1.s1.p2","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos gases por su proporción en el aire seco, de más a menos.","items":[{"id":"i1","texto":"Nitrógeno"},{"id":"i2","texto":"Oxígeno"},{"id":"i3","texto":"Argón"},{"id":"i4","texto":"Dióxido de carbono"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El gas que más respiramos no es el oxígeno: es el nitrógeno, que entra y sale de los pulmones sin cambios.","valores":{"i1":"≈ 78 %","i2":"≈ 21 %","i3":"≈ 0,9 %","i4":"≈ 0,04 %"}}},{"slug":"aire-suelo-1.s1.p3","orden":3,"grupo":"aire-suelo-1.s1.p3","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas partes por millón (ppm) de CO₂ tiene hoy el aire del planeta.","min":100,"max":1000,"paso":5,"unidad":"ppm","escala":"lineal"},"solucion":{"valor":425,"banda":"lineal","explicacion":"Más de 420 ppm, según las mediciones de la NOAA en Mauna Loa. Antes de la Revolución Industrial eran unas 280 ppm."}},{"slug":"aire-suelo-1.s1.p4","orden":4,"grupo":"aire-suelo-1.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Partes por millón","cuerpo":["Para gases que están en cantidades chicas se usa la unidad partes por millón (ppm): cuántas moléculas de ese gas hay en un millón de moléculas de aire. 420 ppm de CO₂ significa 420 moléculas de CO₂ por cada millón de moléculas de aire, o sea 0,042 %.","Para pasar de ppm a porcentaje se divide por 10.000."]},"solucion":{}},{"slug":"aire-suelo-1.s1.p5","orden":5,"grupo":"aire-suelo-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aire tiene 420 ppm de CO₂. ¿A qué porcentaje equivale?","unidad":"%","decimales":3},"solucion":{"valor":0.042,"tolerancia":0.00084,"explicacion":"420 ÷ 10.000 = 0,042 %. Las ppm son cómodas para cantidades tan chicas."}},{"slug":"aire-suelo-1.s1.p5.v2","orden":5,"grupo":"aire-suelo-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aire tiene 280 ppm de CO₂. ¿A qué porcentaje equivale?","unidad":"%","decimales":3},"solucion":{"valor":0.028,"tolerancia":0.0005600000000000001,"explicacion":"280 ÷ 10.000 = 0,028 %. Las ppm son cómodas para cantidades tan chicas."}},{"slug":"aire-suelo-1.s1.p5.v3","orden":5,"grupo":"aire-suelo-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aire tiene 1.000 ppm de CO₂. ¿A qué porcentaje equivale?","unidad":"%","decimales":3},"solucion":{"valor":0.1,"tolerancia":0.002,"explicacion":"1.000 ÷ 10.000 = 0,1 %. Las ppm son cómodas para cantidades tan chicas."}},{"slug":"aire-suelo-1.s1.p6","orden":6,"grupo":"aire-suelo-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las capas de la atmósfera","cuerpo":["La atmósfera tiene capas. La más baja, la troposfera, llega hasta unos 10 a 15 kilómetros de altura: ahí está casi todo el aire que respiramos, las nubes y el clima. Encima está la estratosfera, donde se encuentra la capa de ozono, que filtra buena parte de la radiación ultravioleta del sol.","El ozono es bueno allá arriba, porque nos protege, pero es un contaminante cuando se forma cerca del suelo, como vas a ver en esta unidad."]},"solucion":{}},{"slug":"aire-suelo-1.s1.p7","orden":7,"grupo":"aire-suelo-1.s1.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada capa o componente con su característica.","izquierda":[{"id":"a1","texto":"Troposfera"},{"id":"a2","texto":"Estratosfera"},{"id":"a3","texto":"Capa de ozono"},{"id":"a4","texto":"Vapor de agua"}],"derecha":[{"id":"b1","texto":"Capa donde ocurre el clima"},{"id":"b2","texto":"Capa donde está la capa de ozono"},{"id":"b3","texto":"Filtra la radiación ultravioleta"},{"id":"b4","texto":"Componente variable que forma nubes"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La atmósfera es fina comparada con la Tierra, pero cada capa cumple una función."}},{"slug":"aire-suelo-1.s1.p8","orden":8,"grupo":"aire-suelo-1.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El ozono es siempre bueno para la vida.","razones":[{"id":"r1","texto":"Porque cerca del suelo es un contaminante"},{"id":"r2","texto":"Porque el ozono no existe en la atmósfera"},{"id":"r3","texto":"Porque el ozono solo se encuentra dentro de las casas"}]},"solucion":{"valor":false,"explicacion":"En la estratosfera nos protege de la radiación ultravioleta. Cerca del suelo, en cambio, es un contaminante que irrita los pulmones y daña cultivos.","clave":["r1"]}},{"slug":"aire-suelo-1.s1.p9","orden":9,"grupo":"aire-suelo-1.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Respirar mucho aire","cuerpo":["Una persona adulta en reposo respira unas 12 a 16 veces por minuto, moviendo alrededor de medio litro de aire en cada respiración. En un día, eso suma del orden de 10.000 a 12.000 litros de aire, y mucho más si hace ejercicio.","Por eso, aunque un contaminante esté en cantidades chicas, a lo largo del día entra mucho en los pulmones."]},"solucion":{}},{"slug":"aire-suelo-1.s1.p10","orden":10,"grupo":"aire-suelo-1.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona respira 12 veces por minuto y mueve 0,5 litros de aire en cada respiración. ¿Cuántos litros respira en un día de 1.440 minutos?","unidad":"litros","decimales":0},"solucion":{"valor":8640,"tolerancia":172.8,"explicacion":"12 × 0,5 × 1.440 = 8.640 litros por día. Un volumen enorme que pasa por los pulmones todos los días."}},{"slug":"aire-suelo-1.s1.p10.v2","orden":10,"grupo":"aire-suelo-1.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona respira 15 veces por minuto y mueve 0,5 litros de aire en cada respiración. ¿Cuántos litros respira en un día de 1.440 minutos?","unidad":"litros","decimales":0},"solucion":{"valor":10800,"tolerancia":216,"explicacion":"15 × 0,5 × 1.440 = 10.800 litros por día. Un volumen enorme que pasa por los pulmones todos los días."}},{"slug":"aire-suelo-1.s1.p10.v3","orden":10,"grupo":"aire-suelo-1.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona respira 16 veces por minuto y mueve 0,5 litros de aire en cada respiración. ¿Cuántos litros respira en un día de 1.440 minutos?","unidad":"litros","decimales":0},"solucion":{"valor":11520,"tolerancia":230.4,"explicacion":"16 × 0,5 × 1.440 = 11.520 litros por día. Un volumen enorme que pasa por los pulmones todos los días."}},{"slug":"aire-suelo-1.s1.p11","orden":11,"grupo":"aire-suelo-1.s1.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hay en el aire además de gases? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Polvo y partículas finas"},{"id":"o2","texto":"Polen"},{"id":"o3","texto":"Gotas de agua en las nubes"},{"id":"o4","texto":"Hollín de la combustión"},{"id":"o5","texto":"Nada, el aire es solo gas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las partículas suspendidas en el aire son parte de lo que respiramos, y algunas son muy dañinas."}},{"slug":"aire-suelo-1.s1.p12","orden":12,"grupo":"aire-suelo-1.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El aire tiene alrededor de 21 % de oxígeno."},{"id":"s2","texto":"El gas más abundante del aire es el oxígeno."},{"id":"s3","texto":"El CO₂ está en una proporción muy chica, más de 420 ppm."},{"id":"s4","texto":"Como el CO₂ es tan poco, no puede afectar el clima."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Poco no quiere decir sin importancia: la dosis y el efecto no siempre van juntos.","por_opcion":{"s2":"El más abundante es el nitrógeno, con alrededor del 78 %.","s4":"Pequeñas cantidades de gases de efecto invernadero tienen grandes efectos."}}},{"slug":"aire-suelo-1.s1.p13","orden":13,"grupo":"aire-suelo-1.s1.p13","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá hasta qué altura aproximada llega la troposfera, la capa donde está casi todo el aire que respiramos.","min":1,"max":100,"paso":1,"unidad":"km","escala":"lineal"},"solucion":{"valor":12,"banda":"lineal","explicacion":"Entre unos 10 y 15 kilómetros, según la latitud. Si la Tierra fuera una pelota de fútbol, esa capa tendría el grosor de un par de hojas de papel."}},{"slug":"aire-suelo-1.s1.p14","orden":14,"grupo":"aire-suelo-1.s1.p14","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos gases del aire son de efecto invernadero? Marcá todos.","opciones":[{"id":"o1","texto":"Dióxido de carbono"},{"id":"o2","texto":"Vapor de agua"},{"id":"o3","texto":"Metano"},{"id":"o4","texto":"Nitrógeno"},{"id":"o5","texto":"Argón"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los gases más abundantes, nitrógeno y oxígeno, no retienen calor. Los que sí lo hacen están en cantidades chicas, como viste en el tronco."}},{"slug":"aire-suelo-1.s1.p15","orden":15,"grupo":"aire-suelo-1.s1.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El aire seco tiene alrededor de 78 % de {{0}} y 21 % de {{1}}; el CO₂ se mide en partes por {{2}}.","banco":[{"id":"w1","texto":"nitrógeno"},{"id":"w2","texto":"oxígeno"},{"id":"w3","texto":"millón"},{"id":"w4","texto":"hidrógeno"},{"id":"w5","texto":"ozono"},{"id":"w6","texto":"litro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La composición del aire, resumida en una línea."}}]},{"slug":"aire-suelo-1.s2","orden":2,"tipo":"leccion","titulo_es":"Qué ensucia el aire","bajada_es":"Partículas, óxidos de nitrógeno, ozono y monóxido: los contaminantes principales y de dónde salen.","minutos":11,"pasos":[{"slug":"aire-suelo-1.s2.p1","orden":1,"grupo":"aire-suelo-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los contaminantes principales","cuerpo":["La Organización Mundial de la Salud sigue varios contaminantes clave. El material particulado (PM), formado por partículas diminutas de polvo, hollín y otras sustancias: el PM10 tiene partículas de menos de 10 micrómetros y el PM2,5, de menos de 2,5 micrómetros, tan chicas que llegan al fondo de los pulmones y a la sangre.","También el dióxido de nitrógeno (NO₂), que sale sobre todo de los motores; el ozono de superficie (O₃), que se forma con sol a partir de otros contaminantes; el dióxido de azufre (SO₂), de combustibles con azufre; y el monóxido de carbono (CO), de combustiones incompletas."]},"solucion":{}},{"slug":"aire-suelo-1.s2.p2","orden":2,"grupo":"aire-suelo-1.s2.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada contaminante con su fuente principal en una ciudad.","izquierda":[{"id":"a1","texto":"Dióxido de nitrógeno (NO₂)"},{"id":"a2","texto":"Material particulado (PM2,5)"},{"id":"a3","texto":"Ozono de superficie"},{"id":"a4","texto":"Dióxido de azufre (SO₂)"}],"derecha":[{"id":"b1","texto":"Motores de autos, colectivos y camiones"},{"id":"b2","texto":"Hollín de motores diésel, quemas y polvo"},{"id":"b3","texto":"Reacciones con sol entre otros contaminantes"},{"id":"b4","texto":"Combustibles con azufre en industrias"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El tránsito aparece en casi todos. Por eso el aire suele ser peor en las avenidas."}},{"slug":"aire-suelo-1.s2.p3","orden":3,"grupo":"aire-suelo-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué tan chico es chico","cuerpo":["Un micrómetro es la milésima parte de un milímetro. Un pelo humano mide unos 50 a 70 micrómetros de diámetro. Una partícula de PM2,5 es unas 20 a 30 veces más fina que un pelo.","Cuanto más chica es la partícula, más profundo llega en el cuerpo: las PM10 quedan en la nariz y los bronquios; las PM2,5 llegan a los alvéolos y pueden pasar a la sangre."]},"solucion":{}},{"slug":"aire-suelo-1.s2.p4","orden":4,"grupo":"aire-suelo-1.s2.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená por tamaño, de más grande a más chico.","items":[{"id":"i1","texto":"Un grano de arena fina"},{"id":"i2","texto":"Un pelo humano"},{"id":"i3","texto":"Una partícula PM10"},{"id":"i4","texto":"Una partícula PM2,5"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las partículas más peligrosas son invisibles una por una. Se ven solo cuando hay muchísimas, como smog.","valores":{"i1":"≈ 100 micrómetros","i2":"≈ 50-70 micrómetros","i3":"menos de 10 micrómetros","i4":"menos de 2,5 micrómetros"}}},{"slug":"aire-suelo-1.s2.p5","orden":5,"grupo":"aire-suelo-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pelo mide 60 micrómetros de diámetro. ¿Cuántas veces más fino es una partícula de 2,5 micrómetros?","unidad":"veces","decimales":0},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"60 ÷ 2,5 = 24 veces. Por eso las PM2,5 pasan las defensas de la nariz y llegan al fondo de los pulmones."}},{"slug":"aire-suelo-1.s2.p5.v2","orden":5,"grupo":"aire-suelo-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pelo mide 70 micrómetros de diámetro. ¿Cuántas veces más fino es una partícula de 2,5 micrómetros?","unidad":"veces","decimales":0},"solucion":{"valor":28,"tolerancia":0.56,"explicacion":"70 ÷ 2,5 = 28 veces. Por eso las PM2,5 pasan las defensas de la nariz y llegan al fondo de los pulmones."}},{"slug":"aire-suelo-1.s2.p5.v3","orden":5,"grupo":"aire-suelo-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pelo mide 50 micrómetros de diámetro. ¿Cuántas veces más fino es una partícula de 2,5 micrómetros?","unidad":"veces","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"50 ÷ 2,5 = 20 veces. Por eso las PM2,5 pasan las defensas de la nariz y llegan al fondo de los pulmones."}},{"slug":"aire-suelo-1.s2.p6","orden":6,"grupo":"aire-suelo-1.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las fuentes","cuerpo":["En las ciudades, la fuente más importante suele ser el tránsito, sobre todo los motores diésel viejos. También aportan las industrias, la generación de electricidad con combustibles fósiles, la calefacción, la quema de basura y de residuos de poda, y las obras. En zonas rurales y en algunas regiones del país pesan las quemas de pastizales y los incendios.","Muchas de estas fuentes son las mismas que emiten gases de efecto invernadero: cuidar el aire y cuidar el clima suelen ir juntos."]},"solucion":{}},{"slug":"aire-suelo-1.s2.p7","orden":7,"grupo":"aire-suelo-1.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una fuente de contaminación del aire exterior o interior?","grupos":[{"id":"g1","nombre":"Exterior"},{"id":"g2","nombre":"Interior"}],"items":[{"id":"i1","texto":"Colectivo diésel viejo"},{"id":"i2","texto":"Estufa a leña sin buena salida"},{"id":"i3","texto":"Quema de basura en un baldío"},{"id":"i4","texto":"Humo de cigarrillo dentro de casa"},{"id":"i5","texto":"Chimenea de una fábrica"},{"id":"i6","texto":"Calefón mal instalado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El aire de adentro también se contamina, y ahí pasamos la mayor parte del día."}},{"slug":"aire-suelo-1.s2.p8","orden":8,"grupo":"aire-suelo-1.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se forma el ozono de superficie en un día de verano.","items":[{"id":"i1","texto":"Los autos emiten óxidos de nitrógeno y otros gases"},{"id":"i2","texto":"El sol fuerte ilumina esos gases"},{"id":"i3","texto":"Reaccionan y forman ozono cerca del suelo"},{"id":"i4","texto":"El ozono irrita los pulmones de quienes respiran ese aire"},{"id":"i5","texto":"El ozono baja desde la estratosfera a las calles"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Por eso el ozono de superficie suele ser peor en días soleados y calurosos, a la tarde."}},{"slug":"aire-suelo-1.s2.p9","orden":9,"grupo":"aire-suelo-1.s2.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuidar el aire y cuidar el clima no tienen nada que ver.","razones":[{"id":"r1","texto":"Porque muchas fuentes contaminan el aire y emiten gases de efecto invernadero"},{"id":"r2","texto":"Porque el aire y el clima son lo mismo"},{"id":"r3","texto":"Porque el CO₂ es el principal contaminante que respiramos"}]},"solucion":{"valor":false,"explicacion":"Muchas fuentes de contaminación del aire —motores, centrales a carbón o gas, quemas— son también fuentes de gases de efecto invernadero. Reducirlas ayuda a los dos.","clave":["r1"]}},{"slug":"aire-suelo-1.s2.p10","orden":10,"grupo":"aire-suelo-1.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas acciones reducen la contaminación del aire en una ciudad? Marcá todas.","opciones":[{"id":"o1","texto":"Renovar colectivos diésel viejos por eléctricos"},{"id":"o2","texto":"Prohibir la quema de basura y de restos de poda"},{"id":"o3","texto":"Más ciclovías y transporte público"},{"id":"o4","texto":"Controlar las emisiones de las industrias"},{"id":"o5","texto":"Ensanchar avenidas para que entren más autos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Más autos suelen ser más contaminación. Las demás medidas atacan las fuentes."}},{"slug":"aire-suelo-1.s2.p11","orden":11,"grupo":"aire-suelo-1.s2.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el aire suele estar más contaminado en una avenida con mucho tránsito que en una plaza a dos cuadras?","opciones":[{"id":"o1","texto":"Porque los motores emiten justo ahí"},{"id":"o2","texto":"Porque en las plazas hay más oxígeno puro"},{"id":"o3","texto":"Porque los árboles de la plaza absorben todos los contaminantes"},{"id":"o4","texto":"Porque en las avenidas hace más frío"}]},"solucion":{"clave":["o1"],"explicacion":"La concentración es mayor cerca de la fuente. Caminar por calles paralelas a las avenidas reduce lo que se respira.","por_opcion":{"o3":"Ayudan un poco, pero la diferencia principal es la cercanía a la fuente."}}},{"slug":"aire-suelo-1.s2.p12","orden":12,"grupo":"aire-suelo-1.s2.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las partículas PM2,5 son más finas que un pelo."},{"id":"s2","texto":"El CO₂ es el contaminante que más daña los pulmones en la calle."},{"id":"s3","texto":"Los motores diésel viejos emiten mucho hollín."},{"id":"s4","texto":"El ozono solo existe en la estratosfera."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Contaminantes del aire y gases de efecto invernadero se superponen, pero no son lo mismo.","por_opcion":{"s2":"El CO₂ afecta el clima; en la calle, los más dañinos para la salud son las partículas, el NO₂ y el ozono.","s4":"También se forma cerca del suelo, donde es un contaminante."}}},{"slug":"aire-suelo-1.s2.p13","orden":13,"grupo":"aire-suelo-1.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las partículas {{0}} son tan chicas que llegan a la sangre; el {{1}} sale sobre todo de los motores; y el ozono de superficie se forma con {{2}}.","banco":[{"id":"w1","texto":"PM2,5"},{"id":"w2","texto":"NO₂"},{"id":"w3","texto":"sol"},{"id":"w4","texto":"PM100"},{"id":"w5","texto":"CO₂"},{"id":"w6","texto":"lluvia"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres contaminantes clave del aire urbano, con sus rasgos."}}]},{"slug":"aire-suelo-1.s3","orden":3,"tipo":"leccion","titulo_es":"Aire y salud","bajada_es":"Por qué la OMS considera la contaminación del aire uno de los mayores riesgos ambientales para la salud.","minutos":11,"pasos":[{"slug":"aire-suelo-1.s3.p1","orden":1,"grupo":"aire-suelo-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un riesgo enorme","cuerpo":["Según la Organización Mundial de la Salud, la contaminación del aire exterior y la del aire de los hogares, juntas, se asocian con unos 7 millones de muertes prematuras por año en el mundo. Además, casi toda la población mundial —alrededor del 99 %— vive en lugares donde el aire supera los valores guía de la OMS.","La contaminación del aire aumenta el riesgo de enfermedades respiratorias como el asma y la EPOC, de infartos, de accidentes cerebrovasculares y de cáncer de pulmón."],"destacado":{"valor":"≈ 99 %","texto":"de la población mundial vive donde el aire supera los valores guía de la OMS."}},"solucion":{}},{"slug":"aire-suelo-1.s3.p2","orden":2,"grupo":"aire-suelo-1.s3.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas muertes prematuras por año asocia la OMS con la contaminación del aire exterior y doméstico juntas.","min":10000,"max":100000000,"paso":1,"unidad":"muertes","escala":"log"},"solucion":{"valor":7000000,"banda":"log","explicacion":"Alrededor de 7 millones por año. Es uno de los mayores riesgos ambientales para la salud en todo el mundo."}},{"slug":"aire-suelo-1.s3.p3","orden":3,"grupo":"aire-suelo-1.s3.p3","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas de salud se asocian con la contaminación del aire? Marcá todos.","opciones":[{"id":"o1","texto":"Asma y otras enfermedades respiratorias"},{"id":"o2","texto":"Infartos"},{"id":"o3","texto":"Accidentes cerebrovasculares"},{"id":"o4","texto":"Cáncer de pulmón"},{"id":"o5","texto":"Fracturas de huesos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las partículas finas no solo afectan los pulmones: al pasar a la sangre, afectan el corazón y los vasos sanguíneos."}},{"slug":"aire-suelo-1.s3.p4","orden":4,"grupo":"aire-suelo-1.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los valores guía","cuerpo":["En 2021, la OMS actualizó sus directrices de calidad del aire y las hizo más estrictas, porque la evidencia mostró daños incluso con niveles bajos. Para las partículas PM2,5, recomienda no superar un promedio anual de 5 microgramos por metro cúbico (µg/m³) y un promedio diario de 15 µg/m³. Para el NO₂, un promedio anual de 10 µg/m³.","Muchas ciudades del mundo están muy por encima de estos valores. Los países fijan sus propias normas, que suelen ser menos estrictas que las guías de la OMS."],"datos":{"tipo":"tabla","titulo":"Valores guía de la OMS (2021), algunos ejemplos","columnas":["Contaminante","Promedio","Valor guía"],"filas":[["PM2,5","Anual","5 µg/m³"],["PM2,5","Diario (24 h)","15 µg/m³"],["PM10","Anual","15 µg/m³"],["NO₂","Anual","10 µg/m³"]]}},"solucion":{}},{"slug":"aire-suelo-1.s3.p5","orden":5,"grupo":"aire-suelo-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene un promedio anual de PM2,5 de 15 µg/m³. ¿Cuántas veces supera el valor guía anual de la OMS (5 µg/m³)?","unidad":"veces","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"15 ÷ 5 = 3 veces el valor guía. La OMS bajó este valor en 2021 porque la evidencia muestra daños aun en niveles bajos."}},{"slug":"aire-suelo-1.s3.p5.v2","orden":5,"grupo":"aire-suelo-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene un promedio anual de PM2,5 de 25 µg/m³. ¿Cuántas veces supera el valor guía anual de la OMS (5 µg/m³)?","unidad":"veces","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"25 ÷ 5 = 5 veces el valor guía. La OMS bajó este valor en 2021 porque la evidencia muestra daños aun en niveles bajos."}},{"slug":"aire-suelo-1.s3.p5.v3","orden":5,"grupo":"aire-suelo-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene un promedio anual de PM2,5 de 10 µg/m³. ¿Cuántas veces supera el valor guía anual de la OMS (5 µg/m³)?","unidad":"veces","decimales":0},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"10 ÷ 5 = 2 veces el valor guía. La OMS bajó este valor en 2021 porque la evidencia muestra daños aun en niveles bajos."}},{"slug":"aire-suelo-1.s3.p6","orden":6,"grupo":"aire-suelo-1.s3.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el aire de una ciudad cumple la norma de su país, seguro cumple con las guías de la OMS.","razones":[{"id":"r1","texto":"Porque las normas nacionales suelen ser menos estrictas"},{"id":"r2","texto":"Porque la OMS no publica valores guía"},{"id":"r3","texto":"Porque todas las normas del mundo son idénticas"}]},"solucion":{"valor":false,"explicacion":"Las normas nacionales suelen ser menos estrictas que las guías de la OMS. Una ciudad puede cumplir su norma y superar igual los valores guía.","clave":["r1"]}},{"slug":"aire-suelo-1.s3.p7","orden":7,"grupo":"aire-suelo-1.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quiénes son más vulnerables","cuerpo":["La contaminación afecta a todos, pero más a los niños (respiran más aire por kilo de peso y sus pulmones se están formando), a las personas mayores, a quienes tienen enfermedades respiratorias o cardíacas y a las embarazadas.","También a quienes viven o trabajan junto a avenidas, industrias o basurales, que muchas veces son los barrios más pobres. Por eso la calidad del aire es también un tema de justicia ambiental."]},"solucion":{}},{"slug":"aire-suelo-1.s3.p8","orden":8,"grupo":"aire-suelo-1.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta persona es más vulnerable a la contaminación del aire o no especialmente?","grupos":[{"id":"g1","nombre":"Más vulnerable"},{"id":"g2","nombre":"No especialmente"}],"items":[{"id":"i1","texto":"Una nena de 4 años"},{"id":"i2","texto":"Un adulto sano que vive lejos de avenidas"},{"id":"i3","texto":"Un abuelo con EPOC"},{"id":"i4","texto":"Una joven sana en una zona con aire limpio"},{"id":"i5","texto":"Una embarazada que vive junto a una avenida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"La vulnerabilidad depende de la edad, la salud y dónde se vive y trabaja."}},{"slug":"aire-suelo-1.s3.p9","orden":9,"grupo":"aire-suelo-1.s3.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino de una partícula PM2,5 en el cuerpo.","items":[{"id":"i1","texto":"Se respira aire con partículas finas"},{"id":"i2","texto":"Las partículas pasan la nariz y los bronquios"},{"id":"i3","texto":"Llegan a los alvéolos de los pulmones"},{"id":"i4","texto":"Algunas pasan a la sangre"},{"id":"i5","texto":"Pueden inflamar vasos sanguíneos y afectar el corazón"},{"id":"i6","texto":"Las partículas se disuelven en la nariz sin efecto"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso la contaminación del aire no es solo un problema respiratorio."}},{"slug":"aire-suelo-1.s3.p10","orden":10,"grupo":"aire-suelo-1.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un día con muy mala calidad del aire, ¿qué conviene para un chico con asma?","opciones":[{"id":"o1","texto":"Evitar el ejercicio intenso al aire libre ese día"},{"id":"o2","texto":"Hacer más ejercicio afuera para fortalecer los pulmones"},{"id":"o3","texto":"Abrir todas las ventanas de la casa"},{"id":"o4","texto":"Quedarse cerca de la avenida para tomar aire"}]},"solucion":{"clave":["o1"],"explicacion":"En días de mala calidad del aire, se recomienda reducir la actividad física intensa al aire libre, sobre todo a los más vulnerables.","por_opcion":{"o3":"Si el aire de afuera está muy contaminado, conviene ventilar en otros momentos."}}},{"slug":"aire-suelo-1.s3.p11","orden":11,"grupo":"aire-suelo-1.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La OMS asocia la contaminación del aire con millones de muertes por año."},{"id":"s2","texto":"La contaminación del aire solo afecta los pulmones."},{"id":"s3","texto":"Los niños son especialmente vulnerables."},{"id":"s4","texto":"Si la ciudad cumple su norma nacional, el aire es perfecto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El aire es un tema de salud pública, y también de justicia.","por_opcion":{"s2":"También afecta el corazón y los vasos sanguíneos.","s4":"Las normas suelen ser menos estrictas que las guías de la OMS."}}},{"slug":"aire-suelo-1.s3.p12","orden":12,"grupo":"aire-suelo-1.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La OMS recomienda que el promedio anual de PM2,5 no supere {{0}} µg/m³; alrededor del {{1}} % de la población vive donde se superan los valores guía.","banco":[{"id":"w1","texto":"5"},{"id":"w2","texto":"99"},{"id":"w3","texto":"50"},{"id":"w4","texto":"9"},{"id":"w5","texto":"1"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos números que muestran el tamaño del problema del aire."}},{"slug":"aire-suelo-1.s3.p13","orden":13,"grupo":"aire-suelo-1.s3.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada grupo con por qué es más vulnerable.","izquierda":[{"id":"a1","texto":"Niños"},{"id":"a2","texto":"Personas mayores"},{"id":"a3","texto":"Personas con asma"},{"id":"a4","texto":"Vecinos de avenidas"}],"derecha":[{"id":"b1","texto":"Respiran más aire por kilo y sus pulmones se están formando"},{"id":"b2","texto":"Suelen tener más enfermedades del corazón o los pulmones"},{"id":"b3","texto":"Sus vías respiratorias reaccionan con más facilidad"},{"id":"b4","texto":"Están más expuestos a los contaminantes"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas razones, mismo resultado: más riesgo con el mismo aire."}}]},{"slug":"aire-suelo-1.s4","orden":4,"tipo":"leccion","titulo_es":"Medir el aire","bajada_es":"Estaciones de monitoreo, microgramos por metro cúbico e índices de colores: cómo leer la calidad del aire.","minutos":11,"pasos":[{"slug":"aire-suelo-1.s4.p1","orden":1,"grupo":"aire-suelo-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se mide","cuerpo":["La calidad del aire se mide con estaciones de monitoreo que toman muestras de aire y miden la concentración de cada contaminante. Las partículas y muchos gases se expresan en microgramos por metro cúbico (µg/m³): cuántos millonésimos de gramo de contaminante hay en un metro cúbico de aire.","Varias ciudades argentinas tienen estaciones de monitoreo y publican sus datos. También existen sensores de bajo costo que usan vecinos y escuelas, menos precisos pero útiles para ver tendencias."]},"solucion":{}},{"slug":"aire-suelo-1.s4.p2","orden":2,"grupo":"aire-suelo-1.s4.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa que el PM2,5 de un día fue 30 µg/m³?","opciones":[{"id":"o1","texto":"30 millonésimos de gramo por metro cúbico"},{"id":"o2","texto":"Que el 30 % del aire eran partículas finas"},{"id":"o3","texto":"Que hubo 30 partículas en toda la ciudad"},{"id":"o4","texto":"Que la temperatura del aire fue de 30 °C"}]},"solucion":{"clave":["o1"],"explicacion":"Microgramos por metro cúbico: masa de contaminante en un volumen de aire.","por_opcion":{"o3":"Es una concentración: masa de partículas por volumen de aire."}}},{"slug":"aire-suelo-1.s4.p3","orden":3,"grupo":"aire-suelo-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los índices de colores","cuerpo":["Como los números de cada contaminante son difíciles de interpretar, muchas ciudades publican un índice de calidad del aire: una escala que resume los contaminantes en un número y un color, de \"bueno\" (verde) a \"peligroso\" (violeta o bordó), con recomendaciones para cada nivel.","Los índices cambian según el país, pero la lógica es la misma: el color dice qué tan preocupante es el aire y qué conviene hacer."]},"solucion":{}},{"slug":"aire-suelo-1.s4.p4","orden":4,"grupo":"aire-suelo-1.s4.p4","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas categorías típicas de un índice de calidad del aire, de mejor a peor.","items":[{"id":"i1","texto":"Buena (verde)"},{"id":"i2","texto":"Moderada (amarilla)"},{"id":"i3","texto":"Dañina para grupos sensibles (naranja)"},{"id":"i4","texto":"Dañina para la salud (roja)"},{"id":"i5","texto":"Muy dañina (violeta)"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada color trae una recomendación. En naranja, los más vulnerables ya deberían cuidarse."}},{"slug":"aire-suelo-1.s4.p5","orden":5,"grupo":"aire-suelo-1.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Promedios que engañan","cuerpo":["Un promedio anual puede ocultar días muy malos. Una ciudad con un promedio aceptable puede tener picos peligrosos en días sin viento, con quemas cercanas o con inversión térmica, cuando una capa de aire caliente encima atrapa la contaminación cerca del suelo.","Por eso se miran promedios diarios, anuales y picos, como viste en el tronco al leer números ambientales."]},"solucion":{}},{"slug":"aire-suelo-1.s4.p6","orden":6,"grupo":"aire-suelo-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En cinco días, el PM2,5 promedio diario fue 10, 12, 8, 60, 10 µg/m³. ¿Cuál es el promedio de los cinco días?","unidad":"µg/m³","decimales":1},"solucion":{"valor":20,"tolerancia":0.4,"explicacion":"(10 + 12 + 8 + 60 + 10) ÷ 5 = 20 µg/m³. Pero un día fue de 60: el promedio esconde el pico."}},{"slug":"aire-suelo-1.s4.p6.v2","orden":6,"grupo":"aire-suelo-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En cinco días, el PM2,5 promedio diario fue 20, 18, 22, 90, 20 µg/m³. ¿Cuál es el promedio de los cinco días?","unidad":"µg/m³","decimales":1},"solucion":{"valor":34,"tolerancia":0.68,"explicacion":"(20 + 18 + 22 + 90 + 20) ÷ 5 = 34 µg/m³. Pero un día fue de 90: el promedio esconde el pico."}},{"slug":"aire-suelo-1.s4.p6.v3","orden":6,"grupo":"aire-suelo-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En cinco días, el PM2,5 promedio diario fue 5, 6, 7, 40, 7 µg/m³. ¿Cuál es el promedio de los cinco días?","unidad":"µg/m³","decimales":1},"solucion":{"valor":13,"tolerancia":0.26,"explicacion":"(5 + 6 + 7 + 40 + 7) ÷ 5 = 13 µg/m³. Pero un día fue de 40: el promedio esconde el pico."}},{"slug":"aire-suelo-1.s4.p7","orden":7,"grupo":"aire-suelo-1.s4.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una inversión térmica empeora el aire.","items":[{"id":"i1","texto":"Una noche fría y sin viento enfría el suelo"},{"id":"i2","texto":"Queda una capa de aire más caliente encima del aire frío"},{"id":"i3","texto":"Esa capa funciona como una tapa"},{"id":"i4","texto":"Los contaminantes no se dispersan hacia arriba"},{"id":"i5","texto":"Se acumulan cerca del suelo y el aire empeora"},{"id":"i6","texto":"El aire caliente de arriba limpia el aire de abajo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es común en invierno en ciudades rodeadas de sierras o en valles."}},{"slug":"aire-suelo-1.s4.p8","orden":8,"grupo":"aire-suelo-1.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el promedio anual de PM2,5 de una ciudad es bajo, nunca hay días de aire malo.","razones":[{"id":"r1","texto":"Porque el promedio puede ocultar picos muy altos"},{"id":"r2","texto":"Porque el promedio anual es el valor de todos los días"},{"id":"r3","texto":"Porque el aire no cambia de un día a otro"}]},"solucion":{"valor":false,"explicacion":"El promedio puede ocultar picos: días sin viento, quemas o inversiones térmicas pueden tener niveles muy altos aunque el promedio sea aceptable.","clave":["r1"]}},{"slug":"aire-suelo-1.s4.p9","orden":9,"grupo":"aire-suelo-1.s4.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta situación suele empeorar o mejorar la calidad del aire?","grupos":[{"id":"g1","nombre":"Empeora"},{"id":"g2","nombre":"Mejora"}],"items":[{"id":"i1","texto":"Noche fría sin viento"},{"id":"i2","texto":"Viento fuerte"},{"id":"i3","texto":"Quema de pastizales cercana"},{"id":"i4","texto":"Lluvia que lava las partículas"},{"id":"i5","texto":"Hora pico de tránsito"},{"id":"i6","texto":"Día sin clases ni tránsito"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El clima del día y las actividades humanas se combinan para definir el aire que se respira."}},{"slug":"aire-suelo-1.s4.p10","orden":10,"grupo":"aire-suelo-1.s4.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con para qué sirve.","izquierda":[{"id":"a1","texto":"Estación de monitoreo oficial"},{"id":"a2","texto":"Sensor de bajo costo"},{"id":"a3","texto":"Índice de colores"},{"id":"a4","texto":"Valor guía de la OMS"}],"derecha":[{"id":"b1","texto":"Medir con precisión y generar datos oficiales"},{"id":"b2","texto":"Ver tendencias en un barrio o una escuela"},{"id":"b3","texto":"Comunicar rápido qué tan bueno es el aire"},{"id":"b4","texto":"Comparar con un nivel recomendado para la salud"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Medir, comunicar y comparar: tres pasos para que un dato sirva."}},{"slug":"aire-suelo-1.s4.p11","orden":11,"grupo":"aire-suelo-1.s4.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos conviene mirar para saber si el aire de tu barrio es un problema? Marcá todos.","opciones":[{"id":"o1","texto":"El promedio anual de PM2,5"},{"id":"o2","texto":"Los días que se superó el valor guía diario"},{"id":"o3","texto":"Los picos y en qué condiciones ocurren"},{"id":"o4","texto":"La comparación con los valores guía de la OMS"},{"id":"o5","texto":"Solo el dato de un día de viento fuerte"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un solo día no alcanza: hace falta mirar promedios, picos y comparar con una referencia."}},{"slug":"aire-suelo-1.s4.p12","orden":12,"grupo":"aire-suelo-1.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe barrial y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El sensor midió 12 µg/m³ de PM2,5 un día ventoso."},{"id":"s2","texto":"Por eso el aire del barrio es excelente todo el año."},{"id":"s3","texto":"En días fríos sin viento, los valores subieron."},{"id":"s4","texto":"Los sensores de bajo costo son tan precisos como las estaciones oficiales."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un dato sin contexto puede llevar a conclusiones equivocadas.","por_opcion":{"s2":"Un día ventoso no representa el año: hay que mirar promedios y picos.","s4":"Son útiles para ver tendencias, pero menos precisos."}}},{"slug":"aire-suelo-1.s4.p13","orden":13,"grupo":"aire-suelo-1.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las partículas se miden en microgramos por metro {{0}}; una capa de aire caliente que atrapa la contaminación es una inversión {{1}}.","banco":[{"id":"w1","texto":"cúbico"},{"id":"w2","texto":"térmica"},{"id":"w3","texto":"cuadrado"},{"id":"w4","texto":"solar"},{"id":"w5","texto":"lineal"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas clave para leer datos de calidad del aire."}}]},{"slug":"aire-suelo-1.s5","orden":5,"tipo":"leccion","titulo_es":"El aire de adentro","bajada_es":"Monóxido de carbono, humo, leña y aulas cerradas: el aire que respiramos la mayor parte del día.","minutos":11,"pasos":[{"slug":"aire-suelo-1.s5.p1","orden":1,"grupo":"aire-suelo-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pasamos el día adentro","cuerpo":["La mayoría de las personas pasa gran parte del día dentro de casas, escuelas, oficinas y vehículos. El aire de adentro puede estar más contaminado que el de afuera: humo de cigarrillo, combustión de estufas, cocinas y calefones, humedad y hongos, productos de limpieza y aire viciado por falta de ventilación.","Según la OMS, la contaminación del aire en los hogares por cocinar y calefaccionar con combustibles sólidos (leña, carbón) o querosén causa millones de muertes por año en el mundo, sobre todo en países de ingresos bajos."]},"solucion":{}},{"slug":"aire-suelo-1.s5.p2","orden":2,"grupo":"aire-suelo-1.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué fuentes contaminan el aire dentro de una casa? Marcá todas.","opciones":[{"id":"o1","texto":"Humo de cigarrillo"},{"id":"o2","texto":"Estufas y calefones mal instalados"},{"id":"o3","texto":"Cocinar con leña sin buena salida de humo"},{"id":"o4","texto":"Humedad y hongos"},{"id":"o5","texto":"Una planta en maceta"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El aire interior se contamina con la combustión, el tabaco y la humedad. Las plantas no son una fuente de contaminación."}},{"slug":"aire-suelo-1.s5.p3","orden":3,"grupo":"aire-suelo-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Monóxido de carbono: el asesino silencioso","cuerpo":["El monóxido de carbono (CO) es un gas sin color, sin olor y sin sabor que se produce cuando un combustible se quema con poco oxígeno: estufas, calefones, braseros, hornos y cocinas en mal estado o en ambientes sin ventilación. Se une a la sangre en lugar del oxígeno y puede matar en poco tiempo.","Cada invierno causa muertes evitables en Argentina. Las señales de alarma son dolor de cabeza, mareos, náuseas y somnolencia en varias personas a la vez. La llama de los artefactos debería ser azul: una llama amarilla o anaranjada indica mala combustión."],"destacado":{"valor":"Llama azul","texto":"indica buena combustión. Llama amarilla o anaranjada: revisar el artefacto."}},"solucion":{}},{"slug":"aire-suelo-1.s5.p4","orden":4,"grupo":"aire-suelo-1.s5.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el monóxido de carbono es tan peligroso?","opciones":[{"id":"o1","texto":"Porque no se nota y desplaza al oxígeno"},{"id":"o2","texto":"Porque tiene un olor tan fuerte que desmaya"},{"id":"o3","texto":"Porque solo aparece en las fábricas"},{"id":"o4","texto":"Porque hace que la llama se vuelva azul"}]},"solucion":{"clave":["o1"],"explicacion":"No da aviso: por eso las rejillas de ventilación y la revisión de artefactos salvan vidas.","por_opcion":{"o3":"Aparece en cualquier casa con artefactos a gas o leña mal instalados o sin ventilación."}}},{"slug":"aire-suelo-1.s5.p5","orden":5,"grupo":"aire-suelo-1.s5.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta señal indica posible riesgo de monóxido de carbono o no?","grupos":[{"id":"g1","nombre":"Posible riesgo"},{"id":"g2","nombre":"Sin riesgo particular"}],"items":[{"id":"i1","texto":"Llama amarilla en la hornalla"},{"id":"i2","texto":"Llama azul y pareja"},{"id":"i3","texto":"Manchas negras sobre una estufa"},{"id":"i4","texto":"Rejillas de ventilación libres"},{"id":"i5","texto":"Varias personas con dolor de cabeza y mareo en la misma habitación"},{"id":"i6","texto":"Estufa de tiro balanceado revisada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Llama amarilla, hollín y síntomas en grupo son señales para apagar, ventilar y pedir ayuda."}},{"slug":"aire-suelo-1.s5.p6","orden":6,"grupo":"aire-suelo-1.s5.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená qué hacer ante una sospecha de intoxicación con monóxido de carbono.","items":[{"id":"i1","texto":"Abrir puertas y ventanas"},{"id":"i2","texto":"Apagar los artefactos si es posible"},{"id":"i3","texto":"Salir al aire libre"},{"id":"i4","texto":"Llamar a emergencias"},{"id":"i5","texto":"Hacer revisar los artefactos por un gasista matriculado antes de volver a usarlos"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ventilar, salir y pedir ayuda. Después, revisar todo con un profesional."}},{"slug":"aire-suelo-1.s5.p7","orden":7,"grupo":"aire-suelo-1.s5.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un brasero encendido en un dormitorio cerrado es una forma segura de calefaccionar.","razones":[{"id":"r1","texto":"Porque produce monóxido de carbono en un ambiente sin ventilación"},{"id":"r2","texto":"Porque los braseros no producen calor"},{"id":"r3","texto":"Porque el monóxido solo se produce al aire libre"}]},"solucion":{"valor":false,"explicacion":"Es una de las causas más comunes de intoxicación por monóxido de carbono. Nunca se usan braseros ni hornallas para calefaccionar ambientes cerrados.","clave":["r1"]}},{"slug":"aire-suelo-1.s5.p8","orden":8,"grupo":"aire-suelo-1.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aire viciado en las aulas","cuerpo":["Cuando muchas personas comparten un espacio cerrado, el CO₂ que exhalan se acumula. El CO₂ en esos niveles no es tóxico, pero funciona como un indicador: si sube mucho, quiere decir que el aire no se está renovando, y con él se acumulan otras cosas, como virus y humedad.","Muchas guías usan como referencia no superar unos 800 a 1.000 ppm de CO₂ en aulas y oficinas. Afuera, el aire tiene algo más de 420 ppm."]},"solucion":{}},{"slug":"aire-suelo-1.s5.p9","orden":9,"grupo":"aire-suelo-1.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un medidor en un aula cerrada marca 1.800 ppm de CO₂. Si la referencia es no superar 1.000 ppm, ¿cuántas ppm por encima está?","unidad":"ppm","decimales":0},"solucion":{"valor":800,"tolerancia":16,"explicacion":"1.800 − 1.000 = 800 ppm por encima. Es una señal de que hay que ventilar, por ejemplo abriendo ventanas enfrentadas unos minutos."}},{"slug":"aire-suelo-1.s5.p9.v2","orden":9,"grupo":"aire-suelo-1.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un medidor en un aula cerrada marca 1.400 ppm de CO₂. Si la referencia es no superar 1.000 ppm, ¿cuántas ppm por encima está?","unidad":"ppm","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"1.400 − 1.000 = 400 ppm por encima. Es una señal de que hay que ventilar, por ejemplo abriendo ventanas enfrentadas unos minutos."}},{"slug":"aire-suelo-1.s5.p9.v3","orden":9,"grupo":"aire-suelo-1.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un medidor en un aula cerrada marca 2.200 ppm de CO₂. Si la referencia es no superar 1.000 ppm, ¿cuántas ppm por encima está?","unidad":"ppm","decimales":0},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"2.200 − 1.000 = 1.200 ppm por encima. Es una señal de que hay que ventilar, por ejemplo abriendo ventanas enfrentadas unos minutos."}},{"slug":"aire-suelo-1.s5.p10","orden":10,"grupo":"aire-suelo-1.s5.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué pasa en un aula cerrada durante una clase larga.","items":[{"id":"i1","texto":"Treinta personas respiran en un aula con ventanas cerradas"},{"id":"i2","texto":"El CO₂ exhalado se acumula"},{"id":"i3","texto":"El aire no se renueva"},{"id":"i4","texto":"Se acumulan también humedad y posibles virus"},{"id":"i5","texto":"Aumentan el cansancio y el riesgo de contagios"},{"id":"i6","texto":"El CO₂ se transforma en oxígeno dentro del aula"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Medir el CO₂ es una forma barata de saber cuándo ventilar."}},{"slug":"aire-suelo-1.s5.p11","orden":11,"grupo":"aire-suelo-1.s5.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué mejora el aire interior? Marcá todo lo que ayuda.","opciones":[{"id":"o1","texto":"Ventilar abriendo ventanas enfrentadas unos minutos"},{"id":"o2","texto":"Mantener libres las rejillas de ventilación"},{"id":"o3","texto":"No fumar adentro"},{"id":"o4","texto":"Revisar los artefactos a gas cada año"},{"id":"o5","texto":"Tapar las rejillas para que no entre frío"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Ventilar y revisar artefactos: dos hábitos simples que protegen la salud y la vida."}},{"slug":"aire-suelo-1.s5.p12","orden":12,"grupo":"aire-suelo-1.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje de un grupo de padres y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Conviene ventilar el aula unos minutos cada hora."},{"id":"s2","texto":"El CO₂ del aula es un veneno mortal a 1.500 ppm."},{"id":"s3","texto":"La llama de la estufa del aula tiene que ser azul."},{"id":"s4","texto":"Si la estufa tiene llama amarilla, es más calentita y está mejor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El CO₂ es un indicador; el monóxido de carbono es el verdadero peligro de la combustión.","por_opcion":{"s2":"A esos niveles no es tóxico; es un indicador de mala ventilación.","s4":"La llama amarilla indica mala combustión y posible monóxido de carbono."}}},{"slug":"aire-suelo-1.s5.p13","orden":13,"grupo":"aire-suelo-1.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El monóxido de carbono no tiene {{0}} ni color; la llama de los artefactos tiene que ser {{1}}; y las {{2}} de ventilación nunca se tapan.","banco":[{"id":"w1","texto":"olor"},{"id":"w2","texto":"azul"},{"id":"w3","texto":"rejillas"},{"id":"w4","texto":"peso"},{"id":"w5","texto":"amarilla"},{"id":"w6","texto":"ventanas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas que salvan vidas cada invierno."}}]},{"slug":"aire-suelo-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el aire que respirás","bajada_es":"Composición, contaminantes, salud, mediciones y aire interior, mezclados.","minutos":8,"pasos":[{"slug":"aire-suelo-1.s6.p1","orden":1,"grupo":"aire-suelo-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El aire que respirás». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"aire-suelo-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el aire de la escuela de la avenida","bajada_es":"Una escuela junto a una avenida midió su aire. Interpretá los datos y armá un plan. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"aire-suelo-1.s7.p1","orden":1,"grupo":"aire-suelo-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["Una escuela está sobre una avenida con mucho tránsito de colectivos. Un grupo de estudiantes midió con un sensor durante un mes. En la vereda, el PM2,5 promedió 28 µg/m³, con picos de 60 en la hora de entrada. En el patio del fondo, a 60 metros de la avenida, promedió 14. En las aulas, el CO₂ llegaba a 1.800 ppm al final de las clases con las ventanas cerradas.","En invierno, el aula de música se calefacciona con una estufa vieja con llama amarilla."]},"solucion":{}},{"slug":"aire-suelo-1.s7.p2","orden":2,"grupo":"aire-suelo-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas veces supera el promedio de la vereda (28 µg/m³) el valor guía diario de la OMS para PM2,5 (15 µg/m³)? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Vereda: 28 µg/m³ de PM2,5 promedio; guía diaria OMS: 15."},"solucion":{"valor":1.9,"tolerancia":0.1,"explicacion":"28 ÷ 15 ≈ 1,9 veces. Y en la hora de entrada, los picos de 60 son 4 veces el valor guía."}},{"slug":"aire-suelo-1.s7.p3","orden":3,"grupo":"aire-suelo-1.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje baja el PM2,5 del patio del fondo (14) respecto de la vereda (28)?","unidad":"%","decimales":0,"contexto":"Vereda: 28 µg/m³. Patio del fondo: 14 µg/m³."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(28 − 14) ÷ 28 × 100 = 50 %. Alejarse 60 metros de la avenida reduce a la mitad lo que se respira."}},{"slug":"aire-suelo-1.s7.p4","orden":4,"grupo":"aire-suelo-1.s7.p4","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los problemas de la escuela por urgencia, del más urgente al menos.","items":[{"id":"i1","texto":"Estufa con llama amarilla en el aula de música"},{"id":"i2","texto":"Aulas a 1.800 ppm de CO₂ sin ventilar"},{"id":"i3","texto":"Picos de PM2,5 en la vereda a la hora de entrada"},{"id":"i4","texto":"PM2,5 del patio del fondo por encima de la guía anual"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero lo que puede matar hoy; después lo que afecta la salud todos los días.","valores":{"i1":"riesgo de monóxido: urgente","i2":"mala ventilación diaria","i3":"exposición diaria breve","i4":"exposición moderada"}}},{"slug":"aire-suelo-1.s7.p5","orden":5,"grupo":"aire-suelo-1.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer ya con la estufa del aula de música?","opciones":[{"id":"o1","texto":"Dejar de usarla hasta que la revise un gasista matriculado"},{"id":"o2","texto":"Usarla solo con la puerta cerrada para que caliente más"},{"id":"o3","texto":"Seguir usándola porque la llama amarilla calienta más"},{"id":"o4","texto":"Taparle la salida para que no se escape el calor"}]},"solucion":{"clave":["o1"],"explicacion":"Ante una llama amarilla, no se usa hasta que un profesional la revise.","por_opcion":{"o3":"La llama amarilla indica mala combustión y riesgo de monóxido de carbono."}}},{"slug":"aire-suelo-1.s7.p6","orden":6,"grupo":"aire-suelo-1.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas del plan son razonables? Marcá todas.","opciones":[{"id":"o1","texto":"Ventilar las aulas unos minutos en cada recreo"},{"id":"o2","texto":"Hacer la fila de entrada en el patio del fondo"},{"id":"o3","texto":"Pedir al municipio prioridad para colectivos menos contaminantes en esa avenida"},{"id":"o4","texto":"Seguir midiendo para ver si las medidas funcionan"},{"id":"o5","texto":"Cerrar todas las ventanas para que no entre el aire de la avenida"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cerrar todo empeora el CO₂ y la ventilación. Conviene ventilar y alejar a los chicos de la fuente en los momentos pico."}},{"slug":"aire-suelo-1.s7.p7","orden":7,"grupo":"aire-suelo-1.s7.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué mover la fila de entrada al patio del fondo ayuda.","items":[{"id":"i1","texto":"La fila se arma lejos de la avenida"},{"id":"i2","texto":"Los chicos esperan donde el PM2,5 es la mitad"},{"id":"i3","texto":"Respiran menos partículas en el momento de más tránsito"},{"id":"i4","texto":"Baja su exposición diaria sin costo"},{"id":"i5","texto":"El patio del fondo filtra el aire de la avenida"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una medida gratis que usa los datos medidos: la distancia a la fuente importa."}},{"slug":"aire-suelo-1.s7.p8","orden":8,"grupo":"aire-suelo-1.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La escuela publica su plan. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La estufa del aula de música no se usa hasta que la revise un gasista."},{"id":"s2","texto":"Como el CO₂ de las aulas es veneno, suspendemos las clases."},{"id":"s3","texto":"La fila de entrada se hará en el patio del fondo."},{"id":"s4","texto":"Para que no entre el aire de la avenida, no ventilaremos nunca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan interpreta bien cada dato y prioriza lo urgente.","por_opcion":{"s2":"A esos niveles no es tóxico: indica que hay que ventilar.","s4":"Sin ventilar, empeora el aire interior. Mejor ventilar en momentos de menos tránsito."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"aire-suelo-2","rama":"aire_suelo","orden":2,"nivel":1,"titulo_es":"El suelo vivo","bajada_es":"Un centímetro de suelo puede tardar siglos en formarse y perderse en una tormenta. Qué es, quién vive ahí y por qué casi toda tu comida depende de él.","objetivos_es":["Describir los componentes y las capas de un suelo","Reconocer los organismos del suelo y sus funciones","Explicar el papel de la materia orgánica en el agua y el carbono del suelo","Identificar los procesos de degradación del suelo y sus causas","Proponer prácticas para conservar y recuperar suelos"],"repasa":["tronco-1","plantas-1"],"requiere_tronco":1,"fuentes":["fao-suelos","fao-suelos-degradacion","anthony-2023-suelo","inta","ipbes-global"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"aire-suelo-2.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es el suelo","bajada_es":"Minerales, materia orgánica, agua y aire: la capa fina que cubre la tierra y cómo se forma.","minutos":12,"pasos":[{"slug":"aire-suelo-2.s1.p1","orden":1,"grupo":"aire-suelo-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mucho más que tierra","cuerpo":["El suelo es la capa superficial de la tierra donde crecen las plantas. No es solo \"tierra\": es una mezcla de partículas minerales (arena, limo y arcilla), materia orgánica (restos de plantas y animales en descomposición), agua, aire y una cantidad enorme de seres vivos.","En un suelo sano típico, alrededor de la mitad del volumen son partículas sólidas —casi todas minerales y una parte chica de materia orgánica— y la otra mitad son poros, ocupados por agua y aire."],"datos":{"tipo":"barras","titulo":"Composición de un suelo sano típico","unidad":"% del volumen","filas":[{"etiqueta":"Minerales","valor":45},{"etiqueta":"Agua","valor":25},{"etiqueta":"Aire","valor":25},{"etiqueta":"Materia orgánica","valor":5}],"nota":"Valores de referencia de manual; cambian mucho entre suelos y según la humedad."}},"solucion":{}},{"slug":"aire-suelo-2.s1.p2","orden":2,"grupo":"aire-suelo-2.s1.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese ejemplo, ordená los componentes del suelo por su volumen, de más a menos.","items":[{"id":"i1","texto":"Minerales"},{"id":"i2","texto":"Agua"},{"id":"i3","texto":"Aire"},{"id":"i4","texto":"Materia orgánica"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La materia orgánica es la parte más chica, pero, como vas a ver, una de las más importantes.","valores":{"i1":"≈ 45 %","i2":"≈ 25 %","i3":"≈ 25 %","i4":"≈ 5 %"}}},{"slug":"aire-suelo-2.s1.p3","orden":3,"grupo":"aire-suelo-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Arena, limo y arcilla","cuerpo":["Las partículas minerales tienen distintos tamaños: la arena es la más gruesa (se siente áspera), el limo es intermedio (se siente como talco) y la arcilla es la más fina (se siente pegajosa cuando está mojada). La proporción de cada una es la textura del suelo.","Los suelos arenosos dejan pasar el agua rápido y se secan pronto; los arcillosos retienen mucha agua pero pueden encharcarse. Los suelos francos, con una mezcla equilibrada, suelen ser los mejores para cultivar."]},"solucion":{}},{"slug":"aire-suelo-2.s1.p4","orden":4,"grupo":"aire-suelo-2.s1.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tipo de partícula con su característica.","izquierda":[{"id":"a1","texto":"Arena"},{"id":"a2","texto":"Limo"},{"id":"a3","texto":"Arcilla"}],"derecha":[{"id":"b1","texto":"Gruesa y áspera; el agua pasa rápido"},{"id":"b2","texto":"Intermedia; se siente como talco"},{"id":"b3","texto":"Muy fina y pegajosa; retiene mucha agua"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"La textura explica por qué algunos suelos se secan en horas y otros se encharcan por días."}},{"slug":"aire-suelo-2.s1.p5","orden":5,"grupo":"aire-suelo-2.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué suelo describe mejor cada situación?","grupos":[{"id":"g1","nombre":"Arenoso"},{"id":"g2","nombre":"Arcilloso"}],"items":[{"id":"i1","texto":"Se seca pocas horas después de regar"},{"id":"i2","texto":"Queda encharcado días después de la lluvia"},{"id":"i3","texto":"Se siente áspero entre los dedos"},{"id":"i4","texto":"Se pega a las botas cuando está mojado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Conocer la textura ayuda a decidir cuánto y cada cuánto regar."}},{"slug":"aire-suelo-2.s1.p6","orden":6,"grupo":"aire-suelo-2.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las capas","cuerpo":["Si se cava un pozo profundo, se ven capas horizontales llamadas horizontes. Arriba suele haber una capa de restos orgánicos; debajo, la capa superficial (horizonte A), oscura y fértil, donde están casi todas las raíces y la vida; más abajo, el subsuelo (horizonte B), más claro, donde se acumulan arcillas; y después el material del que se formó el suelo y la roca.","La capa superficial es la más valiosa y la más fácil de perder."]},"solucion":{}},{"slug":"aire-suelo-2.s1.p7","orden":7,"grupo":"aire-suelo-2.s1.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las capas de un suelo, de arriba hacia abajo.","items":[{"id":"i1","texto":"Restos orgánicos (hojas, ramitas)"},{"id":"i2","texto":"Capa superficial oscura y fértil (horizonte A)"},{"id":"i3","texto":"Subsuelo más claro (horizonte B)"},{"id":"i4","texto":"Material de origen meteorizado (horizonte C)"},{"id":"i5","texto":"Roca"}],"extremos":["Arriba","Abajo"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La vida y la fertilidad se concentran arriba. Por eso la erosión, que se lleva la capa superficial, es tan grave."}},{"slug":"aire-suelo-2.s1.p8","orden":8,"grupo":"aire-suelo-2.s1.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un recurso que tarda siglos","cuerpo":["El suelo se forma muy lentamente: la roca se rompe por el agua, el hielo, las raíces y los seres vivos, y se mezcla con materia orgánica. Según la FAO, formar un centímetro de suelo puede llevar hasta mil años.","Por eso, a escala de una vida humana, el suelo es prácticamente un recurso no renovable: lo que se pierde en una tormenta o en años de mal manejo no vuelve en generaciones."],"destacado":{"valor":"Hasta 1.000 años","texto":"puede llevar formar un centímetro de suelo, según la FAO."}},"solucion":{}},{"slug":"aire-suelo-2.s1.p9","orden":9,"grupo":"aire-suelo-2.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si formar un centímetro de suelo lleva 500 años, ¿cuántos años tardarían en formarse los 5 cm que se perdieron por erosión en un campo?","unidad":"años","decimales":0},"solucion":{"valor":2500,"tolerancia":50,"explicacion":"5 × 500 = 2.500 años. Lo que se pierde en pocos años de erosión tarda milenios en volver."}},{"slug":"aire-suelo-2.s1.p9.v2","orden":9,"grupo":"aire-suelo-2.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si formar un centímetro de suelo lleva 300 años, ¿cuántos años tardarían en formarse los 10 cm que se perdieron por erosión en un campo?","unidad":"años","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"10 × 300 = 3.000 años. Lo que se pierde en pocos años de erosión tarda milenios en volver."}},{"slug":"aire-suelo-2.s1.p9.v3","orden":9,"grupo":"aire-suelo-2.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si formar un centímetro de suelo lleva 1000 años, ¿cuántos años tardarían en formarse los 2 cm que se perdieron por erosión en un campo?","unidad":"años","decimales":0},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"2 × 1000 = 2.000 años. Lo que se pierde en pocos años de erosión tarda milenios en volver."}},{"slug":"aire-suelo-2.s1.p10","orden":10,"grupo":"aire-suelo-2.s1.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El suelo es un recurso renovable que se recupera en pocos años.","razones":[{"id":"r1","texto":"Porque formar un centímetro puede llevar cientos de años"},{"id":"r2","texto":"Porque el suelo se fabrica en las fábricas de fertilizantes"},{"id":"r3","texto":"Porque la lluvia trae suelo nuevo cada año"}]},"solucion":{"valor":false,"explicacion":"Formar suelo lleva siglos o milenios. En la escala de una vida humana, el suelo perdido prácticamente no vuelve: por eso se lo considera casi no renovable.","clave":["r1"]}},{"slug":"aire-suelo-2.s1.p11","orden":11,"grupo":"aire-suelo-2.s1.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué componentes forman un suelo sano? Marcá todos.","opciones":[{"id":"o1","texto":"Partículas minerales"},{"id":"o2","texto":"Materia orgánica"},{"id":"o3","texto":"Agua"},{"id":"o4","texto":"Aire"},{"id":"o5","texto":"Plástico triturado"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Minerales, materia orgánica, agua, aire y, además, una enorme cantidad de seres vivos. El plástico es contaminación."}},{"slug":"aire-suelo-2.s1.p12","orden":12,"grupo":"aire-suelo-2.s1.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Querés saber si la tierra de tu cantero es arcillosa. ¿Qué prueba simple podés hacer?","opciones":[{"id":"o1","texto":"Mojarla y ver si se pega y forma un rollito"},{"id":"o2","texto":"Olerla para ver si tiene olor a humedad"},{"id":"o3","texto":"Pesarla seca en una balanza de cocina"},{"id":"o4","texto":"Mirar si tiene hojas secas arriba"}]},"solucion":{"clave":["o1"],"explicacion":"La arcilla mojada es pegajosa y se puede estirar en un rollito; la arena se desarma; el limo se siente suave como talco.","por_opcion":{"o3":"El peso solo no dice la textura: la arcilla se reconoce porque es pegajosa y moldeable."}}},{"slug":"aire-suelo-2.s1.p13","orden":13,"grupo":"aire-suelo-2.s1.p13","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La capa superficial del suelo es la que concentra más raíces y más vida.","razones":[{"id":"r1","texto":"Porque tiene más materia orgánica, aire y alimento"},{"id":"r2","texto":"Porque la roca de abajo tiene más nutrientes"},{"id":"r3","texto":"Porque las raíces solo crecen en el subsuelo"}]},"solucion":{"valor":true,"explicacion":"Es la capa con más materia orgánica, aire y alimento. Por eso perderla por erosión es tan grave.","clave":["r1"]}},{"slug":"aire-suelo-2.s1.p14","orden":14,"grupo":"aire-suelo-2.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El suelo tiene minerales, materia orgánica, agua y aire."},{"id":"s2","texto":"El suelo es solo tierra muerta que sostiene las plantas."},{"id":"s3","texto":"La capa superficial es la más fértil."},{"id":"s4","texto":"Un centímetro de suelo se forma en un par de años."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El suelo está vivo y es lento. Dos ideas que cambian cómo se lo trata.","por_opcion":{"s2":"Está lleno de vida y es un sistema complejo.","s4":"Puede llevar cientos o hasta mil años."}}},{"slug":"aire-suelo-2.s1.p15","orden":15,"grupo":"aire-suelo-2.s1.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La proporción de arena, limo y arcilla es la {{0}} del suelo; la capa más fértil es la {{1}}; y formar un centímetro puede llevar hasta {{2}} años.","banco":[{"id":"w1","texto":"textura"},{"id":"w2","texto":"superficial"},{"id":"w3","texto":"mil"},{"id":"w4","texto":"temperatura"},{"id":"w5","texto":"profunda"},{"id":"w6","texto":"diez"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas básicas sobre qué es el suelo."}}]},{"slug":"aire-suelo-2.s2","orden":2,"tipo":"leccion","titulo_es":"La vida bajo tus pies","bajada_es":"Bacterias, hongos, lombrices y bichos bolita: el suelo es uno de los lugares con más vida del planeta.","minutos":11,"pasos":[{"slug":"aire-suelo-2.s2.p1","orden":1,"grupo":"aire-suelo-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una multitud invisible","cuerpo":["Un puñado de suelo sano tiene más seres vivos que personas hay en la Tierra: bacterias, hongos, protozoos, nematodos, ácaros, colémbolos, lombrices, larvas de insectos y muchos más. Un estudio de 2023 estimó que más de la mitad de todas las especies del planeta vive en el suelo.","Casi todos son invisibles a simple vista, pero hacen trabajos esenciales: descomponen restos, reciclan nutrientes, forman la estructura del suelo y ayudan a las plantas."],"destacado":{"valor":"Más de la mitad","texto":"de las especies del planeta viviría en el suelo, según un estudio publicado en 2023."}},"solucion":{}},{"slug":"aire-suelo-2.s2.p2","orden":2,"grupo":"aire-suelo-2.s2.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las especies del planeta vive en el suelo, según un estudio de 2023.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":59,"banda":"lineal","explicacion":"Alrededor del 59 %. El suelo sería el hábitat más rico en especies de la Tierra, aunque casi no lo miremos."}},{"slug":"aire-suelo-2.s2.p3","orden":3,"grupo":"aire-suelo-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién hace qué","cuerpo":["Las bacterias y los hongos descomponen la materia orgánica y liberan nutrientes que las plantas pueden absorber. Los hongos micorrícicos, que viste en la unidad de plantas, se asocian con las raíces. Las lombrices comen restos y tierra, cavan túneles que dejan pasar el aire y el agua, y producen un abono muy rico.","Los pequeños artrópodos, como los colémbolos y los ácaros, trituran restos y regulan a otros organismos. Todos juntos forman la red trófica del suelo."]},"solucion":{}},{"slug":"aire-suelo-2.s2.p4","orden":4,"grupo":"aire-suelo-2.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada organismo del suelo con su trabajo principal.","izquierda":[{"id":"a1","texto":"Bacterias"},{"id":"a2","texto":"Hongos micorrícicos"},{"id":"a3","texto":"Lombrices"},{"id":"a4","texto":"Colémbolos"}],"derecha":[{"id":"b1","texto":"Descomponer restos y liberar nutrientes"},{"id":"b2","texto":"Ayudar a las raíces a tomar agua y nutrientes"},{"id":"b3","texto":"Cavar túneles y mezclar el suelo"},{"id":"b4","texto":"Triturar restos orgánicos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un equipo invisible que mantiene funcionando el suelo."}},{"slug":"aire-suelo-2.s2.p5","orden":5,"grupo":"aire-suelo-2.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una hoja caída se convierte en nutriente.","items":[{"id":"i1","texto":"Una hoja cae al suelo"},{"id":"i2","texto":"Bichos pequeños la trituran"},{"id":"i3","texto":"Hongos y bacterias la descomponen"},{"id":"i4","texto":"Se liberan nutrientes en el suelo"},{"id":"i5","texto":"Una raíz los absorbe"},{"id":"i6","texto":"La hoja se evapora y llueve como nutriente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ciclo de la materia del tronco, en un centímetro de suelo."}},{"slug":"aire-suelo-2.s2.p6","orden":6,"grupo":"aire-suelo-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las lombrices, ingenieras","cuerpo":["Las lombrices de tierra son ingenieras del suelo: sus túneles mejoran la infiltración del agua y la aireación, y sus excrementos (el humus de lombriz) son ricos en nutrientes. Donde hay muchas lombrices, suele haber un suelo sano.","Contar lombrices en una palada de tierra es una forma sencilla de evaluar la salud de un suelo, que usan productores y huerteros."]},"solucion":{}},{"slug":"aire-suelo-2.s2.p7","orden":7,"grupo":"aire-suelo-2.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Encontrar muchas lombrices en una palada de tierra suele ser una buena señal.","razones":[{"id":"r1","texto":"Porque indican materia orgánica, humedad y buena estructura"},{"id":"r2","texto":"Porque las lombrices son una plaga de los cultivos"},{"id":"r3","texto":"Porque las lombrices solo viven en suelos contaminados"}]},"solucion":{"valor":true,"explicacion":"Indican un suelo con materia orgánica, humedad y poca contaminación. Muchos productores las cuentan para evaluar la salud del suelo.","clave":["r1"]}},{"slug":"aire-suelo-2.s2.p8","orden":8,"grupo":"aire-suelo-2.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 4 paladas de tierra se contaron 48 lombrices en total. ¿Cuántas lombrices hay en promedio por palada?","unidad":"lombrices","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"48 ÷ 4 = 12 lombrices por palada. Muchas guías de campo consideran que más de 10 por palada es señal de un suelo con buena actividad biológica."}},{"slug":"aire-suelo-2.s2.p8.v2","orden":8,"grupo":"aire-suelo-2.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 5 paladas de tierra se contaron 15 lombrices en total. ¿Cuántas lombrices hay en promedio por palada?","unidad":"lombrices","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"15 ÷ 5 = 3 lombrices por palada. Muchas guías de campo consideran que más de 10 por palada es señal de un suelo con buena actividad biológica."}},{"slug":"aire-suelo-2.s2.p8.v3","orden":8,"grupo":"aire-suelo-2.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 5 paladas de tierra se contaron 100 lombrices en total. ¿Cuántas lombrices hay en promedio por palada?","unidad":"lombrices","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"100 ÷ 5 = 20 lombrices por palada. Muchas guías de campo consideran que más de 10 por palada es señal de un suelo con buena actividad biológica."}},{"slug":"aire-suelo-2.s2.p9","orden":9,"grupo":"aire-suelo-2.s2.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica favorece o perjudica la vida del suelo?","grupos":[{"id":"g1","nombre":"Favorece"},{"id":"g2","nombre":"Perjudica"}],"items":[{"id":"i1","texto":"Agregar compost"},{"id":"i2","texto":"Quemar rastrojos"},{"id":"i3","texto":"Dejar restos vegetales como cobertura"},{"id":"i4","texto":"Dejar el suelo desnudo al sol"},{"id":"i5","texto":"Rotar cultivos"},{"id":"i6","texto":"Aplicar exceso de agroquímicos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La vida del suelo necesita alimento (materia orgánica), protección (cobertura) y que no la maten."}},{"slug":"aire-suelo-2.s2.p10","orden":10,"grupo":"aire-suelo-2.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué quemar los rastrojos de un cultivo perjudica al suelo?","opciones":[{"id":"o1","texto":"Porque elimina materia orgánica y vida del suelo"},{"id":"o2","texto":"Porque el fuego agrega nutrientes que sobran"},{"id":"o3","texto":"Porque el humo tapa el sol durante semanas"},{"id":"o4","texto":"Porque las cenizas vuelven arenoso al suelo"}]},"solucion":{"clave":["o1"],"explicacion":"La quema deja el suelo desnudo, sin alimento para su vida y expuesto a la erosión. Además, contamina el aire.","por_opcion":{"o3":"El humo contamina el aire, pero el daño al suelo es perder materia orgánica y organismos."}}},{"slug":"aire-suelo-2.s2.p11","orden":11,"grupo":"aire-suelo-2.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué organismos forman parte de la vida del suelo? Marcá todos.","opciones":[{"id":"o1","texto":"Bacterias"},{"id":"o2","texto":"Hongos"},{"id":"o3","texto":"Lombrices"},{"id":"o4","texto":"Bichos bolita"},{"id":"o5","texto":"Palomas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las palomas pueden comer en el suelo, pero no viven en él. Los otros son parte de su red."}},{"slug":"aire-suelo-2.s2.p12","orden":12,"grupo":"aire-suelo-2.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario de un huertero y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Encontré muchas lombrices: buena señal."},{"id":"s2","texto":"Voy a fumigar el suelo para matar todos los bichos y que crezca mejor."},{"id":"s3","texto":"Agrego compost para alimentar la vida del suelo."},{"id":"s4","texto":"Los hongos del suelo son siempre enfermedades."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El suelo sano es un suelo con mucha vida. Casi toda trabaja a favor.","por_opcion":{"s2":"La mayoría de los organismos del suelo son beneficiosos: matarlos empobrece el suelo.","s4":"Muchos hongos descomponen restos o ayudan a las raíces."}}},{"slug":"aire-suelo-2.s2.p13","orden":13,"grupo":"aire-suelo-2.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las {{0}} cavan túneles que dejan pasar agua y aire; las bacterias y los {{1}} descomponen restos y liberan {{2}}.","banco":[{"id":"w1","texto":"lombrices"},{"id":"w2","texto":"hongos"},{"id":"w3","texto":"nutrientes"},{"id":"w4","texto":"hormigas"},{"id":"w5","texto":"virus"},{"id":"w6","texto":"plásticos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La red de vida del suelo, en una sola línea."}}]},{"slug":"aire-suelo-2.s3","orden":3,"tipo":"leccion","titulo_es":"Una esponja de carbono y agua","bajada_es":"La materia orgánica: por qué un suelo oscuro guarda más agua, más nutrientes y más carbono.","minutos":12,"pasos":[{"slug":"aire-suelo-2.s3.p1","orden":1,"grupo":"aire-suelo-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La materia orgánica","cuerpo":["La materia orgánica del suelo son los restos de plantas, animales y microbios en distintas etapas de descomposición. La parte más estable se llama humus y le da al suelo su color oscuro.","Aunque sea una parte chica del volumen, cumple muchas funciones: alimenta la vida del suelo, guarda nutrientes, pega las partículas en grumos que dejan pasar el aire y el agua, y retiene agua como una esponja."]},"solucion":{}},{"slug":"aire-suelo-2.s3.p2","orden":2,"grupo":"aire-suelo-2.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace la materia orgánica en el suelo? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Retiene agua"},{"id":"o2","texto":"Guarda nutrientes"},{"id":"o3","texto":"Alimenta a los organismos del suelo"},{"id":"o4","texto":"Forma grumos que mejoran la estructura"},{"id":"o5","texto":"Impide que crezcan las raíces"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Poca en cantidad, pero enorme en las funciones que cumple."}},{"slug":"aire-suelo-2.s3.p3","orden":3,"grupo":"aire-suelo-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una esponja","cuerpo":["Un suelo con buena materia orgánica absorbe la lluvia en vez de dejarla escurrir, y la guarda para las plantas durante los días secos. Por eso los suelos con más materia orgánica resisten mejor las sequías y reducen las inundaciones, como viste en la rama de Agua con los humedales."]},"solucion":{}},{"slug":"aire-suelo-2.s3.p4","orden":4,"grupo":"aire-suelo-2.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un suelo con más materia orgánica resiste mejor una sequía.","items":[{"id":"i1","texto":"El suelo tiene mucha materia orgánica"},{"id":"i2","texto":"Forma grumos y poros que absorben la lluvia"},{"id":"i3","texto":"Guarda más agua después de cada lluvia"},{"id":"i4","texto":"Las plantas tienen agua disponible más días"},{"id":"i5","texto":"El cultivo sufre menos la sequía"},{"id":"i6","texto":"La materia orgánica produce lluvia"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuidar la materia orgánica es una forma de adaptarse al cambio climático."}},{"slug":"aire-suelo-2.s3.p5","orden":5,"grupo":"aire-suelo-2.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El mayor depósito de carbono de la tierra firme","cuerpo":["La materia orgánica está hecha en buena parte de carbono, que las plantas tomaron del aire con la fotosíntesis. Los suelos del mundo guardan, en su primer metro, alrededor de 1.500 gigatoneladas de carbono: más que toda la atmósfera y más que toda la vegetación.","Cuando un suelo se degrada, se ara intensamente o se quema, parte de ese carbono vuelve al aire como CO₂. Cuando se maneja bien, puede recuperar materia orgánica y guardar carbono."],"datos":{"tipo":"barras","titulo":"Dónde está el carbono (aproximado)","unidad":"gigatoneladas de carbono","filas":[{"etiqueta":"Suelos (primer metro)","valor":1500},{"etiqueta":"Atmósfera","valor":875},{"etiqueta":"Vegetación","valor":450}],"nota":"Órdenes de magnitud aproximados de la literatura científica."}},"solucion":{}},{"slug":"aire-suelo-2.s3.p6","orden":6,"grupo":"aire-suelo-2.s3.p6","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos depósitos de carbono de mayor a menor (aproximado).","items":[{"id":"i1","texto":"Suelos (primer metro)"},{"id":"i2","texto":"Atmósfera"},{"id":"i3","texto":"Vegetación de todo el planeta"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"El suelo guarda más carbono que el aire y las plantas. Perderlo tiene un efecto directo sobre el clima.","valores":{"i1":"≈ 1.500 Gt C","i2":"≈ 875 Gt C","i3":"≈ 450 Gt C"}}},{"slug":"aire-suelo-2.s3.p7","orden":7,"grupo":"aire-suelo-2.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El suelo guarda más carbono que toda la vegetación del planeta.","razones":[{"id":"r1","texto":"Porque su materia orgánica acumula muchísimo carbono"},{"id":"r2","texto":"Porque los suelos están hechos de carbón mineral"},{"id":"r3","texto":"Porque las plantas no tienen carbono"}]},"solucion":{"valor":true,"explicacion":"En su primer metro guarda alrededor de 1.500 gigatoneladas, contra unas 450 de la vegetación. Por eso cuidar la materia orgánica del suelo es también cuidar el clima.","clave":["r1"]}},{"slug":"aire-suelo-2.s3.p8","orden":8,"grupo":"aire-suelo-2.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo de 100 hectáreas pierde 2 toneladas de carbono del suelo por hectárea por mal manejo. ¿Cuántas toneladas de carbono pierde en total?","unidad":"toneladas de carbono","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"100 × 2 = 200 t de carbono, que vuelven al aire como CO₂. Cada tonelada de carbono equivale a unas 3,7 t de CO₂."}},{"slug":"aire-suelo-2.s3.p8.v2","orden":8,"grupo":"aire-suelo-2.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo de 500 hectáreas pierde 1 toneladas de carbono del suelo por hectárea por mal manejo. ¿Cuántas toneladas de carbono pierde en total?","unidad":"toneladas de carbono","decimales":0},"solucion":{"valor":500,"tolerancia":10,"explicacion":"500 × 1 = 500 t de carbono, que vuelven al aire como CO₂. Cada tonelada de carbono equivale a unas 3,7 t de CO₂."}},{"slug":"aire-suelo-2.s3.p8.v3","orden":8,"grupo":"aire-suelo-2.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo de 1.000 hectáreas pierde 3 toneladas de carbono del suelo por hectárea por mal manejo. ¿Cuántas toneladas de carbono pierde en total?","unidad":"toneladas de carbono","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"1.000 × 3 = 3.000 t de carbono, que vuelven al aire como CO₂. Cada tonelada de carbono equivale a unas 3,7 t de CO₂."}},{"slug":"aire-suelo-2.s3.p9","orden":9,"grupo":"aire-suelo-2.s3.p9","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"De carbono a CO₂","planteo":"Un suelo pierde 10 toneladas de carbono. ¿Cuánto CO₂ es? El CO₂ pesa unas 3,67 veces más que el carbono solo, porque suma dos oxígenos.","pasos":["Carbono perdido: 10 t.","CO₂: 10 × 3,67 ≈ 36,7 t."],"resultado":"Casi 37 toneladas de CO₂ salen de 10 de carbono. Es la misma razón por la que un litro de nafta produce más de 2 kg de CO₂."},"solucion":{}},{"slug":"aire-suelo-2.s3.p10","orden":10,"grupo":"aire-suelo-2.s3.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un suelo pierde 10 toneladas de carbono. Si cada tonelada de carbono forma unas 3,67 t de CO₂, ¿cuántas toneladas de CO₂ son? Redondeá a un decimal.","unidad":"t de CO₂","decimales":1},"solucion":{"valor":36.7,"tolerancia":0.2,"explicacion":"10 × 3,67 ≈ 36,7 t de CO₂. El carbono toma oxígeno del aire al convertirse en CO₂."}},{"slug":"aire-suelo-2.s3.p10.v2","orden":10,"grupo":"aire-suelo-2.s3.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un suelo pierde 5 toneladas de carbono. Si cada tonelada de carbono forma unas 3,67 t de CO₂, ¿cuántas toneladas de CO₂ son? Redondeá a un decimal.","unidad":"t de CO₂","decimales":1},"solucion":{"valor":18.4,"tolerancia":0.2,"explicacion":"5 × 3,67 ≈ 18,4 t de CO₂. El carbono toma oxígeno del aire al convertirse en CO₂."}},{"slug":"aire-suelo-2.s3.p10.v3","orden":10,"grupo":"aire-suelo-2.s3.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un suelo pierde 20 toneladas de carbono. Si cada tonelada de carbono forma unas 3,67 t de CO₂, ¿cuántas toneladas de CO₂ son? Redondeá a un decimal.","unidad":"t de CO₂","decimales":1},"solucion":{"valor":73.4,"tolerancia":0.2,"explicacion":"20 × 3,67 ≈ 73,4 t de CO₂. El carbono toma oxígeno del aire al convertirse en CO₂."}},{"slug":"aire-suelo-2.s3.p11","orden":11,"grupo":"aire-suelo-2.s3.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas gigatoneladas de carbono guardan los suelos del mundo en su primer metro.","min":10,"max":100000,"paso":1,"unidad":"Gt C","escala":"log"},"solucion":{"valor":1500,"banda":"log","explicacion":"Alrededor de 1.500 gigatoneladas: más que la atmósfera (unas 875) y que toda la vegetación (unas 450)."}},{"slug":"aire-suelo-2.s3.p12","orden":12,"grupo":"aire-suelo-2.s3.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un suelo oscuro suele ser más fértil que uno claro de la misma zona?","opciones":[{"id":"o1","texto":"Porque tiene más materia orgánica"},{"id":"o2","texto":"Porque absorbe más luz del sol y se calienta"},{"id":"o3","texto":"Porque tiene más arena gruesa"},{"id":"o4","texto":"Porque tiene menos agua y menos aire"}]},"solucion":{"clave":["o1"],"explicacion":"El color oscuro del horizonte superficial es la marca del humus: nutrientes, agua y vida.","por_opcion":{"o3":"La arena no oscurece el suelo; el color oscuro viene del humus."}}},{"slug":"aire-suelo-2.s3.p13","orden":13,"grupo":"aire-suelo-2.s3.p13","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica aumenta o reduce la materia orgánica del suelo?","grupos":[{"id":"g1","nombre":"La aumenta"},{"id":"g2","nombre":"La reduce"}],"items":[{"id":"i1","texto":"Agregar compost"},{"id":"i2","texto":"Arar muy seguido"},{"id":"i3","texto":"Mantener el suelo cubierto con plantas"},{"id":"i4","texto":"Quemar rastrojos"},{"id":"i5","texto":"Pasturas bien manejadas"},{"id":"i6","texto":"Dejar el suelo desnudo muchos meses"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La materia orgánica entra con los restos de plantas y el compost, y se pierde con la labranza intensa, el fuego y el suelo desnudo."}},{"slug":"aire-suelo-2.s3.p14","orden":14,"grupo":"aire-suelo-2.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La materia orgánica le da al suelo su color oscuro."},{"id":"s2","texto":"La materia orgánica no tiene relación con el agua del suelo."},{"id":"s3","texto":"Los suelos guardan más carbono que la atmósfera."},{"id":"s4","texto":"Quemar rastrojos aumenta el carbono del suelo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Materia orgánica: agua, nutrientes, vida y clima en un solo ingrediente.","por_opcion":{"s2":"Retiene agua como una esponja y mejora la infiltración.","s4":"Lo devuelve al aire como CO₂ y deja el suelo sin cobertura."}}},{"slug":"aire-suelo-2.s3.p15","orden":15,"grupo":"aire-suelo-2.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La parte más estable de la materia orgánica se llama {{0}}; un suelo con más materia orgánica retiene más {{1}} y guarda más {{2}}.","banco":[{"id":"w1","texto":"humus"},{"id":"w2","texto":"agua"},{"id":"w3","texto":"carbono"},{"id":"w4","texto":"arcilla"},{"id":"w5","texto":"arena"},{"id":"w6","texto":"oxígeno"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres funciones clave de la materia orgánica, resumidas."}}]},{"slug":"aire-suelo-2.s4","orden":4,"tipo":"leccion","titulo_es":"Cuando el suelo se pierde","bajada_es":"Erosión por agua y viento, compactación, salinización y cemento: cómo se degrada el suelo.","minutos":11,"pasos":[{"slug":"aire-suelo-2.s4.p1","orden":1,"grupo":"aire-suelo-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un problema mundial","cuerpo":["Según la FAO, alrededor de un tercio de los suelos del mundo está moderada o altamente degradado. Las causas principales son la erosión, la pérdida de materia orgánica, la compactación, la salinización, la contaminación y el sellado bajo construcciones.","En Argentina, la erosión hídrica y eólica afecta a decenas de millones de hectáreas, según estimaciones del INTA."],"destacado":{"valor":"≈ 1/3","texto":"de los suelos del mundo está moderada o altamente degradado, según la FAO."}},"solucion":{}},{"slug":"aire-suelo-2.s4.p2","orden":2,"grupo":"aire-suelo-2.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada forma de degradación con su causa típica.","izquierda":[{"id":"a1","texto":"Erosión hídrica"},{"id":"a2","texto":"Erosión eólica"},{"id":"a3","texto":"Compactación"},{"id":"a4","texto":"Salinización"}],"derecha":[{"id":"b1","texto":"Lluvia sobre suelo desnudo en pendiente"},{"id":"b2","texto":"Viento sobre suelo seco y sin cobertura"},{"id":"b3","texto":"Maquinaria pesada o pisoteo excesivo"},{"id":"b4","texto":"Riego con mal drenaje en zonas secas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada forma de degradación tiene su causa y su solución."}},{"slug":"aire-suelo-2.s4.p3","orden":3,"grupo":"aire-suelo-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Erosión por agua y viento","cuerpo":["La erosión hídrica ocurre cuando la lluvia golpea un suelo desnudo, desarma los grumos y el agua que corre arrastra la capa superficial. En pendientes forma surcos y cárcavas.","La erosión eólica ocurre cuando el viento levanta las partículas de un suelo seco y sin cobertura. En la década de 1930, sequías y un manejo inadecuado provocaron enormes voladuras de suelo en el oeste de la región pampeana, algo parecido a lo que ocurrió en Estados Unidos en la misma época."]},"solucion":{}},{"slug":"aire-suelo-2.s4.p4","orden":4,"grupo":"aire-suelo-2.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se forma una cárcava en un campo.","items":[{"id":"i1","texto":"El suelo queda desnudo después de la cosecha"},{"id":"i2","texto":"Una lluvia fuerte golpea el suelo sin protección"},{"id":"i3","texto":"El agua corre por la pendiente arrastrando tierra"},{"id":"i4","texto":"Se forman surcos que se agrandan con cada lluvia"},{"id":"i5","texto":"Aparece una cárcava que corta el campo"},{"id":"i6","texto":"La cárcava se rellena sola en la próxima lluvia"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Todo empieza con el suelo desnudo. La cobertura corta la cadena en el primer eslabón."}},{"slug":"aire-suelo-2.s4.p5","orden":5,"grupo":"aire-suelo-2.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es erosión hídrica o eólica?","grupos":[{"id":"g1","nombre":"Hídrica (agua)"},{"id":"g2","nombre":"Eólica (viento)"}],"items":[{"id":"i1","texto":"Surcos en una ladera después de una tormenta"},{"id":"i2","texto":"Nubes de polvo en un día ventoso y seco"},{"id":"i3","texto":"Agua marrón que sale de un campo arado"},{"id":"i4","texto":"Médanos que avanzan sobre un campo"},{"id":"i5","texto":"Cárcavas en un camino rural"},{"id":"i6","texto":"Alambrados tapados por tierra acumulada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Agua en pendientes y lluvias fuertes; viento en zonas secas y planas sin cobertura."}},{"slug":"aire-suelo-2.s4.p6","orden":6,"grupo":"aire-suelo-2.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La erosión solo es un problema en las montañas.","razones":[{"id":"r1","texto":"Porque también afecta llanuras, con agua y con viento"},{"id":"r2","texto":"Porque en las llanuras no llueve"},{"id":"r3","texto":"Porque el viento no puede mover tierra"}]},"solucion":{"valor":false,"explicacion":"También ocurre en llanuras: la erosión eólica en zonas secas y planas, y la hídrica en lomas y pendientes suaves de la región pampeana.","clave":["r1"]}},{"slug":"aire-suelo-2.s4.p7","orden":7,"grupo":"aire-suelo-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Otras amenazas","cuerpo":["La compactación ocurre cuando maquinaria pesada o el pisoteo aplastan el suelo y cierran sus poros: el agua no infiltra y las raíces no penetran. La salinización se da cuando se acumulan sales, muchas veces por riego con mal drenaje en zonas secas. La contaminación con químicos, hidrocarburos o metales envenena la vida del suelo.","Y el sellado: cada vez que se construye o se pavimenta, el suelo queda bajo el cemento y deja de cumplir sus funciones. En las ciudades, gran parte del suelo está sellado."]},"solucion":{}},{"slug":"aire-suelo-2.s4.p8","orden":8,"grupo":"aire-suelo-2.s4.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas son formas de degradación del suelo? Marcá todas.","opciones":[{"id":"o1","texto":"Compactación por maquinaria pesada"},{"id":"o2","texto":"Salinización por riego mal drenado"},{"id":"o3","texto":"Sellado bajo pavimento"},{"id":"o4","texto":"Contaminación con hidrocarburos"},{"id":"o5","texto":"Cobertura con restos de cosecha"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La cobertura es justamente una de las mejores formas de proteger el suelo."}},{"slug":"aire-suelo-2.s4.p9","orden":9,"grupo":"aire-suelo-2.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo de 100 hectáreas pierde 10 toneladas de suelo por hectárea por año por erosión. ¿Cuántas toneladas pierde en total por año?","unidad":"toneladas","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"10 × 100 = 1.000 toneladas de suelo por año: decenas o cientos de camiones de la capa más fértil que se van con la lluvia o el viento."}},{"slug":"aire-suelo-2.s4.p9.v2","orden":9,"grupo":"aire-suelo-2.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo de 50 hectáreas pierde 20 toneladas de suelo por hectárea por año por erosión. ¿Cuántas toneladas pierde en total por año?","unidad":"toneladas","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"20 × 50 = 1.000 toneladas de suelo por año: decenas o cientos de camiones de la capa más fértil que se van con la lluvia o el viento."}},{"slug":"aire-suelo-2.s4.p9.v3","orden":9,"grupo":"aire-suelo-2.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo de 200 hectáreas pierde 5 toneladas de suelo por hectárea por año por erosión. ¿Cuántas toneladas pierde en total por año?","unidad":"toneladas","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"5 × 200 = 1.000 toneladas de suelo por año: decenas o cientos de camiones de la capa más fértil que se van con la lluvia o el viento."}},{"slug":"aire-suelo-2.s4.p10","orden":10,"grupo":"aire-suelo-2.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un campo con pendiente suave, ¿cuándo es mayor el riesgo de erosión hídrica?","opciones":[{"id":"o1","texto":"Con el suelo desnudo y una tormenta fuerte"},{"id":"o2","texto":"Con el cultivo en pleno crecimiento y lluvia suave"},{"id":"o3","texto":"Con el suelo cubierto de rastrojos y sequía"},{"id":"o4","texto":"Con pasturas densas en otoño"}]},"solucion":{"clave":["o1"],"explicacion":"Suelo desnudo más lluvia intensa: la combinación más peligrosa.","por_opcion":{"o3":"Sin lluvia no hay erosión hídrica; y los rastrojos protegen."}}},{"slug":"aire-suelo-2.s4.p11","orden":11,"grupo":"aire-suelo-2.s4.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas situaciones por riesgo de erosión, de mayor a menor.","items":[{"id":"i1","texto":"Suelo arado y desnudo en pendiente, con tormenta"},{"id":"i2","texto":"Suelo desnudo en llano, con lluvia moderada"},{"id":"i3","texto":"Suelo con rastrojos en pendiente"},{"id":"i4","texto":"Pastizal denso en llano"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cobertura y pendiente son las dos variables más importantes.","valores":{"i1":"muy alto","i2":"alto","i3":"bajo","i4":"muy bajo"}}},{"slug":"aire-suelo-2.s4.p12","orden":12,"grupo":"aire-suelo-2.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Un tercio de los suelos del mundo está degradado."},{"id":"s2","texto":"La erosión solo se lleva la tierra de abajo, que no sirve."},{"id":"s3","texto":"La compactación impide que el agua infiltre."},{"id":"s4","texto":"Pavimentar no afecta al suelo porque queda debajo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Perder suelo es perder la capa más valiosa, y no vuelve pronto.","por_opcion":{"s2":"Se lleva la capa superficial, la más fértil y con más vida.","s4":"El suelo sellado deja de infiltrar agua y de sostener vida."}}},{"slug":"aire-suelo-2.s4.p13","orden":13,"grupo":"aire-suelo-2.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La erosión {{0}} la causa el agua y la {{1}} el viento; las dos empiezan casi siempre con el suelo {{2}}.","banco":[{"id":"w1","texto":"hídrica"},{"id":"w2","texto":"eólica"},{"id":"w3","texto":"desnudo"},{"id":"w4","texto":"térmica"},{"id":"w5","texto":"química"},{"id":"w6","texto":"mojado"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La clave para prevenir la erosión, en una línea."}}]},{"slug":"aire-suelo-2.s5","orden":5,"tipo":"leccion","titulo_es":"Cuidar el suelo","bajada_es":"Cobertura, siembra directa, rotaciones, compost y más verde en la ciudad: cómo conservar y recuperar suelos.","minutos":12,"pasos":[{"slug":"aire-suelo-2.s5.p1","orden":1,"grupo":"aire-suelo-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los principios","cuerpo":["Las prácticas que conservan el suelo se resumen en pocos principios: mantenerlo cubierto (con plantas vivas o restos), moverlo lo menos posible, mantener raíces vivas la mayor parte del año, diversificar los cultivos y devolverle materia orgánica.","Estos principios son la base de la agricultura de conservación y de la agricultura regenerativa, y se aplican tanto en un campo de mil hectáreas como en una huerta."],"lista":["Suelo siempre cubierto","Mínimo movimiento","Raíces vivas todo el año","Diversidad de cultivos","Devolver materia orgánica"]},"solucion":{}},{"slug":"aire-suelo-2.s5.p2","orden":2,"grupo":"aire-suelo-2.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos son principios de conservación del suelo? Marcá todos.","opciones":[{"id":"o1","texto":"Mantener el suelo cubierto"},{"id":"o2","texto":"Moverlo lo menos posible"},{"id":"o3","texto":"Mantener raíces vivas la mayor parte del año"},{"id":"o4","texto":"Diversificar los cultivos"},{"id":"o5","texto":"Dejarlo desnudo para que \"descanse\""}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un suelo desnudo no descansa: se erosiona y pierde vida."}},{"slug":"aire-suelo-2.s5.p3","orden":3,"grupo":"aire-suelo-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siembra directa y cultivos de cobertura","cuerpo":["En la siembra directa, se siembra sin arar, sobre los restos del cultivo anterior, que quedan como una cobertura protectora. Argentina es uno de los países con mayor adopción de la siembra directa del mundo: se usa en la gran mayoría de la superficie agrícola.","Los cultivos de cobertura (o de servicio) se siembran entre dos cultivos de cosecha, no para vender, sino para cubrir el suelo, sumar raíces y materia orgánica y, si son legumbres, aportar nitrógeno."]},"solucion":{}},{"slug":"aire-suelo-2.s5.p4","orden":4,"grupo":"aire-suelo-2.s5.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada práctica con su beneficio principal.","izquierda":[{"id":"a1","texto":"Siembra directa"},{"id":"a2","texto":"Cultivo de cobertura"},{"id":"a3","texto":"Rotación de cultivos"},{"id":"a4","texto":"Compost"}],"derecha":[{"id":"b1","texto":"Menos movimiento del suelo y cobertura con rastrojos"},{"id":"b2","texto":"Raíces vivas y suelo protegido entre cosechas"},{"id":"b3","texto":"Diversidad que corta plagas y equilibra nutrientes"},{"id":"b4","texto":"Devolver materia orgánica al suelo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro herramientas que funcionan mejor combinadas entre sí."}},{"slug":"aire-suelo-2.s5.p5","orden":5,"grupo":"aire-suelo-2.s5.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La siembra directa, por sí sola, resuelve todos los problemas del suelo.","razones":[{"id":"r1","texto":"Porque necesita rotaciones y aportes de materia orgánica"},{"id":"r2","texto":"Porque la siembra directa aumenta la erosión"},{"id":"r3","texto":"Porque la siembra directa no se usa en Argentina"}]},"solucion":{"valor":false,"explicacion":"Protege mucho contra la erosión, pero si no se rota y se aporta poca materia orgánica, el suelo igual se degrada. Funciona mejor combinada con rotaciones y cultivos de cobertura.","clave":["r1"]}},{"slug":"aire-suelo-2.s5.p6","orden":6,"grupo":"aire-suelo-2.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Rotar y diversificar","cuerpo":["Sembrar siempre el mismo cultivo en el mismo lugar (monocultivo) agota ciertos nutrientes y favorece plagas y enfermedades de ese cultivo. Rotar —por ejemplo, alternar maíz, soja y trigo, o incluir pasturas— equilibra el suelo, corta los ciclos de las plagas y suma distintos tipos de raíces.","Las rotaciones con gramíneas como el maíz o el trigo aportan mucho rastrojo; las legumbres aportan nitrógeno."]},"solucion":{}},{"slug":"aire-suelo-2.s5.p7","orden":7,"grupo":"aire-suelo-2.s5.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el monocultivo de soja puede empobrecer el suelo.","items":[{"id":"i1","texto":"Se siembra soja año tras año en el mismo lote"},{"id":"i2","texto":"La soja deja poco rastrojo"},{"id":"i3","texto":"Entra poca materia orgánica al suelo"},{"id":"i4","texto":"La materia orgánica baja con los años"},{"id":"i5","texto":"El suelo retiene menos agua y es más vulnerable a la erosión"},{"id":"i6","texto":"La soja deja tanto rastrojo que el suelo se tapa"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso se recomienda rotar la soja con gramíneas y cultivos de cobertura."}},{"slug":"aire-suelo-2.s5.p8","orden":8,"grupo":"aire-suelo-2.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"En la ciudad y en casa","cuerpo":["En las ciudades también se puede cuidar el suelo: compostar los restos orgánicos y devolverlos a canteros y huertas, cubrir la tierra con mulch, evitar pisar y compactar los canteros, y reemplazar superficies selladas por superficies absorbentes cuando se puede.","Una huerta en casa, con compost y cobertura, puede tener un suelo más vivo en pocos años."]},"solucion":{}},{"slug":"aire-suelo-2.s5.p9","orden":9,"grupo":"aire-suelo-2.s5.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción en la ciudad cuida o daña el suelo?","grupos":[{"id":"g1","nombre":"Lo cuida"},{"id":"g2","nombre":"Lo daña"}],"items":[{"id":"i1","texto":"Cubrir los canteros con hojas secas"},{"id":"i2","texto":"Estacionar autos sobre el cantero"},{"id":"i3","texto":"Agregar compost a la huerta"},{"id":"i4","texto":"Tirar aceite usado en la tierra"},{"id":"i5","texto":"Reemplazar un patio de cemento por pasto y plantas"},{"id":"i6","texto":"Barrer y tirar todas las hojas del jardín a la basura"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las hojas secas son alimento y abrigo para el suelo. Tirarlas es tirar materia orgánica."}},{"slug":"aire-suelo-2.s5.p10","orden":10,"grupo":"aire-suelo-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia composta 15 kg de restos orgánicos por semana. Si el compost final pesa el 30 % de lo que entra, ¿cuántos kilos de compost obtiene en un año de 52 semanas?","unidad":"kg","decimales":1},"solucion":{"valor":234,"tolerancia":4.68,"explicacion":"15 × 52 × 30 ÷ 100 = 234 kg de compost por año: materia orgánica que vuelve al suelo en vez de ir al relleno."}},{"slug":"aire-suelo-2.s5.p10.v2","orden":10,"grupo":"aire-suelo-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia composta 10 kg de restos orgánicos por semana. Si el compost final pesa el 30 % de lo que entra, ¿cuántos kilos de compost obtiene en un año de 52 semanas?","unidad":"kg","decimales":1},"solucion":{"valor":156,"tolerancia":3.12,"explicacion":"10 × 52 × 30 ÷ 100 = 156 kg de compost por año: materia orgánica que vuelve al suelo en vez de ir al relleno."}},{"slug":"aire-suelo-2.s5.p10.v3","orden":10,"grupo":"aire-suelo-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia composta 20 kg de restos orgánicos por semana. Si el compost final pesa el 25 % de lo que entra, ¿cuántos kilos de compost obtiene en un año de 52 semanas?","unidad":"kg","decimales":1},"solucion":{"valor":260,"tolerancia":5.2,"explicacion":"20 × 52 × 25 ÷ 100 = 260 kg de compost por año: materia orgánica que vuelve al suelo en vez de ir al relleno."}},{"slug":"aire-suelo-2.s5.p11","orden":11,"grupo":"aire-suelo-2.s5.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con las hojas secas que caen en el jardín en otoño?","opciones":[{"id":"o1","texto":"Usarlas como cobertura o en el compost"},{"id":"o2","texto":"Quemarlas en una pila en la vereda"},{"id":"o3","texto":"Tirarlas en bolsas con la basura común"},{"id":"o4","texto":"Barrerlas hacia la alcantarilla de la calle"}]},"solucion":{"clave":["o1"],"explicacion":"Las hojas son el abono natural del suelo. Quemarlas contamina el aire; tirarlas al desagüe tapa alcantarillas.","por_opcion":{"o3":"Se pierde materia orgánica valiosa que termina en el relleno."}}},{"slug":"aire-suelo-2.s5.p12","orden":12,"grupo":"aire-suelo-2.s5.p12","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para recuperar un cantero compactado y pobre.","items":[{"id":"i1","texto":"Aflojar la tierra sin darla vuelta"},{"id":"i2","texto":"Agregar una capa de compost"},{"id":"i3","texto":"Plantar especies con raíces variadas"},{"id":"i4","texto":"Cubrir con mulch de hojas"},{"id":"i5","texto":"Evitar pisarlo y observar la vida que aparece"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Aflojar, alimentar, plantar, cubrir y proteger: los principios aplicados a un cantero."}},{"slug":"aire-suelo-2.s5.p13","orden":13,"grupo":"aire-suelo-2.s5.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de un productor y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Voy a sembrar un cultivo de cobertura en invierno."},{"id":"s2","texto":"Después de cosechar, quemo el rastrojo para limpiar el lote."},{"id":"s3","texto":"Voy a rotar soja con maíz y trigo."},{"id":"s4","texto":"Voy a arar profundo todos los años para airear."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cubrir, no mover, rotar y alimentar: el plan de cualquier suelo sano.","por_opcion":{"s2":"Se pierde materia orgánica y el suelo queda desnudo.","s4":"La labranza intensa acelera la pérdida de materia orgánica y la erosión."}}},{"slug":"aire-suelo-2.s5.p14","orden":14,"grupo":"aire-suelo-2.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para conservar el suelo hay que mantenerlo {{0}}, moverlo lo {{1}} posible y {{2}} los cultivos.","banco":[{"id":"w1","texto":"cubierto"},{"id":"w2","texto":"menos"},{"id":"w3","texto":"rotar"},{"id":"w4","texto":"desnudo"},{"id":"w5","texto":"más"},{"id":"w6","texto":"quemar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres principios de la agricultura de conservación."}}]},{"slug":"aire-suelo-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el suelo vivo","bajada_es":"Componentes, vida, materia orgánica, degradación y conservación, mezclados.","minutos":8,"pasos":[{"slug":"aire-suelo-2.s6.p1","orden":1,"grupo":"aire-suelo-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El suelo vivo». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"aire-suelo-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el campo de los Benítez","bajada_es":"Un campo del sudeste bonaerense muestra señales de un suelo que se agota. Hacé el diagnóstico y armá un plan.","minutos":10,"pasos":[{"slug":"aire-suelo-2.s7.p1","orden":1,"grupo":"aire-suelo-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El campo","cuerpo":["Los Benítez tienen 300 hectáreas con lomas suaves. Hace diez años siembran soja todos los años, sin cultivos de cobertura, y el suelo queda desnudo desde la cosecha hasta la siembra siguiente. Algunos años queman los restos.","Un análisis mostró que la materia orgánica bajó del 5 % al 3,5 % en diez años. Después de cada tormenta se ven surcos en las lomas y agua marrón en los bajos. En una palada contaron 2 lombrices."]},"solucion":{}},{"slug":"aire-suelo-2.s7.p2","orden":2,"grupo":"aire-suelo-2.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje bajó la materia orgánica del suelo respecto del valor inicial?","unidad":"%","decimales":0,"contexto":"Materia orgánica: 5 % hace diez años, 3,5 % hoy."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Bajó 5 − 3,5 = 1,5 puntos sobre 5: 1,5 ÷ 5 × 100 = 30 %. Casi un tercio de la materia orgánica en diez años."}},{"slug":"aire-suelo-2.s7.p3","orden":3,"grupo":"aire-suelo-2.s7.p3","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales indican que el suelo de los Benítez se está degradando? Marcá todas.","opciones":[{"id":"o1","texto":"La materia orgánica bajó un 30 %"},{"id":"o2","texto":"Surcos en las lomas después de las tormentas"},{"id":"o3","texto":"Agua marrón en los bajos"},{"id":"o4","texto":"Muy pocas lombrices por palada"},{"id":"o5","texto":"Que el campo tenga lomas suaves"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las lomas son el relieve natural; las otras cuatro son síntomas de degradación."}},{"slug":"aire-suelo-2.s7.p4","orden":4,"grupo":"aire-suelo-2.s7.p4","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena que explica lo que le pasa al campo.","items":[{"id":"i1","texto":"Monocultivo de soja con poco rastrojo y quemas"},{"id":"i2","texto":"Entra poca materia orgánica al suelo"},{"id":"i3","texto":"Baja la vida del suelo y se desarman los grumos"},{"id":"i4","texto":"El suelo absorbe menos agua de lluvia"},{"id":"i5","texto":"El agua corre por las lomas y se lleva la capa fértil"},{"id":"i6","texto":"La soja atrae tormentas más fuertes"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Manejo, materia orgánica, estructura, agua y erosión: todos los eslabones de la unidad en un solo campo."}},{"slug":"aire-suelo-2.s7.p5","orden":5,"grupo":"aire-suelo-2.s7.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas del plan por prioridad, de la primera a la última.","items":[{"id":"i1","texto":"Dejar de quemar rastrojos"},{"id":"i2","texto":"Sembrar cultivos de cobertura en invierno"},{"id":"i3","texto":"Rotar la soja con maíz y trigo"},{"id":"i4","texto":"Medir materia orgánica y lombrices cada año"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero se deja de dañar; después se protege y se alimenta; y se mide para saber si funciona.","valores":{"i1":"inmediata y gratis","i2":"protege el suelo desnudo","i3":"suma rastrojo y diversidad","i4":"verifica que funcione"}}},{"slug":"aire-suelo-2.s7.p6","orden":6,"grupo":"aire-suelo-2.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si las lomas de los Benítez (100 de las 300 hectáreas) pierden 15 toneladas de suelo por hectárea por año, ¿cuántas toneladas pierden por año?","unidad":"toneladas","decimales":0},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"15 × 100 = 1.500 toneladas de la capa más fértil por año. A ese ritmo, en pocas décadas se pierden centímetros que tardaron siglos en formarse."}},{"slug":"aire-suelo-2.s7.p6.v2","orden":6,"grupo":"aire-suelo-2.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si las lomas de los Benítez (100 de las 300 hectáreas) pierden 10 toneladas de suelo por hectárea por año, ¿cuántas toneladas pierden por año?","unidad":"toneladas","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"10 × 100 = 1.000 toneladas de la capa más fértil por año. A ese ritmo, en pocas décadas se pierden centímetros que tardaron siglos en formarse."}},{"slug":"aire-suelo-2.s7.p6.v3","orden":6,"grupo":"aire-suelo-2.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si las lomas de los Benítez (100 de las 300 hectáreas) pierden 20 toneladas de suelo por hectárea por año, ¿cuántas toneladas pierden por año?","unidad":"toneladas","decimales":0},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"20 × 100 = 2.000 toneladas de la capa más fértil por año. A ese ritmo, en pocas décadas se pierden centímetros que tardaron siglos en formarse."}},{"slug":"aire-suelo-2.s7.p7","orden":7,"grupo":"aire-suelo-2.s7.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un vecino les dice que agreguen más fertilizante y listo. ¿Qué le responderías?","opciones":[{"id":"o1","texto":"Que el fertilizante no repone materia orgánica ni frena la erosión"},{"id":"o2","texto":"Que tiene razón: con fertilizante el suelo se recupera solo"},{"id":"o3","texto":"Que el fertilizante está prohibido en Argentina"},{"id":"o4","texto":"Que conviene arar más profundo para mezclar el fertilizante"}]},"solucion":{"clave":["o1"],"explicacion":"Los fertilizantes aportan nutrientes, pero no reconstruyen la estructura ni la vida del suelo, ni lo protegen de la lluvia.","por_opcion":{"o3":"No está prohibido; el punto es que no resuelve la causa del problema."}}},{"slug":"aire-suelo-2.s7.p8","orden":8,"grupo":"aire-suelo-2.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Los Benítez escriben su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Este año dejamos de quemar los rastrojos."},{"id":"s2","texto":"Vamos a arar todo para emparejar los surcos."},{"id":"s3","texto":"Sembramos centeno como cultivo de cobertura en invierno."},{"id":"s4","texto":"Seguimos con soja todos los años porque es lo más rentable ahora."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan de suelos piensa en décadas, no solo en la próxima cosecha.","por_opcion":{"s2":"Arar deja el suelo más expuesto y acelera la pérdida de materia orgánica.","s4":"El monocultivo sin rotación es parte de la causa del problema."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"aire-suelo-3","rama":"aire_suelo","orden":3,"nivel":2,"titulo_es":"El efecto invernadero","bajada_es":"Por qué la Tierra no es una bola de hielo, cuánto subió el CO₂, cómo sabemos que viene de los combustibles fósiles y cuánto se calentó el planeta.","objetivos_es":["Explicar cómo los gases de efecto invernadero retienen calor","Leer la curva del CO₂ y compararla con los últimos 800.000 años","Justificar con evidencia que el CO₂ extra viene de los combustibles fósiles","Comparar metano, óxido nitroso y CO₂ por su efecto y duración","Distinguir tiempo y clima, y reconocer las huellas del calentamiento humano"],"repasa":["aire-suelo-1","aire-suelo-2","tronco-2","tronco-1"],"requiere_tronco":2,"fuentes":["nasa-evidencia","noaa-co2","noaa-co2-historia","global-carbon-budget","ipcc-ar6","nasa-gistemp","copernicus-clima-2024","wmo-clima-2024","inventario-gei-ar","consenso-cook-2016"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"aire-suelo-3.s1","orden":1,"tipo":"leccion","titulo_es":"La manta del planeta","bajada_es":"La luz del sol entra, el calor sale con dificultad: cómo funciona el efecto invernadero natural.","minutos":14,"pasos":[{"slug":"aire-suelo-3.s1.p1","orden":1,"grupo":"aire-suelo-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Luz que entra, calor que sale","cuerpo":["La luz del sol atraviesa casi sin obstáculos la atmósfera y calienta la superficie de la Tierra. La superficie caliente, a su vez, emite energía hacia el espacio, pero no como luz visible sino como radiación infrarroja, la misma que sentís cerca de una estufa sin tocarla.","Algunos gases de la atmósfera absorben esa radiación infrarroja y la vuelven a emitir en todas las direcciones, una parte de nuevo hacia la superficie. Así, la Tierra pierde calor más despacio y se mantiene más templada. Eso es el efecto invernadero."]},"solucion":{}},{"slug":"aire-suelo-3.s1.p2","orden":2,"grupo":"aire-suelo-3.s1.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del efecto invernadero.","items":[{"id":"i1","texto":"La luz del sol atraviesa la atmósfera"},{"id":"i2","texto":"La superficie de la Tierra se calienta"},{"id":"i3","texto":"La superficie emite radiación infrarroja"},{"id":"i4","texto":"Los gases de efecto invernadero la absorben"},{"id":"i5","texto":"Reemiten parte de esa energía hacia la superficie"},{"id":"i6","texto":"Los gases reflejan la luz del sol hacia el espacio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La clave está en que la atmósfera deja pasar la luz, pero frena la salida del infrarrojo."}},{"slug":"aire-suelo-3.s1.p3","orden":3,"grupo":"aire-suelo-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un efecto natural y necesario","cuerpo":["Sin efecto invernadero, la temperatura media de la Tierra sería de unos −18 °C: un planeta congelado. Con él, es de unos +15 °C. El problema no es el efecto invernadero en sí, sino que lo estamos intensificando al agregar gases a la atmósfera."],"destacado":{"valor":"−18 °C","texto":"sería la temperatura media de la Tierra sin el efecto invernadero natural. Hoy es de unos +15 °C."}},"solucion":{}},{"slug":"aire-suelo-3.s1.p4","orden":4,"grupo":"aire-suelo-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si sin efecto invernadero la temperatura media sería de −18 °C y hoy es de +15 °C, ¿cuántos grados aporta el efecto invernadero natural?","unidad":"°C","decimales":0,"contexto":"Sin efecto invernadero −18 °C; con él, +15 °C."},"solucion":{"valor":33,"tolerancia":0.66,"explicacion":"De −18 a +15 hay 33 grados. Ese es el aporte del efecto invernadero natural: sin él, no habría agua líquida en la mayor parte del planeta."}},{"slug":"aire-suelo-3.s1.p5","orden":5,"grupo":"aire-suelo-3.s1.p5","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El efecto invernadero es algo malo que hay que eliminar.","razones":[{"id":"r1","texto":"Porque el efecto natural hace habitable el planeta"},{"id":"r2","texto":"Porque el efecto invernadero no existe"},{"id":"r3","texto":"Porque solo ocurre dentro de los invernaderos"}]},"solucion":{"valor":false,"explicacion":"El efecto invernadero natural hace habitable la Tierra. El problema es intensificarlo agregando gases, que es lo que hacemos al quemar combustibles fósiles y desmontar.","clave":["r1"]}},{"slug":"aire-suelo-3.s1.p6","orden":6,"grupo":"aire-suelo-3.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué gases lo producen","cuerpo":["Los gases de efecto invernadero principales son el vapor de agua, el dióxido de carbono (CO₂), el metano (CH₄), el óxido nitroso (N₂O) y los gases fluorados, que son industriales. El nitrógeno y el oxígeno, que forman el 99 % del aire seco, no absorben radiación infrarroja: no son gases de efecto invernadero.","Un gas puede ser muy escaso y tener un gran efecto: el CO₂ es apenas un 0,04 % del aire, pero es clave para el balance de calor."]},"solucion":{}},{"slug":"aire-suelo-3.s1.p7","orden":7,"grupo":"aire-suelo-3.s1.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un gas de efecto invernadero o no?","grupos":[{"id":"g1","nombre":"Gas de efecto invernadero"},{"id":"g2","nombre":"No retiene infrarrojo"}],"items":[{"id":"i1","texto":"Dióxido de carbono"},{"id":"i2","texto":"Nitrógeno"},{"id":"i3","texto":"Metano"},{"id":"i4","texto":"Oxígeno"},{"id":"i5","texto":"Óxido nitroso"},{"id":"i6","texto":"Argón"},{"id":"i7","texto":"Vapor de agua"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1"},"explicacion":"Los gases más abundantes del aire no retienen infrarrojo. Los que sí lo hacen están en proporciones pequeñas."}},{"slug":"aire-suelo-3.s1.p8","orden":8,"grupo":"aire-suelo-3.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"El CO₂ es solo un 0,04 % del aire. ¿Cómo puede tener tanto efecto?","opciones":[{"id":"o1","texto":"Absorbe el infrarrojo, cosa que el nitrógeno no hace"},{"id":"o2","texto":"Porque es un gas tóxico que calienta al respirarlo"},{"id":"o3","texto":"Porque es más pesado y se junta en el suelo"},{"id":"o4","texto":"Porque refleja la luz del sol hacia la Tierra"}]},"solucion":{"clave":["o1"],"explicacion":"Que algo sea escaso no quiere decir que no importe: una gota de tinta tiñe un vaso de agua.","por_opcion":{"o3":"Se mezcla en toda la atmósfera; su efecto viene de absorber infrarrojo."}}},{"slug":"aire-suelo-3.s1.p9","orden":9,"grupo":"aire-suelo-3.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El vapor de agua, un amplificador","cuerpo":["El vapor de agua es el gas de efecto invernadero que más contribuye al efecto natural. Pero su cantidad depende de la temperatura: el aire más cálido puede contener más vapor. Por eso funciona como un amplificador: si otros gases calientan un poco el planeta, se evapora más agua, y ese vapor extra calienta todavía más. Es una retroalimentación."]},"solucion":{}},{"slug":"aire-suelo-3.s1.p10","orden":10,"grupo":"aire-suelo-3.s1.p10","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la retroalimentación del vapor de agua.","items":[{"id":"i1","texto":"Aumenta el CO₂ en la atmósfera"},{"id":"i2","texto":"La temperatura sube un poco"},{"id":"i3","texto":"Se evapora más agua y el aire guarda más vapor"},{"id":"i4","texto":"El vapor extra retiene más calor"},{"id":"i5","texto":"La temperatura sube un poco más"},{"id":"i6","texto":"El vapor extra enfría el planeta de inmediato"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una retroalimentación amplifica un cambio inicial. Por eso pequeños aumentos de CO₂ tienen efectos mayores."}},{"slug":"aire-suelo-3.s1.p11","orden":11,"grupo":"aire-suelo-3.s1.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su descripción.","izquierda":[{"id":"a1","texto":"Radiación infrarroja"},{"id":"a2","texto":"Gas de efecto invernadero"},{"id":"a3","texto":"Retroalimentación"},{"id":"a4","texto":"Efecto invernadero natural"}],"derecha":[{"id":"b1","texto":"Calor que emite la superficie terrestre"},{"id":"b2","texto":"Absorbe y reemite radiación infrarroja"},{"id":"b3","texto":"Un cambio que amplifica el cambio inicial"},{"id":"b4","texto":"Mantiene la Tierra unos 33 °C más cálida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ideas para explicar el efecto invernadero sin confundirse."}},{"slug":"aire-suelo-3.s1.p12","orden":12,"grupo":"aire-suelo-3.s1.p12","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"¿Por qué \"invernadero\"?","cuerpo":["El nombre viene de una comparación con los invernaderos de plantas, pero no es exacta: un invernadero se mantiene cálido sobre todo porque sus paredes impiden que el aire caliente se escape y se mezcle con el de afuera. En la atmósfera, en cambio, lo que se frena es la salida de radiación infrarroja. La comparación sirve para empezar, pero conviene conocer el mecanismo real."]},"solucion":{}},{"slug":"aire-suelo-3.s1.p13","orden":13,"grupo":"aire-suelo-3.s1.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué afirmaciones sobre el efecto invernadero son correctas? Marcá todas.","opciones":[{"id":"o1","texto":"Sin él, la Tierra sería mucho más fría"},{"id":"o2","texto":"Lo producen gases que absorben infrarrojo"},{"id":"o3","texto":"El vapor de agua amplifica los cambios"},{"id":"o4","texto":"El nitrógeno es el principal gas de efecto invernadero"},{"id":"o5","texto":"Funciona exactamente igual que un invernadero de plantas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El nitrógeno no retiene infrarrojo, y la comparación con el invernadero de plantas es solo aproximada."}},{"slug":"aire-suelo-3.s1.p14","orden":14,"grupo":"aire-suelo-3.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación de un compañero y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La luz del sol calienta la superficie de la Tierra."},{"id":"s2","texto":"La Tierra devuelve el calor como luz visible, que los gases atrapan."},{"id":"s3","texto":"El vapor de agua amplifica el calentamiento."},{"id":"s4","texto":"Como el CO₂ es escaso, no puede cambiar la temperatura."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Explicar bien el mecanismo ayuda a responder los mitos más comunes.","por_opcion":{"s2":"La superficie emite radiación infrarroja, no luz visible.","s4":"Absorbe infrarrojo: pequeñas cantidades tienen un efecto grande."}}},{"slug":"aire-suelo-3.s1.p15","orden":15,"grupo":"aire-suelo-3.s1.p15","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del aire seco es CO₂.","min":0.001,"max":50,"paso":1,"unidad":"%","escala":"log"},"solucion":{"valor":0.04,"banda":"log","explicacion":"Apenas un 0,04 %, es decir, unas 400 partes por millón. Muy poco en cantidad, pero decisivo para el balance de calor del planeta."}},{"slug":"aire-suelo-3.s1.p16","orden":16,"grupo":"aire-suelo-3.s1.p16","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La superficie de la Tierra emite radiación {{0}}; sin efecto invernadero, la temperatura media sería de unos {{1}} °C; y el vapor de agua funciona como un {{2}}.","banco":[{"id":"w1","texto":"infrarroja"},{"id":"w2","texto":"−18"},{"id":"w3","texto":"amplificador"},{"id":"w4","texto":"ultravioleta"},{"id":"w5","texto":"+40"},{"id":"w6","texto":"filtro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas centrales para explicar el efecto invernadero natural."}}]},{"slug":"aire-suelo-3.s2","orden":2,"tipo":"leccion","titulo_es":"La curva del CO₂","bajada_es":"Del hielo antártico a Mauna Loa: cuánto CO₂ hubo en el aire y cuánto hay ahora.","minutos":12,"pasos":[{"slug":"aire-suelo-3.s2.p1","orden":1,"grupo":"aire-suelo-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El archivo del hielo","cuerpo":["En la Antártida, la nieve se acumula año tras año y se convierte en hielo, atrapando pequeñas burbujas de aire. Al perforar el hielo y analizar esas burbujas, se puede medir cuánto CO₂ había en la atmósfera hace cientos de miles de años. Esos registros muestran que, durante los últimos 800.000 años, el CO₂ osciló aproximadamente entre 180 y 300 partes por millón (ppm), subiendo en los períodos cálidos y bajando en las glaciaciones.","Antes de la Revolución Industrial, el CO₂ estaba en unas 280 ppm."]},"solucion":{}},{"slug":"aire-suelo-3.s2.p2","orden":2,"grupo":"aire-suelo-3.s2.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo se sabe cuánto CO₂ había en el aire hace 500.000 años?","opciones":[{"id":"o1","texto":"Por burbujas de aire atrapadas en el hielo antártico"},{"id":"o2","texto":"Por cálculos a partir de pinturas rupestres antiguas"},{"id":"o3","texto":"Por mediciones de satélites de esa época"},{"id":"o4","texto":"Por los relatos de los primeros exploradores"}]},"solucion":{"clave":["o1"],"explicacion":"El hielo guarda muestras reales de aire antiguo: es un archivo natural de la atmósfera.","por_opcion":{"o3":"No había satélites: los primeros son de la década de 1950."}}},{"slug":"aire-suelo-3.s2.p3","orden":3,"grupo":"aire-suelo-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mauna Loa","cuerpo":["En 1958, el científico Charles David Keeling empezó a medir el CO₂ en el observatorio de Mauna Loa, en Hawái, lejos de ciudades y fábricas. Encontró unas 315 ppm. La medición siguió sin interrupciones y hoy supera las 420 ppm: la llamada curva de Keeling sube año tras año, con un serrucho estacional.","Es la concentración más alta en al menos 800.000 años, y probablemente en millones de años."],"datos":{"tipo":"barras","titulo":"Concentración de CO₂ en la atmósfera (aproximada)","unidad":"ppm","filas":[{"etiqueta":"Mínimo de glaciaciones","valor":180},{"etiqueta":"Máximo de 800.000 años","valor":300},{"etiqueta":"Antes de 1750","valor":280},{"etiqueta":"1958 (Mauna Loa)","valor":315},{"etiqueta":"2024 (Mauna Loa)","valor":425}],"nota":"Testigos de hielo y registro de Mauna Loa, NOAA; valores redondeados."}},"solucion":{}},{"slug":"aire-suelo-3.s2.p4","orden":4,"grupo":"aire-suelo-3.s2.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos momentos según la concentración de CO₂, de menor a mayor.","items":[{"id":"i1","texto":"Una glaciación"},{"id":"i2","texto":"Antes de la Revolución Industrial"},{"id":"i3","texto":"Primera medición de Keeling, 1958"},{"id":"i4","texto":"Hoy"}],"extremos":["Menos CO₂","Más CO₂"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El salto de los últimos dos siglos supera todo lo que muestran 800.000 años de hielo.","valores":{"i1":"≈ 180 ppm","i2":"≈ 280 ppm","i3":"≈ 315 ppm","i4":"más de 420 ppm"}}},{"slug":"aire-suelo-3.s2.p5","orden":5,"grupo":"aire-suelo-3.s2.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"¿Cuánto subió?","planteo":"Antes de la Revolución Industrial había unas 280 ppm de CO₂. En 2024, unas 420 ppm.","pasos":["El aumento es 420 − 280 = 140 ppm.","En porcentaje: 140 ÷ 280 × 100 = 50 %."],"resultado":"La concentración de CO₂ aumentó alrededor de un 50 % respecto de la era preindustrial."},"solucion":{}},{"slug":"aire-suelo-3.s2.p6","orden":6,"grupo":"aire-suelo-3.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el CO₂ preindustrial era de 280 ppm y en un año dado llegó a 420 ppm, ¿en qué porcentaje aumentó? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(420 − 280) ÷ 280 × 100 ≈ 50 %. Cada año que siguen las emisiones, el porcentaje crece."}},{"slug":"aire-suelo-3.s2.p6.v2","orden":6,"grupo":"aire-suelo-3.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el CO₂ preindustrial era de 280 ppm y en un año dado llegó a 434 ppm, ¿en qué porcentaje aumentó? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":55,"tolerancia":1,"explicacion":"(434 − 280) ÷ 280 × 100 ≈ 55 %. Cada año que siguen las emisiones, el porcentaje crece."}},{"slug":"aire-suelo-3.s2.p6.v3","orden":6,"grupo":"aire-suelo-3.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el CO₂ preindustrial era de 280 ppm y en un año dado llegó a 448 ppm, ¿en qué porcentaje aumentó? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":60,"tolerancia":1,"explicacion":"(448 − 280) ÷ 280 × 100 ≈ 60 %. Cada año que siguen las emisiones, el porcentaje crece."}},{"slug":"aire-suelo-3.s2.p7","orden":7,"grupo":"aire-suelo-3.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El serrucho","cuerpo":["La curva de Keeling no es lisa: cada año sube y baja un poco. En primavera y verano del hemisferio norte, donde hay mucha más tierra con vegetación, las plantas absorben CO₂ al crecer y la concentración baja; en otoño e invierno, las hojas caen, se descomponen y el CO₂ sube. Es la \"respiración\" del planeta, montada sobre una tendencia que sube."]},"solucion":{}},{"slug":"aire-suelo-3.s2.p8","orden":8,"grupo":"aire-suelo-3.s2.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la curva del CO₂ baja un poco durante el verano del hemisferio norte?","opciones":[{"id":"o1","texto":"Porque la vegetación del norte crece y absorbe CO₂"},{"id":"o2","texto":"Porque en verano se usan menos autos en el mundo"},{"id":"o3","texto":"Porque el sol destruye el CO₂ con el calor"},{"id":"o4","texto":"Porque en verano el mar libera oxígeno"}]},"solucion":{"clave":["o1"],"explicacion":"Hay más superficie de tierra y vegetación en el hemisferio norte, así que su estación marca el ritmo del serrucho.","por_opcion":{"o3":"El calor no destruye el CO₂; lo que cambia es la fotosíntesis."}}},{"slug":"aire-suelo-3.s2.p9","orden":9,"grupo":"aire-suelo-3.s2.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 1958 había 315 ppm de CO₂ y en 2024, 425 ppm. ¿Cuántas ppm por año subió en promedio? Redondeá a un decimal.","unidad":"ppm/año","decimales":1},"solucion":{"valor":1.7,"tolerancia":0.1,"explicacion":"(425 − 315) ÷ (2024 − 1958) ≈ 1,7 ppm por año. En los últimos años, el aumento anual ronda las 2 a 3 ppm: el ritmo se aceleró."}},{"slug":"aire-suelo-3.s2.p9.v2","orden":9,"grupo":"aire-suelo-3.s2.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 1970 había 325 ppm de CO₂ y en 2020, 413 ppm. ¿Cuántas ppm por año subió en promedio? Redondeá a un decimal.","unidad":"ppm/año","decimales":1},"solucion":{"valor":1.8,"tolerancia":0.1,"explicacion":"(413 − 325) ÷ (2020 − 1970) ≈ 1,8 ppm por año. En los últimos años, el aumento anual ronda las 2 a 3 ppm: el ritmo se aceleró."}},{"slug":"aire-suelo-3.s2.p9.v3","orden":9,"grupo":"aire-suelo-3.s2.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 1990 había 354 ppm de CO₂ y en 2024, 425 ppm. ¿Cuántas ppm por año subió en promedio? Redondeá a un decimal.","unidad":"ppm/año","decimales":1},"solucion":{"valor":2.1,"tolerancia":0.1,"explicacion":"(425 − 354) ÷ (2024 − 1990) ≈ 2,1 ppm por año. En los últimos años, el aumento anual ronda las 2 a 3 ppm: el ritmo se aceleró."}},{"slug":"aire-suelo-3.s2.p10","orden":10,"grupo":"aire-suelo-3.s2.p10","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas partes por millón (ppm) de CO₂ hay hoy en la atmósfera.","min":100,"max":1000,"paso":5,"unidad":"ppm","escala":"lineal"},"solucion":{"valor":425,"banda":"lineal","explicacion":"Más de 420 ppm, según Mauna Loa. En 1958 eran 315 ppm y antes de la Revolución Industrial, unas 280."}},{"slug":"aire-suelo-3.s2.p11","orden":11,"grupo":"aire-suelo-3.s2.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El CO₂ atmosférico actual está dentro del rango de los últimos 800.000 años.","razones":[{"id":"r1","texto":"Porque hoy supera las 420 ppm y el máximo fue unas 300"},{"id":"r2","texto":"Porque hoy hay menos CO₂ que en las glaciaciones"},{"id":"r3","texto":"Porque en el pasado nunca hubo CO₂"}]},"solucion":{"valor":false,"explicacion":"En 800.000 años de registros de hielo osciló entre unas 180 y 300 ppm. Hoy supera las 420 ppm: muy por encima del rango.","clave":["r1"]}},{"slug":"aire-suelo-3.s2.p12","orden":12,"grupo":"aire-suelo-3.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Keeling empezó a medir el CO₂ en Mauna Loa en 1958."},{"id":"s2","texto":"La curva del CO₂ sube de forma perfectamente lisa."},{"id":"s3","texto":"Los testigos de hielo guardan aire de cientos de miles de años."},{"id":"s4","texto":"El CO₂ preindustrial era de unas 420 ppm."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Datos precisos para una discusión precisa.","por_opcion":{"s2":"Tiene un serrucho estacional por la vegetación del hemisferio norte.","s4":"Era de unas 280 ppm; 420 es el valor actual."}}},{"slug":"aire-suelo-3.s2.p13","orden":13,"grupo":"aire-suelo-3.s2.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada valor de CO₂ con su momento.","izquierda":[{"id":"a1","texto":"≈ 180 ppm"},{"id":"a2","texto":"≈ 280 ppm"},{"id":"a3","texto":"≈ 315 ppm"},{"id":"a4","texto":"Más de 420 ppm"}],"derecha":[{"id":"b1","texto":"Glaciaciones"},{"id":"b2","texto":"Antes de la Revolución Industrial"},{"id":"b3","texto":"Primera medición en Mauna Loa"},{"id":"b4","texto":"Hoy"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Estos cuatro números resumen la historia del CO₂."}},{"slug":"aire-suelo-3.s2.p14","orden":14,"grupo":"aire-suelo-3.s2.p14","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos momentos de la historia del CO₂, del más antiguo al más reciente.","items":[{"id":"i1","texto":"Último máximo glacial, con unas 180 ppm"},{"id":"i2","texto":"Comienzo de la Revolución Industrial, con unas 280 ppm"},{"id":"i3","texto":"Keeling mide unas 315 ppm en Mauna Loa"},{"id":"i4","texto":"El promedio anual supera por primera vez las 400 ppm"}],"extremos":["Más antiguo","Más reciente"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"En unos 20.000 años el CO₂ pasó de 180 a 280 ppm; en menos de 200 años, de 280 a más de 420."}},{"slug":"aire-suelo-3.s2.p15","orden":15,"grupo":"aire-suelo-3.s2.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Antes de la Revolución Industrial había unas {{0}} ppm de CO₂; hoy hay más de {{1}}; y la serie de mediciones de Mauna Loa se llama curva de {{2}}.","banco":[{"id":"w1","texto":"280"},{"id":"w2","texto":"420"},{"id":"w3","texto":"Keeling"},{"id":"w4","texto":"180"},{"id":"w5","texto":"1000"},{"id":"w6","texto":"Darwin"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los números clave de la historia del CO₂ en la atmósfera."}}]},{"slug":"aire-suelo-3.s3","orden":3,"tipo":"leccion","titulo_es":"De dónde sale el carbono extra","bajada_es":"Combustibles fósiles, desmontes y la huella química que delata su origen. Y a dónde va lo que emitimos.","minutos":11,"pasos":[{"slug":"aire-suelo-3.s3.p1","orden":1,"grupo":"aire-suelo-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Carbono de hace millones de años","cuerpo":["El carbón, el petróleo y el gas se formaron a partir de restos de seres vivos enterrados durante millones de años. Guardan carbono que salió del ciclo rápido hace muchísimo tiempo. Al quemarlos, en pocas décadas devolvemos a la atmósfera carbono que tardó millones de años en acumularse. A eso se suma el carbono que liberan los desmontes y los incendios de bosques.","Según el Global Carbon Project, la quema de combustibles fósiles emite hoy alrededor de 37.000 millones de toneladas de CO₂ por año, y los cambios en el uso del suelo, unos 4.000 millones más."]},"solucion":{}},{"slug":"aire-suelo-3.s3.p2","orden":2,"grupo":"aire-suelo-3.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta actividad agrega carbono a la atmósfera o lo retira?","grupos":[{"id":"g1","nombre":"Agrega carbono"},{"id":"g2","nombre":"Retira carbono"}],"items":[{"id":"i1","texto":"Quemar gas en una central eléctrica"},{"id":"i2","texto":"Un bosque que crece"},{"id":"i3","texto":"Desmontar un bosque y quemar los restos"},{"id":"i4","texto":"Un suelo que gana materia orgánica"},{"id":"i5","texto":"Cargar nafta y manejar"},{"id":"i6","texto":"El océano absorbiendo CO₂"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El balance entre lo que se emite y lo que se absorbe define cuánto CO₂ queda en el aire."}},{"slug":"aire-suelo-3.s3.p3","orden":3,"grupo":"aire-suelo-3.s3.p3","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos miles de millones de toneladas de CO₂ emite por año la quema de combustibles fósiles en el mundo.","min":1,"max":500,"paso":1,"unidad":"miles de millones de t","escala":"log"},"solucion":{"valor":37,"banda":"log","explicacion":"Unos 37.000 millones de toneladas por año, según el Global Carbon Project. Con los cambios de uso del suelo, más de 40.000 millones."}},{"slug":"aire-suelo-3.s3.p4","orden":4,"grupo":"aire-suelo-3.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La huella química","cuerpo":["¿Cómo sabemos que el CO₂ extra viene de los combustibles fósiles y no, por ejemplo, de los volcanes? El carbono tiene distintas variantes, llamadas isótopos. El carbono de los fósiles, de origen vegetal y muy antiguo, tiene menos carbono-13 y nada de carbono-14, que desaparece con los milenios. Y en la atmósfera, justamente, la proporción de esos isótopos está bajando: es la huella del carbono fósil.","Además, los volcanes emiten, en promedio, menos del 1 % de lo que emiten hoy las actividades humanas."]},"solucion":{}},{"slug":"aire-suelo-3.s3.p5","orden":5,"grupo":"aire-suelo-3.s3.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el razonamiento que prueba el origen fósil del CO₂ extra.","items":[{"id":"i1","texto":"El carbono de los fósiles no tiene carbono-14"},{"id":"i2","texto":"Si el CO₂ extra fuera fósil, bajaría la proporción de carbono-14 en el aire"},{"id":"i3","texto":"Las mediciones muestran que esa proporción baja"},{"id":"i4","texto":"La evidencia apunta a los combustibles fósiles"},{"id":"i5","texto":"Los volcanes emiten más CO₂ que toda la actividad humana"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Es un razonamiento científico: una predicción que los datos confirman."}},{"slug":"aire-suelo-3.s3.p6","orden":6,"grupo":"aire-suelo-3.s3.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Alguien dice que el CO₂ extra viene de los volcanes. ¿Qué dato lo contradice mejor?","opciones":[{"id":"o1","texto":"Los volcanes emiten menos del 1 % que las personas"},{"id":"o2","texto":"Los volcanes solo están en la cordillera de los Andes"},{"id":"o3","texto":"Los volcanes emiten solo vapor de agua"},{"id":"o4","texto":"Los volcanes se apagaron en el siglo pasado"}]},"solucion":{"clave":["o1"],"explicacion":"Los volcanes emiten CO₂, pero muy poco comparado con los combustibles fósiles. Y la huella química confirma el origen fósil.","por_opcion":{"o3":"Emiten CO₂, pero muy poco comparado con la actividad humana."}}},{"slug":"aire-suelo-3.s3.p7","orden":7,"grupo":"aire-suelo-3.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"A dónde va lo que emitimos","cuerpo":["No todo el CO₂ que emitimos queda en el aire. En las últimas décadas, alrededor de un cuarto lo absorbieron los océanos, cerca de un tercio la vegetación y los suelos, y el resto —algo menos de la mitad— se acumuló en la atmósfera. Esos sumideros nos ayudan, pero tienen un costo: el océano se acidifica al absorber CO₂, y los bosques absorben menos cuando hay sequías, calor extremo o desmonte."],"datos":{"tipo":"barras","titulo":"Destino del CO₂ emitido por las personas (aproximado)","unidad":"%","filas":[{"etiqueta":"Queda en la atmósfera","valor":46},{"etiqueta":"Absorben la vegetación y los suelos","valor":29},{"etiqueta":"Absorben los océanos","valor":25}],"nota":"Global Carbon Budget, promedios de la última década; valores redondeados."}},"solucion":{}},{"slug":"aire-suelo-3.s3.p8","orden":8,"grupo":"aire-suelo-3.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un año se emiten 40 mil millones de toneladas de CO₂ y queda en la atmósfera el 46 %, ¿cuántos miles de millones de toneladas se acumulan en el aire? Redondeá a un decimal.","unidad":"mil millones de t","decimales":1},"solucion":{"valor":18.4,"tolerancia":0.1,"explicacion":"40 × 0,46 ≈ 18,4. El resto lo absorben océanos, vegetación y suelos."}},{"slug":"aire-suelo-3.s3.p8.v2","orden":8,"grupo":"aire-suelo-3.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un año se emiten 42 mil millones de toneladas de CO₂ y queda en la atmósfera el 46 %, ¿cuántos miles de millones de toneladas se acumulan en el aire? Redondeá a un decimal.","unidad":"mil millones de t","decimales":1},"solucion":{"valor":19.3,"tolerancia":0.1,"explicacion":"42 × 0,46 ≈ 19,3. El resto lo absorben océanos, vegetación y suelos."}},{"slug":"aire-suelo-3.s3.p8.v3","orden":8,"grupo":"aire-suelo-3.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un año se emiten 38 mil millones de toneladas de CO₂ y queda en la atmósfera el 46 %, ¿cuántos miles de millones de toneladas se acumulan en el aire? Redondeá a un decimal.","unidad":"mil millones de t","decimales":1},"solucion":{"valor":17.5,"tolerancia":0.1,"explicacion":"38 × 0,46 ≈ 17,5. El resto lo absorben océanos, vegetación y suelos."}},{"slug":"aire-suelo-3.s3.p9","orden":9,"grupo":"aire-suelo-3.s3.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sumidero con su costo o límite.","izquierda":[{"id":"a1","texto":"Océano"},{"id":"a2","texto":"Bosques"},{"id":"a3","texto":"Suelos"},{"id":"a4","texto":"Atmósfera"}],"derecha":[{"id":"b1","texto":"Se acidifica al absorber CO₂"},{"id":"b2","texto":"Absorben menos con sequías, calor o desmonte"},{"id":"b3","texto":"Pierden carbono si se degradan"},{"id":"b4","texto":"Acumula el CO₂ que nadie absorbe"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los sumideros ayudan, pero no son ilimitados ni gratuitos."}},{"slug":"aire-suelo-3.s3.p10","orden":10,"grupo":"aire-suelo-3.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como océanos y bosques absorben CO₂, no importa cuánto emitamos.","razones":[{"id":"r1","texto":"Porque absorben solo una parte y pueden debilitarse"},{"id":"r2","texto":"Porque los sumideros absorben todo el CO₂"},{"id":"r3","texto":"Porque los océanos emiten más de lo que absorben"}]},"solucion":{"valor":false,"explicacion":"Absorben algo más de la mitad, pero el resto se acumula en el aire. Y los sumideros pueden debilitarse con el calentamiento.","clave":["r1"]}},{"slug":"aire-suelo-3.s3.p11","orden":11,"grupo":"aire-suelo-3.s3.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué evidencias muestran que el CO₂ extra es de origen humano? Marcá todas.","opciones":[{"id":"o1","texto":"Baja la proporción de carbono-14 en el aire"},{"id":"o2","texto":"El aumento coincide con la quema de combustibles"},{"id":"o3","texto":"Las emisiones humanas superan con creces a las volcánicas"},{"id":"o4","texto":"El CO₂ sube solo en las ciudades"},{"id":"o5","texto":"El CO₂ bajó desde 1958"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Varias líneas de evidencia independientes apuntan a lo mismo."}},{"slug":"aire-suelo-3.s3.p12","orden":12,"grupo":"aire-suelo-3.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El carbón y el petróleo se formaron durante millones de años."},{"id":"s2","texto":"Todo el CO₂ que emitimos queda en la atmósfera."},{"id":"s3","texto":"El océano se acidifica al absorber CO₂."},{"id":"s4","texto":"Los volcanes emiten más CO₂ que las personas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber a dónde va el carbono evita dos errores: pensar que no importa y pensar que todo queda en el aire.","por_opcion":{"s2":"Algo más de la mitad la absorben océanos, vegetación y suelos.","s4":"Emiten menos del 1 % de lo que emiten hoy las actividades humanas."}}},{"slug":"aire-suelo-3.s3.p13","orden":13,"grupo":"aire-suelo-3.s3.p13","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si con el calor y las sequías los bosques absorben menos CO₂, ¿qué pasa?","opciones":[{"id":"o1","texto":"Queda más CO₂ en el aire por cada tonelada emitida"},{"id":"o2","texto":"Los océanos absorben automáticamente todo lo que falta"},{"id":"o3","texto":"Baja el CO₂, porque los árboles dejan de respirar"},{"id":"o4","texto":"Nada, porque los bosques no participan del ciclo"}]},"solucion":{"clave":["o1"],"explicacion":"Es una retroalimentación: el calentamiento debilita los sumideros, y eso acelera el calentamiento.","por_opcion":{"o3":"Si absorben menos, el CO₂ sube; no baja."}}},{"slug":"aire-suelo-3.s3.p14","orden":14,"grupo":"aire-suelo-3.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El CO₂ fósil no tiene carbono-{{0}}; los océanos absorben alrededor de un {{1}} de lo que emitimos; y al hacerlo se {{2}}.","banco":[{"id":"w1","texto":"14"},{"id":"w2","texto":"cuarto"},{"id":"w3","texto":"acidifican"},{"id":"w4","texto":"12"},{"id":"w5","texto":"décimo"},{"id":"w6","texto":"enfrían"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves sobre el origen y el destino del carbono."}}]},{"slug":"aire-suelo-3.s4","orden":4,"tipo":"leccion","titulo_es":"Los otros gases","bajada_es":"Metano, óxido nitroso y gases fluorados: cuánto calientan, cuánto duran y de dónde vienen en Argentina.","minutos":11,"pasos":[{"slug":"aire-suelo-3.s4.p1","orden":1,"grupo":"aire-suelo-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Metano y óxido nitroso","cuerpo":["El metano (CH₄) se emite en la ganadería (por la digestión de las vacas), en arrozales, en basurales y rellenos sanitarios, y en fugas de la extracción y el transporte de gas. Calienta mucho más que el CO₂ por tonelada, pero dura menos en la atmósfera: unos 12 años. Según el IPCC, el metano explica alrededor de medio grado del calentamiento observado.","El óxido nitroso (N₂O) viene sobre todo de los fertilizantes nitrogenados y del estiércol. Dura más de un siglo y calienta casi 300 veces más que el CO₂ por tonelada, en 100 años."]},"solucion":{}},{"slug":"aire-suelo-3.s4.p2","orden":2,"grupo":"aire-suelo-3.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada gas con su fuente principal.","izquierda":[{"id":"a1","texto":"Metano"},{"id":"a2","texto":"Óxido nitroso"},{"id":"a3","texto":"Dióxido de carbono"},{"id":"a4","texto":"Gases fluorados"}],"derecha":[{"id":"b1","texto":"Ganadería, basurales y fugas de gas"},{"id":"b2","texto":"Fertilizantes nitrogenados"},{"id":"b3","texto":"Quema de combustibles fósiles"},{"id":"b4","texto":"Refrigeración y aire acondicionado"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada gas tiene sus fuentes, y por eso sus soluciones son distintas."}},{"slug":"aire-suelo-3.s4.p3","orden":3,"grupo":"aire-suelo-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Repaso: el CO₂ equivalente","cuerpo":["Como viste en el tronco, para sumar gases distintos se usa el CO₂ equivalente (CO₂e), que multiplica cada gas por su potencial de calentamiento en 100 años. En números redondos del IPCC: CO₂ = 1, metano ≈ 28 y óxido nitroso ≈ 273."],"datos":{"tipo":"tabla","titulo":"Potencial de calentamiento y duración (valores aproximados, IPCC)","columnas":["Gas","Poder de calentamiento a 100 años","Duración en la atmósfera"],"filas":[["CO₂","1","Una parte, siglos a milenios"],["Metano","≈ 28","≈ 12 años"],["Óxido nitroso","≈ 273","≈ 110 años"]]}},"solucion":{}},{"slug":"aire-suelo-3.s4.p4","orden":4,"grupo":"aire-suelo-3.s4.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de CO₂e equivalen a 2 toneladas de metano, si el metano vale 28 veces el CO₂?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"2 × 28 = 56 t CO₂e. Por eso reducir fugas de metano rinde mucho por tonelada."}},{"slug":"aire-suelo-3.s4.p4.v2","orden":4,"grupo":"aire-suelo-3.s4.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de CO₂e equivalen a 5 toneladas de metano, si el metano vale 28 veces el CO₂?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"5 × 28 = 140 t CO₂e. Por eso reducir fugas de metano rinde mucho por tonelada."}},{"slug":"aire-suelo-3.s4.p4.v3","orden":4,"grupo":"aire-suelo-3.s4.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de CO₂e equivalen a 10 toneladas de metano, si el metano vale 28 veces el CO₂?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":280,"tolerancia":5.6000000000000005,"explicacion":"10 × 28 = 280 t CO₂e. Por eso reducir fugas de metano rinde mucho por tonelada."}},{"slug":"aire-suelo-3.s4.p5","orden":5,"grupo":"aire-suelo-3.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de CO₂e equivalen a 3 toneladas de óxido nitroso, si vale 273 veces el CO₂?","unidad":"t CO₂e","decimales":0,"contexto":"3 t de N₂O; potencial de 273."},"solucion":{"valor":819,"tolerancia":16.38,"explicacion":"3 × 273 = 819 t CO₂e. Pocas toneladas de óxido nitroso pesan como cientos de toneladas de CO₂."}},{"slug":"aire-suelo-3.s4.p6","orden":6,"grupo":"aire-suelo-3.s4.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"El metano calienta mucho por tonelada pero dura poco. ¿Qué implica eso?","opciones":[{"id":"o1","texto":"Reducirlo frena el calentamiento en pocas décadas"},{"id":"o2","texto":"Que no hace falta reducirlo, porque se va solo"},{"id":"o3","texto":"Que dura más que el CO₂"},{"id":"o4","texto":"Que no tiene ningún efecto sobre el clima"}]},"solucion":{"clave":["o1"],"explicacion":"Recortar metano da resultados rápidos; recortar CO₂ evita un calentamiento que duraría siglos. Hacen falta las dos cosas.","por_opcion":{"o3":"Es al revés: el metano dura unos 12 años; parte del CO₂, siglos."}}},{"slug":"aire-suelo-3.s4.p7","orden":7,"grupo":"aire-suelo-3.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Argentina en el mapa","cuerpo":["Según el Inventario Nacional de Gases de Efecto Invernadero, alrededor de la mitad de las emisiones de Argentina viene de la energía (transporte, electricidad, industria, calefacción), y cerca del 39 % de la agricultura, la ganadería, la silvicultura y otros usos de la tierra, incluidos los desmontes. El resto, de procesos industriales (≈ 6 %) y residuos (≈ 5 %).","Argentina emite menos del 1 % de los gases del mundo, pero por persona está cerca del promedio mundial o algo por encima, según el año y cómo se cuente."],"datos":{"tipo":"barras","titulo":"Emisiones de Argentina por sector (aproximado)","unidad":"%","filas":[{"etiqueta":"Energía","valor":50},{"etiqueta":"Agro, ganadería y usos de la tierra","valor":39},{"etiqueta":"Procesos industriales","valor":6},{"etiqueta":"Residuos","valor":5}],"nota":"Inventario Nacional de GEI de Argentina; valores redondeados."}},"solucion":{}},{"slug":"aire-suelo-3.s4.p8","orden":8,"grupo":"aire-suelo-3.s4.p8","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los sectores de Argentina por sus emisiones, de mayor a menor.","items":[{"id":"i1","texto":"Energía"},{"id":"i2","texto":"Agro, ganadería y usos de la tierra"},{"id":"i3","texto":"Procesos industriales"},{"id":"i4","texto":"Residuos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"A diferencia de muchos países industrializados, en Argentina el agro y los desmontes pesan casi tanto como la energía.","valores":{"i1":"≈ 50 %","i2":"≈ 39 %","i3":"≈ 6 %","i4":"≈ 5 %"}}},{"slug":"aire-suelo-3.s4.p9","orden":9,"grupo":"aire-suelo-3.s4.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué sector del inventario se cuenta cada emisión?","grupos":[{"id":"g1","nombre":"Energía"},{"id":"g2","nombre":"Agro y usos de la tierra"},{"id":"g3","nombre":"Residuos"}],"items":[{"id":"i1","texto":"Nafta de los autos"},{"id":"i2","texto":"Metano de la ganadería"},{"id":"i3","texto":"Metano de los rellenos sanitarios"},{"id":"i4","texto":"Gas de las centrales eléctricas"},{"id":"i5","texto":"Desmonte en el Chaco"},{"id":"i6","texto":"Aguas residuales sin tratar"},{"id":"i7","texto":"Calefacción a gas"},{"id":"i8","texto":"Fertilizantes nitrogenados"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2"},"explicacion":"Conocer cómo se reparten las emisiones ayuda a ver dónde están las mayores oportunidades."}},{"slug":"aire-suelo-3.s4.p10","orden":10,"grupo":"aire-suelo-3.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina emite 366 millones de toneladas de CO₂e por año y el 39 % viene del agro, la ganadería y los usos de la tierra, ¿cuántos millones de toneladas son? Redondeá al entero.","unidad":"millones de t CO₂e","decimales":0},"solucion":{"valor":143,"tolerancia":1,"explicacion":"366 × 0,39 ≈ 143 millones de t CO₂e. Casi cuatro de cada diez toneladas vienen del campo y los desmontes."}},{"slug":"aire-suelo-3.s4.p10.v2","orden":10,"grupo":"aire-suelo-3.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina emite 370 millones de toneladas de CO₂e por año y el 39 % viene del agro, la ganadería y los usos de la tierra, ¿cuántos millones de toneladas son? Redondeá al entero.","unidad":"millones de t CO₂e","decimales":0},"solucion":{"valor":144,"tolerancia":1,"explicacion":"370 × 0,39 ≈ 144 millones de t CO₂e. Casi cuatro de cada diez toneladas vienen del campo y los desmontes."}},{"slug":"aire-suelo-3.s4.p10.v3","orden":10,"grupo":"aire-suelo-3.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina emite 360 millones de toneladas de CO₂e por año y el 39 % viene del agro, la ganadería y los usos de la tierra, ¿cuántos millones de toneladas son? Redondeá al entero.","unidad":"millones de t CO₂e","decimales":0},"solucion":{"valor":140,"tolerancia":1,"explicacion":"360 × 0,39 ≈ 140 millones de t CO₂e. Casi cuatro de cada diez toneladas vienen del campo y los desmontes."}},{"slug":"aire-suelo-3.s4.p11","orden":11,"grupo":"aire-suelo-3.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como Argentina emite menos del 1 % del total mundial, sus emisiones no importan.","razones":[{"id":"r1","texto":"Porque sumadas, las emisiones de países chicos pesan mucho"},{"id":"r2","texto":"Porque Argentina emite la mitad del mundo"},{"id":"r3","texto":"Porque las emisiones de otros países no cuentan"}]},"solucion":{"valor":false,"explicacion":"Casi todos los países emiten un porcentaje chico: si todos pensaran así, nadie haría nada. Además, por persona, Argentina está cerca del promedio mundial.","clave":["r1"]}},{"slug":"aire-suelo-3.s4.p12","orden":12,"grupo":"aire-suelo-3.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El metano viene, entre otras fuentes, de la ganadería."},{"id":"s2","texto":"El metano dura siglos en la atmósfera."},{"id":"s3","texto":"El óxido nitroso viene sobre todo de los fertilizantes."},{"id":"s4","texto":"En Argentina, los residuos son el sector que más emite."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los detalles de cada gas importan para elegir bien las soluciones.","por_opcion":{"s2":"Dura unos 12 años; lo que dura siglos es una parte del CO₂.","s4":"Son alrededor del 5 %; los primeros son la energía y el agro."}}},{"slug":"aire-suelo-3.s4.p13","orden":13,"grupo":"aire-suelo-3.s4.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Algunos gases fluorados de heladeras y aires acondicionados calientan miles de veces más que el CO₂ por tonelada.","razones":[{"id":"r1","texto":"Porque algunos HFC tienen potenciales de miles"},{"id":"r2","texto":"Porque los gases fluorados enfrían el planeta"},{"id":"r3","texto":"Porque solo el CO₂ calienta"}]},"solucion":{"valor":true,"explicacion":"Algunos HFC tienen potenciales de miles. Por eso la Enmienda de Kigali (2016) acordó reducirlos de forma gradual en todo el mundo.","clave":["r1"]}},{"slug":"aire-suelo-3.s4.p14","orden":14,"grupo":"aire-suelo-3.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El metano dura unos {{0}} años en la atmósfera; el óxido nitroso viene sobre todo de los {{1}}; y en Argentina, el sector que más emite es la {{2}}.","banco":[{"id":"w1","texto":"12"},{"id":"w2","texto":"fertilizantes"},{"id":"w3","texto":"energía"},{"id":"w4","texto":"500"},{"id":"w5","texto":"plásticos"},{"id":"w6","texto":"minería"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos para ubicar los otros gases y el caso argentino."}}]},{"slug":"aire-suelo-3.s5","orden":5,"tipo":"leccion","titulo_es":"Cuánto se calentó y cómo lo sabemos","bajada_es":"Tiempo y clima, el calentamiento medido y las huellas que señalan a las actividades humanas.","minutos":12,"pasos":[{"slug":"aire-suelo-3.s5.p1","orden":1,"grupo":"aire-suelo-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tiempo no es clima","cuerpo":["El tiempo es lo que pasa en la atmósfera en un lugar y momento: hoy llueve, mañana hace calor. El clima es el promedio y la variabilidad del tiempo durante muchos años, por convención al menos 30. Un día frío no desmiente el calentamiento global, igual que un día caluroso no lo prueba: lo que importa es la tendencia de largo plazo."]},"solucion":{}},{"slug":"aire-suelo-3.s5.p2","orden":2,"grupo":"aire-suelo-3.s5.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Habla del tiempo o del clima?","grupos":[{"id":"g1","nombre":"Tiempo"},{"id":"g2","nombre":"Clima"}],"items":[{"id":"i1","texto":"Mañana va a llover en Córdoba"},{"id":"i2","texto":"En Mendoza llueve poco en promedio"},{"id":"i3","texto":"Hoy hizo 38 °C en Rosario"},{"id":"i4","texto":"Los inviernos de Ushuaia son fríos"},{"id":"i5","texto":"Esta semana hubo heladas"},{"id":"i6","texto":"La temperatura media subió en los últimos 50 años"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El clima se mide en décadas; el tiempo, en horas y días."}},{"slug":"aire-suelo-3.s5.p3","orden":3,"grupo":"aire-suelo-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El calentamiento medido","cuerpo":["Miles de estaciones meteorológicas, barcos, boyas y satélites miden la temperatura del planeta. Los registros de la NASA, la NOAA, el servicio europeo Copernicus y otros coinciden: la temperatura media global ya subió alrededor de 1,2 a 1,3 °C respecto de la época preindustrial (1850–1900). El año 2024 fue el más cálido registrado, con alrededor de 1,55 °C por encima de ese nivel, según la Organización Meteorológica Mundial.","Los continentes se calientan más que el océano, y el Ártico, varias veces más rápido que el promedio global."],"destacado":{"valor":"≈ 1,55 °C","texto":"por encima de la era preindustrial fue la temperatura media global de 2024, el año más cálido registrado."}},"solucion":{}},{"slug":"aire-suelo-3.s5.p4","orden":4,"grupo":"aire-suelo-3.s5.p4","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos grados se calentó en promedio el planeta respecto de la época preindustrial, considerando el promedio de la última década.","min":0,"max":5,"paso":0.05,"unidad":"°C","escala":"lineal"},"solucion":{"valor":1.25,"banda":"lineal","explicacion":"Alrededor de 1,2 a 1,3 °C en promedio de la última década. 2024, un año puntual, llegó a unos 1,55 °C."}},{"slug":"aire-suelo-3.s5.p5","orden":5,"grupo":"aire-suelo-3.s5.p5","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un invierno muy frío en Buenos Aires demuestra que el calentamiento global no existe.","razones":[{"id":"r1","texto":"Porque un evento local no cambia la tendencia global"},{"id":"r2","texto":"Porque el calentamiento solo ocurre en verano"},{"id":"r3","texto":"Porque Buenos Aires no forma parte del planeta"}]},"solucion":{"valor":false,"explicacion":"Un invierno es tiempo, no clima. El calentamiento se mide con promedios globales de décadas, que muestran una tendencia clara al alza.","clave":["r1"]}},{"slug":"aire-suelo-3.s5.p6","orden":6,"grupo":"aire-suelo-3.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"¿Y si fuera el sol?","cuerpo":["Los científicos analizaron las causas naturales posibles. La energía que llega del sol se mide con satélites desde fines de los años 70 y no aumentó: incluso bajó un poco, mientras la temperatura subía. Además hay huellas que solo encajan con los gases de efecto invernadero: la capa baja de la atmósfera se calienta mientras la estratosfera, más arriba, se enfría; y las noches se calientan más rápido que los días. Si la causa fuera el sol, toda la atmósfera se calentaría, incluida la estratosfera."]},"solucion":{}},{"slug":"aire-suelo-3.s5.p7","orden":7,"grupo":"aire-suelo-3.s5.p7","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el razonamiento de la \"huella\" en la estratosfera.","items":[{"id":"i1","texto":"Si el sol fuera la causa, toda la atmósfera se calentaría"},{"id":"i2","texto":"Con más gases de efecto invernadero, la capa baja se calienta y la estratosfera se enfría"},{"id":"i3","texto":"Las mediciones muestran que la estratosfera se enfría"},{"id":"i4","texto":"La evidencia señala a los gases, no al sol"},{"id":"i5","texto":"La estratosfera se calienta más que la superficie"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Comparar predicciones distintas con los datos es la forma en que la ciencia distingue causas."}},{"slug":"aire-suelo-3.s5.p8","orden":8,"grupo":"aire-suelo-3.s5.p8","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué evidencias señalan a los gases de efecto invernadero y no al sol? Marcá todas.","opciones":[{"id":"o1","texto":"La energía solar no aumentó desde los años 70"},{"id":"o2","texto":"La estratosfera se enfría mientras la superficie se calienta"},{"id":"o3","texto":"Las noches se calientan más rápido que los días"},{"id":"o4","texto":"El sol se está acercando a la Tierra"},{"id":"o5","texto":"Los inviernos desaparecieron en todo el mundo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Varias huellas independientes apuntan a la misma causa."}},{"slug":"aire-suelo-3.s5.p9","orden":9,"grupo":"aire-suelo-3.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El consenso","cuerpo":["Distintos estudios que revisaron miles de artículos científicos encontraron que alrededor del 97 % o más de los especialistas en clima que publican sobre el tema coinciden en que el calentamiento reciente es causado por las actividades humanas. El IPCC, en su último informe, lo afirmó sin ambigüedad: es \"inequívoco\" que la influencia humana calentó la atmósfera, el océano y la tierra."]},"solucion":{}},{"slug":"aire-suelo-3.s5.p10","orden":10,"grupo":"aire-suelo-3.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de 1.000 artículos científicos que opinan sobre la causa del calentamiento, el 97 % coincide en que es humana, ¿cuántos artículos coinciden?","unidad":"artículos","decimales":0},"solucion":{"valor":970,"tolerancia":19.400000000000002,"explicacion":"1.000 × 0,97 = 970. Un consenso así en ciencia es muy fuerte, y está respaldado por múltiples líneas de evidencia."}},{"slug":"aire-suelo-3.s5.p10.v2","orden":10,"grupo":"aire-suelo-3.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de 2.500 artículos científicos que opinan sobre la causa del calentamiento, el 97 % coincide en que es humana, ¿cuántos artículos coinciden?","unidad":"artículos","decimales":0},"solucion":{"valor":2425,"tolerancia":48.5,"explicacion":"2.500 × 0,97 = 2.425. Un consenso así en ciencia es muy fuerte, y está respaldado por múltiples líneas de evidencia."}},{"slug":"aire-suelo-3.s5.p10.v3","orden":10,"grupo":"aire-suelo-3.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de 600 artículos científicos que opinan sobre la causa del calentamiento, el 97 % coincide en que es humana, ¿cuántos artículos coinciden?","unidad":"artículos","decimales":0},"solucion":{"valor":582,"tolerancia":11.64,"explicacion":"600 × 0,97 = 582. Un consenso así en ciencia es muy fuerte, y está respaldado por múltiples líneas de evidencia."}},{"slug":"aire-suelo-3.s5.p11","orden":11,"grupo":"aire-suelo-3.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los científicos confían en que el calentamiento es causado por las personas?","opciones":[{"id":"o1","texto":"Varias evidencias independientes apuntan a lo mismo"},{"id":"o2","texto":"Porque lo dijo una sola persona muy famosa"},{"id":"o3","texto":"Porque los modelos se inventan los datos"},{"id":"o4","texto":"Porque todos los veranos son más calurosos que el anterior"}]},"solucion":{"clave":["o1"],"explicacion":"La confianza viene de que muchas líneas de evidencia —isótopos, huellas en la atmósfera, balance de energía, física básica— coinciden.","por_opcion":{"o3":"Los modelos se contrastan con mediciones reales; no alcanzan solos."}}},{"slug":"aire-suelo-3.s5.p12","orden":12,"grupo":"aire-suelo-3.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El planeta se calentó alrededor de 1,2 °C desde la época preindustrial."},{"id":"s2","texto":"El calentamiento lo causa el sol, que cada año emite más energía."},{"id":"s3","texto":"La estratosfera se enfría mientras la superficie se calienta."},{"id":"s4","texto":"Los científicos están divididos a la mitad sobre la causa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber responder los mitos con datos es una forma de cuidar la conversación pública.","por_opcion":{"s2":"La energía solar no aumentó desde los años 70.","s4":"Alrededor del 97 % o más coincide en que es humana."}}},{"slug":"aire-suelo-3.s5.p13","orden":13,"grupo":"aire-suelo-3.s5.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada forma de medir con lo que mide.","izquierda":[{"id":"a1","texto":"Estaciones meteorológicas"},{"id":"a2","texto":"Boyas y barcos"},{"id":"a3","texto":"Satélites"},{"id":"a4","texto":"Testigos de hielo"}],"derecha":[{"id":"b1","texto":"Temperatura del aire sobre los continentes"},{"id":"b2","texto":"Temperatura de la superficie del mar"},{"id":"b3","texto":"Energía que llega del sol"},{"id":"b4","texto":"CO₂ y temperatura del pasado lejano"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Instrumentos distintos, medidos por equipos distintos, llegan a la misma conclusión."}},{"slug":"aire-suelo-3.s5.p14","orden":14,"grupo":"aire-suelo-3.s5.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tuvo una temperatura media de 16,2 °C en 1961–1990 y de 17,1 °C en 1991–2020. ¿Cuántos grados se calentó entre esos dos períodos?","unidad":"°C","decimales":1},"solucion":{"valor":0.9,"tolerancia":0.05,"explicacion":"17,1 − 16,2 = 0,9 °C. Se comparan promedios de 30 años para que un año raro no confunda la tendencia."}},{"slug":"aire-suelo-3.s5.p14.v2","orden":14,"grupo":"aire-suelo-3.s5.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tuvo una temperatura media de 11,4 °C en 1961–1990 y de 12,2 °C en 1991–2020. ¿Cuántos grados se calentó entre esos dos períodos?","unidad":"°C","decimales":1},"solucion":{"valor":0.8,"tolerancia":0.05,"explicacion":"12,2 − 11,4 = 0,8 °C. Se comparan promedios de 30 años para que un año raro no confunda la tendencia."}},{"slug":"aire-suelo-3.s5.p14.v3","orden":14,"grupo":"aire-suelo-3.s5.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tuvo una temperatura media de 22,6 °C en 1961–1990 y de 23,3 °C en 1991–2020. ¿Cuántos grados se calentó entre esos dos períodos?","unidad":"°C","decimales":1},"solucion":{"valor":0.7,"tolerancia":0.05,"explicacion":"23,3 − 22,6 = 0,7 °C. Se comparan promedios de 30 años para que un año raro no confunda la tendencia."}},{"slug":"aire-suelo-3.s5.p15","orden":15,"grupo":"aire-suelo-3.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El clima es el promedio del tiempo en al menos {{0}} años; mientras la superficie se calienta, la {{1}} se enfría; y 2024 fue el año más {{2}} registrado.","banco":[{"id":"w1","texto":"30"},{"id":"w2","texto":"estratosfera"},{"id":"w3","texto":"cálido"},{"id":"w4","texto":"2"},{"id":"w5","texto":"luna"},{"id":"w6","texto":"frío"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para leer y explicar el calentamiento global."}}]},{"slug":"aire-suelo-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el efecto invernadero","bajada_es":"Mecanismo, curva del CO₂, origen del carbono, otros gases y evidencia del calentamiento, mezclados.","minutos":8,"pasos":[{"slug":"aire-suelo-3.s6.p1","orden":1,"grupo":"aire-suelo-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El efecto invernadero». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"aire-suelo-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: responder con datos","bajada_es":"En un grupo familiar circulan cinco mensajes sobre el clima. Usá lo que aprendiste para responder cada uno con evidencia.","minutos":10,"pasos":[{"slug":"aire-suelo-3.s7.p1","orden":1,"grupo":"aire-suelo-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los mensajes","cuerpo":["Mensaje 1: \"El CO₂ es solo el 0,04 % del aire, no puede cambiar nada.\" Mensaje 2: \"El clima siempre cambió, esto es natural.\" Mensaje 3: \"Es el sol, que está más fuerte.\" Mensaje 4: \"Hoy hace un frío terrible, ¿dónde está el calentamiento?\" Mensaje 5: \"Los volcanes largan más CO₂ que todos los autos.\""]},"solucion":{}},{"slug":"aire-suelo-3.s7.p2","orden":2,"grupo":"aire-suelo-3.s7.p2","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada mensaje con el dato que mejor lo responde.","izquierda":[{"id":"a1","texto":"\"El CO₂ es solo el 0,04 %\""},{"id":"a2","texto":"\"El clima siempre cambió\""},{"id":"a3","texto":"\"Es el sol\""},{"id":"a4","texto":"\"Hoy hace frío\""},{"id":"a5","texto":"\"Los volcanes emiten más\""}],"derecha":[{"id":"b1","texto":"Absorbe infrarrojo aunque sea escaso"},{"id":"b2","texto":"El CO₂ actual supera 800.000 años de registros"},{"id":"b3","texto":"La energía solar no aumentó desde los años 70"},{"id":"b4","texto":"El tiempo de un día no es el clima"},{"id":"b5","texto":"Emiten menos del 1 % de lo humano"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada mito tiene una respuesta basada en datos. Conviene responder con respeto y con evidencia."}},{"slug":"aire-suelo-3.s7.p3","orden":3,"grupo":"aire-suelo-3.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el CO₂ subió de 280 a 425 ppm, ¿cuántas ppm aumentó?","unidad":"ppm","decimales":0,"contexto":"De 280 ppm preindustrial a 425 ppm actual."},"solucion":{"valor":145,"tolerancia":2.9,"explicacion":"425 − 280 = 145 ppm. Es un aumento de alrededor del 50 %, fuera del rango de 800.000 años de registros."}},{"slug":"aire-suelo-3.s7.p4","orden":4,"grupo":"aire-suelo-3.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Sobre el mensaje 2, \"el clima siempre cambió\", ¿qué respuesta es más sólida?","opciones":[{"id":"o1","texto":"Cambió, pero hoy el cambio es más rápido y tiene causa humana"},{"id":"o2","texto":"Es falso: el clima nunca cambió antes de nosotros"},{"id":"o3","texto":"Tiene razón, así que no hay nada que hacer"},{"id":"o4","texto":"Es verdad, pero solo en el hemisferio norte"}]},"solucion":{"clave":["o1"],"explicacion":"Reconocer lo cierto del mensaje y aportar el dato que falta suele convencer más que negarlo todo.","por_opcion":{"o3":"Que haya cambios naturales no excluye que este sea causado por las personas."}}},{"slug":"aire-suelo-3.s7.p5","orden":5,"grupo":"aire-suelo-3.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué evidencias podés citar para mostrar que el calentamiento es humano? Marcá todas.","opciones":[{"id":"o1","texto":"La huella de los isótopos del carbono"},{"id":"o2","texto":"El enfriamiento de la estratosfera"},{"id":"o3","texto":"El aumento del CO₂ coincide con la quema de combustibles"},{"id":"o4","texto":"Que este verano fue muy caluroso en tu ciudad"},{"id":"o5","texto":"Que lo dijo un famoso en la televisión"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Un verano caluroso es tiempo, no clima; y una opinión famosa no es evidencia."}},{"slug":"aire-suelo-3.s7.p6","orden":6,"grupo":"aire-suelo-3.s7.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para responder un mito conviene burlarse de quien lo compartió.","razones":[{"id":"r1","texto":"Porque la burla genera defensa y cierra la conversación"},{"id":"r2","texto":"Porque los datos no sirven para convencer"},{"id":"r3","texto":"Porque los mitos no se pueden responder"}]},"solucion":{"valor":false,"explicacion":"Burlarse genera defensa y cierra la conversación. Funciona mejor reconocer la duda, aportar un dato claro y una fuente confiable.","clave":["r1"]}},{"slug":"aire-suelo-3.s7.p7","orden":7,"grupo":"aire-suelo-3.s7.p7","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas respuestas de la más efectiva a la menos, para el grupo familiar.","items":[{"id":"i1","texto":"Reconocer la duda, dar un dato claro y una fuente"},{"id":"i2","texto":"Dar muchos datos juntos sin explicar"},{"id":"i3","texto":"Mandar solo un link sin comentario"},{"id":"i4","texto":"Responder con una burla"}],"extremos":["Más efectiva","Menos efectiva"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo viste en el tronco: hablar de ambiente sin pelear es una habilidad que se practica.","valores":{"i1":"más efectiva","i2":"poco clara","i3":"poco efectiva","i4":"contraproducente"}}},{"slug":"aire-suelo-3.s7.p8","orden":8,"grupo":"aire-suelo-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Tu respuesta al grupo. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Entiendo la duda, a mí también me pasó."},{"id":"s2","texto":"El CO₂ pasó de 280 a más de 420 ppm, más que en 800.000 años."},{"id":"s3","texto":"El sol emite el doble de energía que hace 50 años."},{"id":"s4","texto":"Los volcanes largan más CO₂ que todos los autos juntos."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Una respuesta con un solo dato falso pierde credibilidad. Chequear antes de mandar es clave.","por_opcion":{"s3":"Falso: la energía solar no aumentó desde los años 70.","s4":"Falso: emiten menos del 1 % de lo que emiten las personas."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"aire-suelo-4","rama":"aire_suelo","orden":4,"nivel":2,"titulo_es":"El clima que cambia","bajada_es":"Mares que suben, olas de calor más frecuentes, glaciares que retroceden: lo que ya cambió, cómo nos afecta en Argentina y qué se puede hacer.","objetivos_es":["Describir los cambios observados en temperatura, océano, hielo y nivel del mar","Explicar cómo el calentamiento cambia la frecuencia de los extremos","Interpretar un estudio de atribución y sus límites","Reconocer impactos del cambio climático en distintas regiones de Argentina","Distinguir mitigación y adaptación, y comparar escenarios de futuro"],"repasa":["aire-suelo-3","agua-6","aire-suelo-2","tronco-3"],"requiere_tronco":2,"fuentes":["ipcc-ar6","ipcc-ar6-syr","ipcc-sr15","noaa-nivel-mar","wmo-clima-2024","wwa-atribucion","inventario-glaciares","ley-26639-glaciares","acuerdo-paris","carbon-brief"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"aire-suelo-4.s1","orden":1,"tipo":"leccion","titulo_es":"Lo que ya cambió","bajada_es":"Un océano que guarda el calor, hielo que se derrite y un mar que sube cada vez más rápido.","minutos":11,"pasos":[{"slug":"aire-suelo-4.s1.p1","orden":1,"grupo":"aire-suelo-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El océano guarda casi todo","cuerpo":["Cuando se habla del calentamiento, se suele pensar en el aire. Pero según el IPCC, alrededor del 91 % del calor extra que acumuló el planeta en las últimas décadas fue a parar al océano. El aire se llevó apenas un 1 %; el resto calentó los continentes y derritió hielo. El océano es el gran acumulador del calentamiento."],"datos":{"tipo":"barras","titulo":"A dónde fue el calor extra acumulado por el planeta (aproximado)","unidad":"%","filas":[{"etiqueta":"Océano","valor":91},{"etiqueta":"Continentes","valor":5},{"etiqueta":"Derretir hielo","valor":3},{"etiqueta":"Atmósfera","valor":1}],"nota":"IPCC AR6; valores redondeados."}},"solucion":{}},{"slug":"aire-suelo-4.s1.p2","orden":2,"grupo":"aire-suelo-4.s1.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená dónde se acumuló el calor extra del planeta, de mayor a menor.","items":[{"id":"i1","texto":"Océano"},{"id":"i2","texto":"Continentes"},{"id":"i3","texto":"Derretir hielo"},{"id":"i4","texto":"Atmósfera"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El aire, donde medimos el calentamiento todos los días, guarda apenas una fracción mínima del calor extra.","valores":{"i1":"≈ 91 %","i2":"≈ 5 %","i3":"≈ 3 %","i4":"≈ 1 %"}}},{"slug":"aire-suelo-4.s1.p3","orden":3,"grupo":"aire-suelo-4.s1.p3","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el aire guarda solo el 1 % del calor extra, el calentamiento es menor de lo que parece.","razones":[{"id":"r1","texto":"Porque el océano acumula la mayor parte y sus efectos duran siglos"},{"id":"r2","texto":"Porque el calor del océano desaparece solo"},{"id":"r3","texto":"Porque el aire es lo único que importa"}]},"solucion":{"valor":false,"explicacion":"Es al revés: el océano esconde la mayor parte. Ese calor dilata el agua, derrite hielo desde abajo, afecta a los arrecifes y seguirá influyendo en el clima por siglos.","clave":["r1"]}},{"slug":"aire-suelo-4.s1.p4","orden":4,"grupo":"aire-suelo-4.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El nivel del mar","cuerpo":["El nivel medio del mar subió unos 20 cm entre 1901 y 2018. Sube por dos motivos: el agua se dilata al calentarse, y se suma el agua de glaciares y de las grandes capas de hielo de Groenlandia y la Antártida. Además, el ritmo se aceleró: pasó de alrededor de 1,3 mm por año a comienzos del siglo XX a unos 3,7 mm por año entre 2006 y 2018."]},"solucion":{}},{"slug":"aire-suelo-4.s1.p5","orden":5,"grupo":"aire-suelo-4.s1.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto hace subir el nivel del mar o no?","grupos":[{"id":"g1","nombre":"Hace subir el mar"},{"id":"g2","nombre":"No hace subir el mar"}],"items":[{"id":"i1","texto":"El agua del océano se dilata al calentarse"},{"id":"i2","texto":"Se derrite hielo que ya flotaba en el mar"},{"id":"i3","texto":"Se derriten glaciares de montaña"},{"id":"i4","texto":"Llueve más sobre el océano en una tormenta"},{"id":"i5","texto":"Se derrite hielo de Groenlandia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"El hielo que ya flota desplaza su propio peso en agua: al derretirse, casi no cambia el nivel. El hielo sobre tierra sí lo sube."}},{"slug":"aire-suelo-4.s1.p6","orden":6,"grupo":"aire-suelo-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el mar sube 3,7 mm por año, ¿cuántos centímetros sube en 20 años? Redondeá a un decimal.","unidad":"cm","decimales":1},"solucion":{"valor":7.4,"tolerancia":0.1,"explicacion":"3,7 × 20 = 74 mm = 7,4 cm. Y el ritmo sigue acelerándose, así que la cuenta real será mayor."}},{"slug":"aire-suelo-4.s1.p6.v2","orden":6,"grupo":"aire-suelo-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el mar sube 3,7 mm por año, ¿cuántos centímetros sube en 30 años? Redondeá a un decimal.","unidad":"cm","decimales":1},"solucion":{"valor":11.1,"tolerancia":0.1,"explicacion":"3,7 × 30 = 111 mm = 11,1 cm. Y el ritmo sigue acelerándose, así que la cuenta real será mayor."}},{"slug":"aire-suelo-4.s1.p6.v3","orden":6,"grupo":"aire-suelo-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el mar sube 3,7 mm por año, ¿cuántos centímetros sube en 50 años? Redondeá a un decimal.","unidad":"cm","decimales":1},"solucion":{"valor":18.5,"tolerancia":0.1,"explicacion":"3,7 × 50 = 185 mm = 18,5 cm. Y el ritmo sigue acelerándose, así que la cuenta real será mayor."}},{"slug":"aire-suelo-4.s1.p7","orden":7,"grupo":"aire-suelo-4.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hielo en retirada","cuerpo":["Casi todos los glaciares de montaña del mundo están retrocediendo, incluidos los de los Andes. El hielo marino del Ártico se redujo mucho en extensión y espesor desde que se mide con satélites, en 1979. Groenlandia y la Antártida pierden hielo, y su aporte al nivel del mar crece."]},"solucion":{}},{"slug":"aire-suelo-4.s1.p8","orden":8,"grupo":"aire-suelo-4.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué se acelera el aumento del nivel del mar.","items":[{"id":"i1","texto":"Se acumula más calor en el océano"},{"id":"i2","texto":"El agua se dilata y el hielo se derrite más rápido"},{"id":"i3","texto":"Groenlandia y la Antártida aportan cada vez más agua"},{"id":"i4","texto":"El nivel del mar sube cada año un poco más rápido"},{"id":"i5","texto":"El hielo marino flotante eleva el mar al derretirse"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Más calor acumulado significa más dilatación y más deshielo: la subida se acelera."}},{"slug":"aire-suelo-4.s1.p9","orden":9,"grupo":"aire-suelo-4.s1.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el mar seguirá subiendo durante siglos aunque se frenen las emisiones?","opciones":[{"id":"o1","texto":"El océano profundo y el hielo reaccionan lento"},{"id":"o2","texto":"Porque el agua de lluvia se acumula en los océanos"},{"id":"o3","texto":"Porque la Luna atrae cada vez más agua"},{"id":"o4","texto":"Porque los ríos traen cada vez más agua"}]},"solucion":{"clave":["o1"],"explicacion":"El calor ya acumulado seguirá dilatando el agua y derritiendo hielo. Por eso, cuanto antes se frene, menor será la subida final.","por_opcion":{"o3":"La Luna causa mareas, pero no una subida de largo plazo."}}},{"slug":"aire-suelo-4.s1.p10","orden":10,"grupo":"aire-suelo-4.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada cambio con su dato.","izquierda":[{"id":"a1","texto":"Calor extra en el océano"},{"id":"a2","texto":"Subida del mar 1901–2018"},{"id":"a3","texto":"Ritmo reciente del mar"},{"id":"a4","texto":"Temperatura global"}],"derecha":[{"id":"b1","texto":"Alrededor del 91 %"},{"id":"b2","texto":"Unos 20 cm"},{"id":"b3","texto":"Unos 3,7 mm por año"},{"id":"b4","texto":"Unos 1,2 °C más"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro números que resumen lo que ya cambió."}},{"slug":"aire-suelo-4.s1.p11","orden":11,"grupo":"aire-suelo-4.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El océano absorbió la mayor parte del calor extra."},{"id":"s2","texto":"El nivel del mar sube siempre al mismo ritmo."},{"id":"s3","texto":"Casi todos los glaciares de montaña retroceden."},{"id":"s4","texto":"Si el hielo que flota en el mar se derrite, el mar sube muchísimo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender por qué sube el mar evita confusiones comunes.","por_opcion":{"s2":"El ritmo se aceleró: de 1,3 a unos 3,7 mm por año.","s4":"El hielo que ya flota casi no cambia el nivel al derretirse."}}},{"slug":"aire-suelo-4.s1.p12","orden":12,"grupo":"aire-suelo-4.s1.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué cambios ya se observan en el planeta? Marcá todos.","opciones":[{"id":"o1","texto":"El océano se calienta"},{"id":"o2","texto":"El nivel del mar sube"},{"id":"o3","texto":"Los glaciares retroceden"},{"id":"o4","texto":"El hielo del Ártico aumenta cada año"},{"id":"o5","texto":"La temperatura global bajó desde 1900"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Muchos indicadores distintos, medidos por separado, muestran el mismo calentamiento."}},{"slug":"aire-suelo-4.s1.p13","orden":13,"grupo":"aire-suelo-4.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Alrededor del 91 % del calor extra fue al {{0}}; el mar sube porque el agua se {{1}} y se derrite hielo; y entre 1901 y 2018 subió unos {{2}} cm.","banco":[{"id":"w1","texto":"océano"},{"id":"w2","texto":"dilata"},{"id":"w3","texto":"20"},{"id":"w4","texto":"aire"},{"id":"w5","texto":"congela"},{"id":"w6","texto":"200"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos centrales de los cambios que ya ocurrieron."}},{"slug":"aire-suelo-4.s1.p14","orden":14,"grupo":"aire-suelo-4.s1.p14","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el ritmo de subida del mar, del más lento al más rápido.","items":[{"id":"i1","texto":"Comienzos del siglo XX: unos 1,3 mm por año"},{"id":"i2","texto":"Fines del siglo XX: unos 1,9 mm por año"},{"id":"i3","texto":"Entre 2006 y 2018: unos 3,7 mm por año"}],"extremos":["Más lento","Más rápido"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"En alrededor de un siglo, el ritmo de subida del mar casi se triplicó."}}]},{"slug":"aire-suelo-4.s2","orden":2,"tipo":"leccion","titulo_es":"Extremos más frecuentes","bajada_es":"Olas de calor, lluvias intensas y sequías: cómo un grado de más cambia los eventos extremos, y qué es la atribución.","minutos":11,"pasos":[{"slug":"aire-suelo-4.s2.p1","orden":1,"grupo":"aire-suelo-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un grado cambia mucho","cuerpo":["Un aumento de un grado en el promedio parece poco, pero corre toda la distribución de temperaturas: los días que antes eran extremos se vuelven más comunes, y aparecen extremos que antes casi no existían. Según el IPCC, un calor extremo que en la época preindustrial ocurría una vez cada 10 años hoy ocurre unas 2,8 veces en ese lapso, y con 2 °C de calentamiento ocurriría unas 5,6 veces."],"datos":{"tipo":"barras","titulo":"Veces que ocurre, cada 10 años, un calor extremo que antes pasaba una vez por década","unidad":"veces","filas":[{"etiqueta":"Clima preindustrial","valor":1},{"etiqueta":"Hoy (≈ 1 °C)","valor":2.8},{"etiqueta":"Con 1,5 °C","valor":4.1},{"etiqueta":"Con 2 °C","valor":5.6},{"etiqueta":"Con 4 °C","valor":9.4}],"nota":"IPCC AR6, Resumen para responsables de políticas."}},"solucion":{}},{"slug":"aire-suelo-4.s2.p2","orden":2,"grupo":"aire-suelo-4.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 1,5 °C de calentamiento, un calor extremo que antes ocurría una vez por década ocurriría 4,1 veces por década. ¿Cuántas veces ocurriría en 50 años?","unidad":"veces","decimales":1},"solucion":{"valor":20.5,"tolerancia":0.1,"explicacion":"50 años son 5 décadas: 4,1 × 5 = 20,5. En el clima preindustrial habrían sido 5 veces."}},{"slug":"aire-suelo-4.s2.p2.v2","orden":2,"grupo":"aire-suelo-4.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 2 °C de calentamiento, un calor extremo que antes ocurría una vez por década ocurriría 5,6 veces por década. ¿Cuántas veces ocurriría en 50 años?","unidad":"veces","decimales":1},"solucion":{"valor":28,"tolerancia":0.1,"explicacion":"50 años son 5 décadas: 5,6 × 5 = 28. En el clima preindustrial habrían sido 5 veces."}},{"slug":"aire-suelo-4.s2.p2.v3","orden":2,"grupo":"aire-suelo-4.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 4 °C de calentamiento, un calor extremo que antes ocurría una vez por década ocurriría 9,4 veces por década. ¿Cuántas veces ocurriría en 50 años?","unidad":"veces","decimales":1},"solucion":{"valor":47,"tolerancia":0.1,"explicacion":"50 años son 5 décadas: 9,4 × 5 = 47. En el clima preindustrial habrían sido 5 veces."}},{"slug":"aire-suelo-4.s2.p3","orden":3,"grupo":"aire-suelo-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lluvias más intensas","cuerpo":["El aire más cálido puede contener más vapor de agua: aproximadamente un 7 % más por cada grado. Ese vapor extra puede caer de golpe, así que en muchas regiones las lluvias intensas se vuelven más fuertes y más frecuentes. Al mismo tiempo, en otras regiones, el calor aumenta la evaporación y empeora las sequías. Más calor intensifica los dos extremos del ciclo del agua."]},"solucion":{}},{"slug":"aire-suelo-4.s2.p4","orden":4,"grupo":"aire-suelo-4.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el aire puede contener un 7 % más de vapor por cada grado, ¿cuánto vapor más podría contener, aproximadamente, con 1 grado más? Usá la suma simple.","unidad":"%","decimales":0},"solucion":{"valor":7,"tolerancia":0.5,"explicacion":"1 × 7 % = 7 %, en cuenta simple (en realidad se compone y es un poco más). Ese vapor extra alimenta lluvias más intensas."}},{"slug":"aire-suelo-4.s2.p4.v2","orden":4,"grupo":"aire-suelo-4.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el aire puede contener un 7 % más de vapor por cada grado, ¿cuánto vapor más podría contener, aproximadamente, con 2 grados más? Usá la suma simple.","unidad":"%","decimales":0},"solucion":{"valor":14,"tolerancia":0.5,"explicacion":"2 × 7 % = 14 %, en cuenta simple (en realidad se compone y es un poco más). Ese vapor extra alimenta lluvias más intensas."}},{"slug":"aire-suelo-4.s2.p4.v3","orden":4,"grupo":"aire-suelo-4.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el aire puede contener un 7 % más de vapor por cada grado, ¿cuánto vapor más podría contener, aproximadamente, con 3 grados más? Usá la suma simple.","unidad":"%","decimales":0},"solucion":{"valor":21,"tolerancia":0.5,"explicacion":"3 × 7 % = 21 %, en cuenta simple (en realidad se compone y es un poco más). Ese vapor extra alimenta lluvias más intensas."}},{"slug":"aire-suelo-4.s2.p5","orden":5,"grupo":"aire-suelo-4.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el calentamiento intensifica las lluvias fuertes.","items":[{"id":"i1","texto":"La atmósfera se calienta"},{"id":"i2","texto":"El aire puede contener más vapor de agua"},{"id":"i3","texto":"Las tormentas tienen más agua disponible"},{"id":"i4","texto":"Caen lluvias más intensas en poco tiempo"},{"id":"i5","texto":"Aumentan las inundaciones repentinas"},{"id":"i6","texto":"El aire caliente contiene menos agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un grado más significa más agua en el aire, lista para caer."}},{"slug":"aire-suelo-4.s2.p6","orden":6,"grupo":"aire-suelo-4.s2.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el cambio climático intensifica las lluvias, no puede empeorar las sequías.","razones":[{"id":"r1","texto":"Porque el calor intensifica los dos extremos del ciclo del agua"},{"id":"r2","texto":"Porque las sequías no tienen relación con la temperatura"},{"id":"r3","texto":"Porque llueve igual en todo el mundo"}]},"solucion":{"valor":false,"explicacion":"Puede hacer las dos cosas: más lluvia intensa en algunos lugares y momentos, y más evaporación y sequías en otros. El calor intensifica los extremos del ciclo del agua.","clave":["r1"]}},{"slug":"aire-suelo-4.s2.p7","orden":7,"grupo":"aire-suelo-4.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ciencia de la atribución","cuerpo":["Después de un evento extremo, equipos como World Weather Attribution estiman cuánto cambió su probabilidad por el calentamiento. Comparan el clima actual con un clima simulado sin calentamiento humano. Por ejemplo, encontraron que el calor récord de diciembre de 2022 en Argentina y países vecinos se volvió alrededor de 60 veces más probable por el cambio climático.","Pero no todo se explica así: sobre la gran sequía de 2022–2023 en Argentina, el mismo tipo de estudio concluyó que la falta de lluvia se debió sobre todo a La Niña, aunque las temperaturas más altas probablemente empeoraron sus efectos. La atribución es rigurosa justamente porque a veces dice \"no fue el clima\"."]},"solucion":{}},{"slug":"aire-suelo-4.s2.p8","orden":8,"grupo":"aire-suelo-4.s2.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué hace un estudio de atribución?","opciones":[{"id":"o1","texto":"Estima cuánto cambió la probabilidad de un evento"},{"id":"o2","texto":"Decide quién tiene la culpa legal de un desastre"},{"id":"o3","texto":"Predice el tiempo de la semana que viene"},{"id":"o4","texto":"Mide la lluvia caída en una estación"}]},"solucion":{"clave":["o1"],"explicacion":"Compara el mundo real con uno sin calentamiento humano para estimar cuánto influyó el clima.","por_opcion":{"o3":"Eso es un pronóstico; la atribución analiza eventos que ya pasaron."}}},{"slug":"aire-suelo-4.s2.p9","orden":9,"grupo":"aire-suelo-4.s2.p9","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conclusiones son correctas sobre la atribución? Marcá todas.","opciones":[{"id":"o1","texto":"Compara el clima actual con uno sin calentamiento humano"},{"id":"o2","texto":"Puede concluir que el clima influyó poco en un evento"},{"id":"o3","texto":"Estimó que el calor de diciembre de 2022 fue unas 60 veces más probable"},{"id":"o4","texto":"Dice que todo evento extremo es culpa del cambio climático"},{"id":"o5","texto":"Solo se puede hacer muchos años después del evento"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La atribución no culpa al clima de todo: mide su influencia en cada caso."}},{"slug":"aire-suelo-4.s2.p10","orden":10,"grupo":"aire-suelo-4.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un evento tenía una probabilidad de 1 en 600 por año sin calentamiento y ahora es 60 veces más probable, ¿\"1 en cuántos\" años es ahora?","unidad":"años","decimales":0,"contexto":"Probabilidad de 1 en 600 por año, 60 veces más probable."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"600 ÷ 60 = 10: pasó de ser un evento de 1 en 600 años a uno de 1 en 10 años. Algo casi imposible se vuelve un riesgo con el que hay que planificar."}},{"slug":"aire-suelo-4.s2.p11","orden":11,"grupo":"aire-suelo-4.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada extremo con su relación con el calentamiento.","izquierda":[{"id":"a1","texto":"Olas de calor"},{"id":"a2","texto":"Lluvias intensas"},{"id":"a3","texto":"Sequías"},{"id":"a4","texto":"Incendios forestales"}],"derecha":[{"id":"b1","texto":"Más frecuentes e intensas"},{"id":"b2","texto":"Más vapor de agua en el aire"},{"id":"b3","texto":"Más evaporación en zonas secas"},{"id":"b4","texto":"Vegetación más seca y más calor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada extremo responde al calentamiento por un mecanismo distinto."}},{"slug":"aire-suelo-4.s2.p12","orden":12,"grupo":"aire-suelo-4.s2.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y su bajada y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El calor extremo es más frecuente que en la época preindustrial."},{"id":"s2","texto":"Cualquier tormenta fuerte es 100 % culpa del cambio climático."},{"id":"s3","texto":"El aire cálido contiene más vapor de agua."},{"id":"s4","texto":"La sequía de 2022–2023 se explicó solo por el cambio climático."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Exagerar también desinforma. La ciencia de la atribución es precisa y matizada.","por_opcion":{"s2":"Hay que estudiar cada caso: la atribución estima cuánto influyó.","s4":"El estudio atribuyó la falta de lluvia sobre todo a La Niña."}}},{"slug":"aire-suelo-4.s2.p13","orden":13,"grupo":"aire-suelo-4.s2.p13","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos niveles de calentamiento según cuántas veces por década ocurriría un calor extremo que antes pasaba una vez, de menos a más.","items":[{"id":"i1","texto":"Clima preindustrial"},{"id":"i2","texto":"Hoy, con alrededor de 1 °C"},{"id":"i3","texto":"Con 1,5 °C"},{"id":"i4","texto":"Con 2 °C"}],"extremos":["Menos frecuente","Más frecuente"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada medio grado suma más días de calor extremo: la frecuencia no crece de a poco, se multiplica.","valores":{"i1":"1 vez","i2":"≈ 2,8 veces","i3":"≈ 4,1 veces","i4":"≈ 5,6 veces"}}},{"slug":"aire-suelo-4.s2.p14","orden":14,"grupo":"aire-suelo-4.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El aire puede contener alrededor de un {{0}} % más de vapor por grado; un estudio de {{1}} estima cuánto influyó el clima en un evento; y la sequía de 2022–2023 se explicó sobre todo por La {{2}}.","banco":[{"id":"w1","texto":"7"},{"id":"w2","texto":"atribución"},{"id":"w3","texto":"Niña"},{"id":"w4","texto":"70"},{"id":"w5","texto":"pronóstico"},{"id":"w6","texto":"Luna"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para hablar con precisión de los eventos extremos."}}]},{"slug":"aire-suelo-4.s3","orden":3,"tipo":"leccion","titulo_es":"El cambio climático en Argentina","bajada_es":"Glaciares, ríos de Cuyo, lluvias en la llanura, calor urbano, costas y mosquitos: los impactos de región en región.","minutos":11,"pasos":[{"slug":"aire-suelo-4.s3.p1","orden":1,"grupo":"aire-suelo-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Glaciares y agua de montaña","cuerpo":["Argentina tiene miles de glaciares a lo largo de la cordillera, registrados en el Inventario Nacional de Glaciares. La mayoría está retrocediendo. En Cuyo, los ríos que riegan viñedos, huertas y ciudades dependen en gran parte de la nieve y el hielo de la montaña. Cuando nieva menos y los glaciares se achican, llega menos agua en los meses secos. En la última década, la región central de los Andes sufrió una sequía prolongada.","La Ley 26.639, de 2010, protege los glaciares y el ambiente periglacial como reservas de agua."]},"solucion":{}},{"slug":"aire-suelo-4.s3.p2","orden":2,"grupo":"aire-suelo-4.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el calentamiento afecta el agua en Mendoza.","items":[{"id":"i1","texto":"Sube la temperatura en la cordillera"},{"id":"i2","texto":"Nieva menos y los glaciares se achican"},{"id":"i3","texto":"Llega menos agua a los ríos en verano"},{"id":"i4","texto":"Hay menos agua para riego y ciudades"},{"id":"i5","texto":"Los glaciares crecen con el calor"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"En zonas áridas, la montaña es el tanque de agua. Si se achica, la ciudad y el campo lo sienten."}},{"slug":"aire-suelo-4.s3.p3","orden":3,"grupo":"aire-suelo-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Más lluvia en la llanura","cuerpo":["Durante la segunda mitad del siglo XX, las lluvias aumentaron en gran parte del este y el noreste del país. Eso permitió extender la agricultura hacia el oeste, pero también trajo más inundaciones. Además, las lluvias intensas se volvieron más frecuentes en muchas zonas, y las olas de calor, más largas y frecuentes, sobre todo en el norte y el centro."]},"solucion":{}},{"slug":"aire-suelo-4.s3.p4","orden":4,"grupo":"aire-suelo-4.s3.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué impacto corresponde a cada región?","grupos":[{"id":"g1","nombre":"Cuyo y la cordillera"},{"id":"g2","nombre":"Llanura pampeana y litoral"},{"id":"g3","nombre":"Costa atlántica y Río de la Plata"}],"items":[{"id":"i1","texto":"Menos nieve y ríos con menos agua"},{"id":"i2","texto":"Más inundaciones por lluvias intensas"},{"id":"i3","texto":"Erosión costera y sudestadas más dañinas"},{"id":"i4","texto":"Glaciares que retroceden"},{"id":"i5","texto":"Frontera agrícola que se corrió al oeste"},{"id":"i6","texto":"Subida del nivel del mar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"El cambio climático no se siente igual en todo el país: cada región tiene sus riesgos."}},{"slug":"aire-suelo-4.s3.p5","orden":5,"grupo":"aire-suelo-4.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ciudades, calor y salud","cuerpo":["En las ciudades, las olas de calor se sienten más por el efecto isla de calor. Afectan sobre todo a personas mayores, bebés, personas con enfermedades crónicas y quienes trabajan al aire libre. El Servicio Meteorológico Nacional emite alertas por calor extremo.","Además, el mosquito que transmite el dengue se expandió hacia el sur en las últimas décadas. Temperaturas más altas y lluvias lo favorecen, junto con otros factores como los recipientes con agua estancada y la urbanización. La temporada 2023–2024 fue la mayor epidemia de dengue registrada en el país."]},"solucion":{}},{"slug":"aire-suelo-4.s3.p6","orden":6,"grupo":"aire-suelo-4.s3.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué grupo es más vulnerable a una ola de calor?","opciones":[{"id":"o1","texto":"Las personas mayores que viven solas"},{"id":"o2","texto":"Los adultos jóvenes que trabajan en oficinas"},{"id":"o3","texto":"Quienes viven en zonas frías del sur"},{"id":"o4","texto":"Quienes tienen aire acondicionado en casa"}]},"solucion":{"clave":["o1"],"explicacion":"Las personas mayores regulan peor su temperatura y, si viven solas, nadie advierte a tiempo los síntomas.","por_opcion":{"o3":"También pueden sufrir, pero el riesgo mayor lo tienen personas con menos capacidad de regular su temperatura."}}},{"slug":"aire-suelo-4.s3.p7","orden":7,"grupo":"aire-suelo-4.s3.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué factores favorecen la expansión del dengue? Marcá todos.","opciones":[{"id":"o1","texto":"Temperaturas más altas"},{"id":"o2","texto":"Recipientes con agua estancada"},{"id":"o3","texto":"Lluvias que dejan charcos y cacharros llenos"},{"id":"o4","texto":"Las heladas prolongadas"},{"id":"o5","texto":"La falta total de agua"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El clima ayuda al mosquito, pero la prevención en cada casa sigue siendo clave: sin agua estancada no hay criaderos."}},{"slug":"aire-suelo-4.s3.p8","orden":8,"grupo":"aire-suelo-4.s3.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El dengue se expande solo por el cambio climático.","razones":[{"id":"r1","texto":"Porque influyen también otros factores, como el agua estancada"},{"id":"r2","texto":"Porque el clima no tiene ninguna relación"},{"id":"r3","texto":"Porque el dengue no existe en Argentina"}]},"solucion":{"valor":false,"explicacion":"El clima influye, pero también la urbanización, el agua estancada en recipientes, los viajes y el control del mosquito. Hay varias causas a la vez.","clave":["r1"]}},{"slug":"aire-suelo-4.s3.p9","orden":9,"grupo":"aire-suelo-4.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una ciudad tenía en promedio 3 días de ola de calor por verano y ahora tiene 9, ¿cuántas veces más días tiene?","unidad":"veces","decimales":1,"contexto":"De 3 a 9 días de ola de calor por verano."},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"9 ÷ 3 = 3 veces. Datos ficticios, pero la tendencia a más días de calor extremo es real en muchas ciudades del país."}},{"slug":"aire-suelo-4.s3.p9.v2","orden":9,"grupo":"aire-suelo-4.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una ciudad tenía en promedio 4 días de ola de calor por verano y ahora tiene 10, ¿cuántas veces más días tiene?","unidad":"veces","decimales":1,"contexto":"De 4 a 10 días de ola de calor por verano."},"solucion":{"valor":2.5,"tolerancia":0.1,"explicacion":"10 ÷ 4 = 2,5 veces. Datos ficticios, pero la tendencia a más días de calor extremo es real en muchas ciudades del país."}},{"slug":"aire-suelo-4.s3.p9.v3","orden":9,"grupo":"aire-suelo-4.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una ciudad tenía en promedio 2 días de ola de calor por verano y ahora tiene 8, ¿cuántas veces más días tiene?","unidad":"veces","decimales":1,"contexto":"De 2 a 8 días de ola de calor por verano."},"solucion":{"valor":4,"tolerancia":0.1,"explicacion":"8 ÷ 2 = 4 veces. Datos ficticios, pero la tendencia a más días de calor extremo es real en muchas ciudades del país."}},{"slug":"aire-suelo-4.s3.p10","orden":10,"grupo":"aire-suelo-4.s3.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada impacto con una región o sistema de Argentina.","izquierda":[{"id":"a1","texto":"Menos agua de deshielo"},{"id":"a2","texto":"Erosión y sudestadas"},{"id":"a3","texto":"Expansión del dengue"},{"id":"a4","texto":"Más inundaciones"}],"derecha":[{"id":"b1","texto":"Oasis de riego de Cuyo"},{"id":"b2","texto":"Costa bonaerense"},{"id":"b3","texto":"Ciudades del centro y norte"},{"id":"b4","texto":"Llanura pampeana"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer los impactos locales ayuda a planificar la adaptación en cada lugar."}},{"slug":"aire-suelo-4.s3.p11","orden":11,"grupo":"aire-suelo-4.s3.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año se sancionó la Ley de Glaciares en Argentina.","min":1950,"max":2025,"paso":1,"unidad":"","escala":"lineal"},"solucion":{"valor":2010,"banda":"lineal","explicacion":"En 2010: la Ley 26.639 protege glaciares y ambiente periglacial como reservas estratégicas de agua."}},{"slug":"aire-suelo-4.s3.p12","orden":12,"grupo":"aire-suelo-4.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En Cuyo, los ríos dependen en gran parte de la nieve y los glaciares."},{"id":"s2","texto":"Los glaciares argentinos están creciendo en su mayoría."},{"id":"s3","texto":"Las lluvias aumentaron en gran parte del este del país en el siglo XX."},{"id":"s4","texto":"Las olas de calor afectan a todas las personas por igual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los impactos son desiguales entre regiones y entre personas.","por_opcion":{"s2":"La mayoría está retrocediendo.","s4":"Afectan más a mayores, bebés, enfermos crónicos y trabajadores al aire libre."}}},{"slug":"aire-suelo-4.s3.p13","orden":13,"grupo":"aire-suelo-4.s3.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En Mendoza, ¿por qué preocupa tanto un invierno con poca nieve en la cordillera?","opciones":[{"id":"o1","texto":"Los ríos del verano dependen de esa nieve"},{"id":"o2","texto":"Porque la nieve es necesaria para el turismo de playa"},{"id":"o3","texto":"Porque en verano llueve muchísimo en el llano"},{"id":"o4","texto":"Porque sin nieve los glaciares crecen más rápido"}]},"solucion":{"clave":["o1"],"explicacion":"La nieve del invierno es el agua del verano: se derrite de a poco y alimenta ríos, canales y acequias.","por_opcion":{"o3":"Es al revés: Mendoza es árida y el verano depende del deshielo."}}},{"slug":"aire-suelo-4.s3.p14","orden":14,"grupo":"aire-suelo-4.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En Cuyo, el agua de riego depende de la {{0}} y los glaciares; en la llanura aumentaron las {{1}}; y el mosquito del {{2}} se expandió hacia el sur.","banco":[{"id":"w1","texto":"nieve"},{"id":"w2","texto":"inundaciones"},{"id":"w3","texto":"dengue"},{"id":"w4","texto":"arena"},{"id":"w5","texto":"heladas"},{"id":"w6","texto":"paludismo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres impactos del cambio climático en distintas regiones del país."}}]},{"slug":"aire-suelo-4.s4","orden":4,"tipo":"leccion","titulo_es":"Mitigar y adaptarse","bajada_es":"Reducir las emisiones y prepararse para lo que ya viene: dos respuestas necesarias y complementarias.","minutos":12,"pasos":[{"slug":"aire-suelo-4.s4.p1","orden":1,"grupo":"aire-suelo-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos respuestas","cuerpo":["Frente al cambio climático hay dos tipos de respuesta. Mitigar es reducir las causas: emitir menos gases o absorber más carbono. Adaptarse es prepararse para los impactos que ya ocurren o van a ocurrir: sistemas de alerta, arbolado urbano, infraestructura contra inundaciones, cultivos resistentes a la sequía.","No son opciones alternativas: sin mitigación, la adaptación se vuelve cada vez más cara e incluso imposible; sin adaptación, los impactos que ya están en marcha causan daños evitables."]},"solucion":{}},{"slug":"aire-suelo-4.s4.p2","orden":2,"grupo":"aire-suelo-4.s4.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es mitigación o adaptación?","grupos":[{"id":"g1","nombre":"Mitigación"},{"id":"g2","nombre":"Adaptación"}],"items":[{"id":"i1","texto":"Instalar paneles solares"},{"id":"i2","texto":"Sistema de alerta por olas de calor"},{"id":"i3","texto":"Reducir fugas de metano"},{"id":"i4","texto":"Plantar árboles para dar sombra en veredas"},{"id":"i5","texto":"Frenar desmontes"},{"id":"i6","texto":"Elevar casas en zonas inundables"},{"id":"i7","texto":"Andar más en bicicleta"},{"id":"i8","texto":"Cultivos resistentes a la sequía"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Mitigar ataca las causas; adaptarse reduce los daños. Plantar árboles, además, puede hacer las dos cosas."}},{"slug":"aire-suelo-4.s4.p3","orden":3,"grupo":"aire-suelo-4.s4.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si nos adaptamos bien, no hace falta reducir las emisiones.","razones":[{"id":"r1","texto":"Porque la adaptación tiene límites si el calentamiento sigue"},{"id":"r2","texto":"Porque adaptarse es siempre gratis"},{"id":"r3","texto":"Porque los impactos se detienen solos"}]},"solucion":{"valor":false,"explicacion":"La adaptación tiene límites: con mucho calentamiento, algunos impactos no se pueden evitar, como la pérdida de glaciares o de arrecifes. Hacen falta las dos cosas.","clave":["r1"]}},{"slug":"aire-suelo-4.s4.p4","orden":4,"grupo":"aire-suelo-4.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Soluciones que hacen las dos cosas","cuerpo":["Algunas acciones mitigan y adaptan al mismo tiempo. Un bosque ribereño conservado guarda carbono y amortigua crecidas. El arbolado urbano absorbe algo de carbono, pero sobre todo refresca la ciudad. Un suelo con más materia orgánica guarda carbono y retiene más agua en sequías. Estas soluciones basadas en la naturaleza suelen tener además beneficios para la biodiversidad."]},"solucion":{}},{"slug":"aire-suelo-4.s4.p5","orden":5,"grupo":"aire-suelo-4.s4.p5","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones mitigan y adaptan a la vez? Marcá todas.","opciones":[{"id":"o1","texto":"Conservar humedales que guardan carbono y absorben crecidas"},{"id":"o2","texto":"Aumentar la materia orgánica del suelo"},{"id":"o3","texto":"Plantar árboles nativos en la ciudad"},{"id":"o4","texto":"Construir un muro costero de hormigón"},{"id":"o5","texto":"Instalar aire acondicionado alimentado con gas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El muro adapta pero no mitiga; el aire acondicionado con energía fósil adapta pero suma emisiones."}},{"slug":"aire-suelo-4.s4.p6","orden":6,"grupo":"aire-suelo-4.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La mala adaptación","cuerpo":["Hay respuestas que parecen adaptación pero empeoran las cosas: se llaman mala adaptación. Por ejemplo, depender solo del aire acondicionado alimentado con energía fósil aumenta las emisiones; un muro costero puede trasladar la erosión a la playa vecina; y canalizar un arroyo puede mover la inundación aguas abajo."]},"solucion":{}},{"slug":"aire-suelo-4.s4.p7","orden":7,"grupo":"aire-suelo-4.s4.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un barrio construye un terraplén que lo protege de una crecida, pero el agua se desvía al barrio vecino. ¿Qué es esto?","opciones":[{"id":"o1","texto":"Un caso de mala adaptación"},{"id":"o2","texto":"Una medida de mitigación"},{"id":"o3","texto":"Una adaptación perfecta"},{"id":"o4","texto":"Una solución basada en la naturaleza"}]},"solucion":{"clave":["o1"],"explicacion":"Una buena adaptación mira la cuenca completa, no solo un barrio.","por_opcion":{"o3":"Protege a uno pero traslada el daño a otro: es mala adaptación."}}},{"slug":"aire-suelo-4.s4.p8","orden":8,"grupo":"aire-suelo-4.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Acuerdo de París","cuerpo":["En 2015, casi todos los países firmaron el Acuerdo de París. Se comprometieron a mantener el calentamiento muy por debajo de 2 °C y a hacer esfuerzos para limitarlo a 1,5 °C. Cada país presenta sus propias metas, llamadas contribuciones determinadas a nivel nacional (NDC), y debe actualizarlas cada cinco años con más ambición. Para estabilizar la temperatura, las emisiones netas de CO₂ tienen que llegar a cero."]},"solucion":{}},{"slug":"aire-suelo-4.s4.p9","orden":9,"grupo":"aire-suelo-4.s4.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Mitigación"},{"id":"a2","texto":"Adaptación"},{"id":"a3","texto":"NDC"},{"id":"a4","texto":"Emisiones netas cero"}],"derecha":[{"id":"b1","texto":"Reducir emisiones o absorber carbono"},{"id":"b2","texto":"Prepararse para los impactos"},{"id":"b3","texto":"Metas climáticas que presenta cada país"},{"id":"b4","texto":"Emitir no más de lo que se absorbe"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El vocabulario básico de la política climática."}},{"slug":"aire-suelo-4.s4.p10","orden":10,"grupo":"aire-suelo-4.s4.p10","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo funciona el ciclo del Acuerdo de París.","items":[{"id":"i1","texto":"Cada país presenta sus metas (NDC)"},{"id":"i2","texto":"Informa sus avances de forma transparente"},{"id":"i3","texto":"Se hace un balance mundial de lo logrado"},{"id":"i4","texto":"Cada país actualiza sus metas con más ambición"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El acuerdo funciona como un ciclo que se repite cada cinco años, subiendo la ambición."}},{"slug":"aire-suelo-4.s4.p11","orden":11,"grupo":"aire-suelo-4.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema de alerta temprana cuesta 1 millón de pesos por año y evita daños por 4 millones. ¿Cuántos pesos de daño evita por cada peso invertido?","unidad":"pesos","decimales":0,"contexto":"Costo 1 millones por año; daños evitados 4 millones."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"4 ÷ 1 = 4. Datos ficticios, pero los estudios coinciden en que la adaptación temprana suele ahorrar varias veces lo que cuesta."}},{"slug":"aire-suelo-4.s4.p11.v2","orden":11,"grupo":"aire-suelo-4.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema de alerta temprana cuesta 2 millónes de pesos por año y evita daños por 10 millones. ¿Cuántos pesos de daño evita por cada peso invertido?","unidad":"pesos","decimales":0,"contexto":"Costo 2 millones por año; daños evitados 10 millones."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"10 ÷ 2 = 5. Datos ficticios, pero los estudios coinciden en que la adaptación temprana suele ahorrar varias veces lo que cuesta."}},{"slug":"aire-suelo-4.s4.p11.v3","orden":11,"grupo":"aire-suelo-4.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema de alerta temprana cuesta 3 millónes de pesos por año y evita daños por 12 millones. ¿Cuántos pesos de daño evita por cada peso invertido?","unidad":"pesos","decimales":0,"contexto":"Costo 3 millones por año; daños evitados 12 millones."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"12 ÷ 3 = 4. Datos ficticios, pero los estudios coinciden en que la adaptación temprana suele ahorrar varias veces lo que cuesta."}},{"slug":"aire-suelo-4.s4.p12","orden":12,"grupo":"aire-suelo-4.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El Acuerdo de París busca limitar el calentamiento muy por debajo de 2 °C."},{"id":"s2","texto":"Mitigar y adaptarse son opciones alternativas: con una alcanza."},{"id":"s3","texto":"Conservar humedales puede mitigar y adaptar a la vez."},{"id":"s4","texto":"Cualquier obra contra inundaciones es buena adaptación."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Pensar bien las respuestas evita gastar en soluciones que empeoran el problema.","por_opcion":{"s2":"Son complementarias; hacen falta las dos.","s4":"Si traslada el daño a otros, es mala adaptación."}}},{"slug":"aire-suelo-4.s4.p13","orden":13,"grupo":"aire-suelo-4.s4.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El Acuerdo de París fija la misma meta de reducción, obligatoria, para todos los países.","razones":[{"id":"r1","texto":"Porque cada país define su propia meta y la actualiza"},{"id":"r2","texto":"Porque el acuerdo no tiene ninguna meta de temperatura"},{"id":"r3","texto":"Porque solo lo firmaron dos países"}]},"solucion":{"valor":false,"explicacion":"Cada país define su propia meta (NDC) y la actualiza cada cinco años. Lo común es el objetivo de temperatura y la obligación de informar con transparencia.","clave":["r1"]}},{"slug":"aire-suelo-4.s4.p14","orden":14,"grupo":"aire-suelo-4.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Reducir emisiones es {{0}}; prepararse para los impactos es {{1}}; y para estabilizar la temperatura, las emisiones netas de CO₂ tienen que llegar a {{2}}.","banco":[{"id":"w1","texto":"mitigar"},{"id":"w2","texto":"adaptarse"},{"id":"w3","texto":"cero"},{"id":"w4","texto":"olvidar"},{"id":"w5","texto":"resignarse"},{"id":"w6","texto":"duplicarse"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los conceptos básicos de la respuesta al cambio climático."}},{"slug":"aire-suelo-4.s4.p15","orden":15,"grupo":"aire-suelo-4.s4.p15","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una ciudad con olas de calor cada vez más largas, ¿qué medida combina mejor adaptación y mitigación?","opciones":[{"id":"o1","texto":"Arbolado nativo en veredas y plazas"},{"id":"o2","texto":"Repartir ventiladores en los días críticos"},{"id":"o3","texto":"Pintar las calles de negro"},{"id":"o4","texto":"Cerrar las plazas en verano para cuidarlas"}]},"solucion":{"clave":["o1"],"explicacion":"Los árboles dan sombra, refrescan, absorben algo de carbono y suman biodiversidad.","por_opcion":{"o3":"El asfalto oscuro absorbe más calor: empeora la isla de calor."}}}]},{"slug":"aire-suelo-4.s5","orden":5,"tipo":"leccion","titulo_es":"Qué futuro depende de hoy","bajada_es":"Escenarios, la diferencia entre 1,5 y 2 °C, y por qué cada décima de grado cuenta.","minutos":11,"pasos":[{"slug":"aire-suelo-4.s5.p1","orden":1,"grupo":"aire-suelo-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Escenarios","cuerpo":["Nadie sabe cuánto emitiremos en el futuro, así que el IPCC trabaja con escenarios. En un escenario de emisiones muy bajas, que llegan a cero neto hacia mediados de siglo, el calentamiento hacia fines del siglo XXI sería de alrededor de 1,4 °C. En uno intermedio, de unos 2,7 °C. Y en uno de emisiones muy altas, de unos 4,4 °C.","La física del clima es la misma en todos los escenarios. Lo que cambia son las decisiones."],"datos":{"tipo":"barras","titulo":"Calentamiento estimado para 2081–2100 según el escenario (mejor estimación)","unidad":"°C","filas":[{"etiqueta":"Emisiones muy bajas","valor":1.4},{"etiqueta":"Emisiones intermedias","valor":2.7},{"etiqueta":"Emisiones muy altas","valor":4.4}],"nota":"IPCC AR6, Grupo de Trabajo I."}},"solucion":{}},{"slug":"aire-suelo-4.s5.p2","orden":2,"grupo":"aire-suelo-4.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué define principalmente cuánto se calentará el planeta este siglo?","opciones":[{"id":"o1","texto":"Cuánto CO₂ y otros gases emitamos"},{"id":"o2","texto":"La posición de los planetas en el sistema solar"},{"id":"o3","texto":"Los ciclos naturales del sol, que dominan todo"},{"id":"o4","texto":"La cantidad de volcanes activos"}]},"solucion":{"clave":["o1"],"explicacion":"Los escenarios muestran que la diferencia entre 1,4 y 4,4 °C depende de las emisiones.","por_opcion":{"o3":"La energía solar no aumentó; el factor principal son las emisiones."}}},{"slug":"aire-suelo-4.s5.p3","orden":3,"grupo":"aire-suelo-4.s5.p3","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los escenarios del IPCC según el calentamiento esperado a fines de siglo, de menor a mayor.","items":[{"id":"i1","texto":"Emisiones muy bajas, cero neto hacia 2050"},{"id":"i2","texto":"Emisiones intermedias"},{"id":"i3","texto":"Emisiones muy altas"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Un mismo planeta, tres futuros muy distintos.","valores":{"i1":"≈ 1,4 °C","i2":"≈ 2,7 °C","i3":"≈ 4,4 °C"}}},{"slug":"aire-suelo-4.s5.p4","orden":4,"grupo":"aire-suelo-4.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"1,5 no es lo mismo que 2","cuerpo":["Según el informe especial del IPCC sobre 1,5 °C, medio grado hace mucha diferencia. Con 1,5 °C se perdería entre el 70 y el 90 % de los arrecifes de coral tropicales; con 2 °C, más del 99 %. El nivel del mar subiría unos 10 cm menos hacia 2100 con 1,5 °C que con 2 °C. Y el porcentaje de especies de insectos que perderían más de la mitad de su área de distribución sería del 6 % con 1,5 °C y del 18 % con 2 °C."],"datos":{"tipo":"tabla","titulo":"Diferencias entre 1,5 °C y 2 °C de calentamiento","columnas":["Impacto","Con 1,5 °C","Con 2 °C"],"filas":[["Arrecifes de coral perdidos","70–90 %","más del 99 %"],["Insectos que pierden más de la mitad de su área","6 %","18 %"],["Plantas que pierden más de la mitad de su área","8 %","16 %"],["Veranos árticos sin hielo marino","uno por siglo","uno por década"]],"nota":"IPCC, Informe especial sobre 1,5 °C (2018)."}},"solucion":{}},{"slug":"aire-suelo-4.s5.p5","orden":5,"grupo":"aire-suelo-4.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 1,5 °C, el 6 % de las especies de insectos perdería más de la mitad de su área; con 2 °C, el 18 %. ¿Cuántas veces mayor es el impacto con 2 °C?","unidad":"veces","decimales":0,"contexto":"6 % con 1,5 °C y 18 % con 2 °C."},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"18 ÷ 6 = 3. Medio grado más triplica la proporción de insectos muy afectados."}},{"slug":"aire-suelo-4.s5.p6","orden":6,"grupo":"aire-suelo-4.s5.p6","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada impacto con su valor a 2 °C.","izquierda":[{"id":"a1","texto":"Arrecifes de coral perdidos"},{"id":"a2","texto":"Insectos muy afectados"},{"id":"a3","texto":"Plantas muy afectadas"},{"id":"a4","texto":"Veranos árticos sin hielo"}],"derecha":[{"id":"b1","texto":"Más del 99 %"},{"id":"b2","texto":"18 %"},{"id":"b3","texto":"16 %"},{"id":"b4","texto":"Uno por década"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Con 2 °C los impactos no son \"un poco peores\": en muchos casos se duplican o triplican."}},{"slug":"aire-suelo-4.s5.p7","orden":7,"grupo":"aire-suelo-4.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si ya no se puede limitar el calentamiento a 1,5 °C, da lo mismo llegar a 2 °C o a 3 °C.","razones":[{"id":"r1","texto":"Porque los impactos crecen con cada décima de grado"},{"id":"r2","texto":"Porque los impactos se detienen en 1,5 °C"},{"id":"r3","texto":"Porque 3 °C tiene menos impactos que 2 °C"}]},"solucion":{"valor":false,"explicacion":"Cada décima de grado cuenta: los impactos crecen con cada aumento. Limitar a 1,7 °C es mucho mejor que llegar a 2 °C, y 2 °C es mucho mejor que 3 °C.","clave":["r1"]}},{"slug":"aire-suelo-4.s5.p8","orden":8,"grupo":"aire-suelo-4.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Umbrales","cuerpo":["Algunos sistemas pueden cruzar umbrales a partir de los cuales el cambio se vuelve difícil de revertir durante siglos o milenios, como la pérdida de grandes masas de hielo o la muerte masiva de arrecifes. No se conoce con exactitud dónde están esos umbrales, y el riesgo de cruzarlos aumenta con cada grado. Es otra razón para actuar cuanto antes."]},"solucion":{}},{"slug":"aire-suelo-4.s5.p9","orden":9,"grupo":"aire-suelo-4.s5.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué conviene reducir emisiones cuanto antes.","items":[{"id":"i1","texto":"El CO₂ se acumula en la atmósfera durante siglos"},{"id":"i2","texto":"El calentamiento depende del total acumulado"},{"id":"i3","texto":"Cada año de demora suma calentamiento difícil de revertir"},{"id":"i4","texto":"Actuar antes limita los impactos y el riesgo de umbrales"},{"id":"i5","texto":"El CO₂ desaparece solo en pocos meses"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Como el CO₂ se acumula, cada tonelada evitada hoy vale para siempre."}},{"slug":"aire-suelo-4.s5.p10","orden":10,"grupo":"aire-suelo-4.s5.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué afirmaciones sobre el futuro del clima son correctas? Marcá todas.","opciones":[{"id":"o1","texto":"El calentamiento futuro depende de las emisiones"},{"id":"o2","texto":"Cada décima de grado evitada reduce impactos"},{"id":"o3","texto":"Para estabilizar la temperatura, el CO₂ neto debe llegar a cero"},{"id":"o4","texto":"Ya es tarde y nada de lo que hagamos cambia el resultado"},{"id":"o5","texto":"El clima volverá solo a como era en 1900"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El futuro no está escrito: depende de lo que se haga en estas décadas."}},{"slug":"aire-suelo-4.s5.p11","orden":11,"grupo":"aire-suelo-4.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un calor extremo de \"1 en 10 años\" ocurriría 4,1 veces por década con 1,5 °C y 5,6 veces con 2 °C. ¿Cuántos eventos más por década habría con 2 °C?","unidad":"eventos","decimales":1,"contexto":"4.1 eventos con 1.5 °C y 5.6 con 2 °C."},"solucion":{"valor":1.5,"tolerancia":0.1,"explicacion":"5,6 − 4,1 = 1,5 eventos más por década. Valores aproximados del IPCC; el de 3 °C está interpolado."}},{"slug":"aire-suelo-4.s5.p11.v2","orden":11,"grupo":"aire-suelo-4.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un calor extremo de \"1 en 10 años\" ocurriría 5,6 veces por década con 2 °C y 7,2 veces con 3 °C. ¿Cuántos eventos más por década habría con 3 °C?","unidad":"eventos","decimales":1,"contexto":"5.6 eventos con 2 °C y 7.2 con 3 °C."},"solucion":{"valor":1.6,"tolerancia":0.1,"explicacion":"7,2 − 5,6 = 1,6 eventos más por década. Valores aproximados del IPCC; el de 3 °C está interpolado."}},{"slug":"aire-suelo-4.s5.p11.v3","orden":11,"grupo":"aire-suelo-4.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un calor extremo de \"1 en 10 años\" ocurriría 4,1 veces por década con 1,5 °C y 7,2 veces con 3 °C. ¿Cuántos eventos más por década habría con 3 °C?","unidad":"eventos","decimales":1,"contexto":"4.1 eventos con 1.5 °C y 7.2 con 3 °C."},"solucion":{"valor":3.1,"tolerancia":0.1,"explicacion":"7,2 − 4,1 = 3,1 eventos más por década. Valores aproximados del IPCC; el de 3 °C está interpolado."}},{"slug":"aire-suelo-4.s5.p12","orden":12,"grupo":"aire-suelo-4.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Con 1,5 °C se perderían muchos arrecifes, pero con 2 °C casi todos."},{"id":"s2","texto":"Medio grado más no cambia nada importante."},{"id":"s3","texto":"En un escenario de emisiones muy bajas, el calentamiento rondaría 1,4 °C."},{"id":"s4","texto":"Como ya estamos en 1,2 °C, nada de lo que hagamos importa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El fatalismo es tan equivocado como la negación: los dos llevan a no hacer nada.","por_opcion":{"s2":"Con 2 °C muchos impactos se duplican o triplican respecto de 1,5 °C.","s4":"La diferencia entre 1,4 °C y 4,4 °C depende de las decisiones de estas décadas."}}},{"slug":"aire-suelo-4.s5.p13","orden":13,"grupo":"aire-suelo-4.s5.p13","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué actitud frente al cambio climático expresa cada frase?","grupos":[{"id":"g1","nombre":"Negación"},{"id":"g2","nombre":"Fatalismo"},{"id":"g3","nombre":"Acción informada"}],"items":[{"id":"i1","texto":"\"El cambio climático es un invento\""},{"id":"i2","texto":"\"Ya es tarde, no hay nada que hacer\""},{"id":"i3","texto":"\"Cada décima de grado evitada cuenta\""},{"id":"i4","texto":"\"Siempre hizo calor en verano, no pasa nada\""},{"id":"i5","texto":"\"Lo que hagamos acá no cambia nada\""},{"id":"i6","texto":"\"Hay que reducir emisiones y adaptarse a la vez\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La negación y el fatalismo llevan al mismo lugar: no hacer nada. La evidencia apoya actuar."}},{"slug":"aire-suelo-4.s5.p14","orden":14,"grupo":"aire-suelo-4.s5.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Con 2 °C se perdería más del 99 % de los {{0}} de coral; en un escenario de emisiones muy altas, el calentamiento rondaría los {{1}} °C; y cada {{2}} de grado cuenta.","banco":[{"id":"w1","texto":"arrecifes"},{"id":"w2","texto":"4,4"},{"id":"w3","texto":"décima"},{"id":"w4","texto":"bosques"},{"id":"w5","texto":"0,5"},{"id":"w6","texto":"tonelada"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para entender por qué el futuro depende de hoy."}}]},{"slug":"aire-suelo-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el clima que cambia","bajada_es":"Cambios observados, extremos, atribución, impactos en Argentina, mitigación, adaptación y escenarios, mezclados.","minutos":8,"pasos":[{"slug":"aire-suelo-4.s6.p1","orden":1,"grupo":"aire-suelo-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El clima que cambia». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"aire-suelo-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el plan climático de Villa Ribera","bajada_es":"Un pueblo junto a un río sufre crecidas y olas de calor. Con los datos, armá un plan que combine mitigación y adaptación.","minutos":10,"pasos":[{"slug":"aire-suelo-4.s7.p1","orden":1,"grupo":"aire-suelo-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Villa Ribera tiene 20.000 habitantes y está junto a un río de llanura. En los últimos 20 años tuvo cuatro inundaciones graves, y los días de calor extremo pasaron de 4 a 11 por verano. El municipio tiene un presupuesto limitado y estas propuestas: un sistema de alerta temprana de crecidas, conservar el humedal aguas arriba, plantar árboles nativos en las veredas del centro, pasar el alumbrado público a LED, y construir un terraplén que desviaría el agua hacia un barrio vecino."]},"solucion":{}},{"slug":"aire-suelo-4.s7.p2","orden":2,"grupo":"aire-suelo-4.s7.p2","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas.","grupos":[{"id":"g1","nombre":"Adaptación"},{"id":"g2","nombre":"Mitigación"},{"id":"g3","nombre":"Mitigación y adaptación"},{"id":"g4","nombre":"Mala adaptación"}],"items":[{"id":"i1","texto":"Sistema de alerta temprana de crecidas"},{"id":"i2","texto":"Alumbrado público LED"},{"id":"i3","texto":"Conservar el humedal aguas arriba"},{"id":"i4","texto":"Terraplén que desvía el agua al barrio vecino"},{"id":"i5","texto":"Árboles nativos en las veredas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g4","i5":"g3"},"explicacion":"Un buen plan combina tipos de medidas y descarta las que trasladan el problema."}},{"slug":"aire-suelo-4.s7.p3","orden":3,"grupo":"aire-suelo-4.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los días de calor extremo pasaron de 4 a 11 por verano. ¿En qué porcentaje aumentaron? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"De 4 a 11 días de calor extremo por verano."},"solucion":{"valor":175,"tolerancia":3.5,"explicacion":"(11 − 4) ÷ 4 × 100 = 175 %. Casi se triplicaron: la adaptación al calor es urgente."}},{"slug":"aire-suelo-4.s7.p4","orden":4,"grupo":"aire-suelo-4.s7.p4","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las propuestas de mayor a menor prioridad para empezar.","items":[{"id":"i1","texto":"Sistema de alerta temprana"},{"id":"i2","texto":"Conservar el humedal aguas arriba"},{"id":"i3","texto":"Árboles nativos en las veredas"},{"id":"i4","texto":"Alumbrado LED"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero lo que salva vidas; después lo que reduce riesgos de fondo y suma beneficios. El terraplén queda afuera.","valores":{"i1":"protege vidas ya, bajo costo","i2":"reduce crecidas y guarda carbono","i3":"calor, carbono y biodiversidad","i4":"mitiga y ahorra dinero"}}},{"slug":"aire-suelo-4.s7.p5","orden":5,"grupo":"aire-suelo-4.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene descartar el terraplén propuesto?","opciones":[{"id":"o1","texto":"Traslada la inundación al barrio vecino"},{"id":"o2","texto":"Porque los terraplenes nunca sirven para nada"},{"id":"o3","texto":"Porque es una medida de mitigación"},{"id":"o4","texto":"Porque el río no se desborda nunca"}]},"solucion":{"clave":["o1"],"explicacion":"Proteger a unos a costa de otros es mala adaptación y genera conflictos.","por_opcion":{"o3":"No mitiga: es una obra de adaptación mal planteada."}}},{"slug":"aire-suelo-4.s7.p6","orden":6,"grupo":"aire-suelo-4.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir el plan, además de las obras? Marcá todo.","opciones":[{"id":"o1","texto":"Un protocolo para asistir a personas mayores en olas de calor"},{"id":"o2","texto":"Participación de los barrios en el diseño"},{"id":"o3","texto":"Indicadores para medir si el plan funciona"},{"id":"o4","texto":"Esperar a la próxima inundación para decidir"},{"id":"o5","texto":"Ocultar los mapas de riesgo para no alarmar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Un plan climático también es social: cuidar a los más vulnerables, participar y medir."}},{"slug":"aire-suelo-4.s7.p7","orden":7,"grupo":"aire-suelo-4.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como Villa Ribera emite muy poco, no tiene sentido que incluya medidas de mitigación.","razones":[{"id":"r1","texto":"Porque muchas medidas ahorran dinero o también adaptan"},{"id":"r2","texto":"Porque los pueblos chicos no emiten nada"},{"id":"r3","texto":"Porque la mitigación está prohibida en municipios"}]},"solucion":{"valor":false,"explicacion":"Las medidas de mitigación que ahorran dinero, como el LED, conviene hacerlas igual. Y muchas, como el humedal y los árboles, también adaptan.","clave":["r1"]}},{"slug":"aire-suelo-4.s7.p8","orden":8,"grupo":"aire-suelo-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El intendente presenta el plan. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Instalaremos un sistema de alerta de crecidas."},{"id":"s2","texto":"Rellenaremos el humedal para construir un barrio nuevo."},{"id":"s3","texto":"Plantaremos árboles nativos en las veredas del centro."},{"id":"s4","texto":"Las olas de calor no requieren ninguna acción."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan coherente no contradice en una línea lo que propone en otra.","por_opcion":{"s2":"El humedal amortigua crecidas: rellenarlo aumenta el riesgo.","s4":"Los días de calor extremo casi se triplicaron: hacen falta alertas y cuidados."}}}]}]}$ac$::jsonb);
